src/access/action-registry.ts.source:
/**
 * Registry of action IDs the platform knows about.
 *
 * Built-in actions are registered at module load (their static catalogue
 * lives in `action-registry-data.ts`). Plugins call `registerAccessAction()`
 * from their setup code so their custom permissions appear in the
 * role-builder action picker, audit logs, and the "My Permissions" view.
 *
 * Action IDs are colon-namespaced strings: `<resource>:<verb>` (e.g.
 * `posts:edit`). Subscopes are encoded in the verb (`posts:delete.any` vs
 * `posts:delete.own`) — the policy engine does not interpret these,
 * but UI pickers can group them.
 */

import { BUILT_IN_ACCESS_ACTIONS } from "./action-registry-data";
import type { ActionDefinition } from "./types";

const registry = new Map<string, ActionDefinition>();

export function registerAccessAction(def: ActionDefinition): void {
	if (registry.has(def.id) && registry.get(def.id)?.pluginId !== def.pluginId) {
		throw new Error(
			`Access action "${def.id}" is already registered by plugin "${
				registry.get(def.id)?.pluginId
			}". Plugins cannot redeclare actions owned by others.`,
		);
	}
	registry.set(def.id, def);
}

export function getAccessAction(id: string): ActionDefinition | undefined {
	return registry.get(id);
}

export function listAccessActions(): readonly ActionDefinition[] {
	return [...registry.values()].sort((a, b) => a.id.localeCompare(b.id));
}

/** Test helper. Do not call in production code. */
export function _resetAccessActionRegistryForTests(): void {
	registry.clear();
	registerBuiltInActions();
}

function registerBuiltInActions(): void {
	for (const def of BUILT_IN_ACCESS_ACTIONS) registry.set(def.id, def);
}

registerBuiltInActions();

src/access/d1-access-store.ts.source:
/**
 * D1 read path for the per-request access snapshot.
 *
 * Lives here (not in `request-context.ts`) so the SQL-containment arch
 * rule can keep .prepare() confined to the d1- and sqlite- adapter layer.
 * The repository in `repository.ts` owns sync writes against the access
 * tables; this module owns the async read path against Cloudflare D1.
 */

import type { D1DatabaseLike } from "../d1-database";
import type { AttributeValue, Condition, Effect, Policy } from "./types";

export interface AccessSnapshot {
	userId: string;
	isAdmin: boolean;
	roles: readonly string[];
	attributes: Readonly<Record<string, AttributeValue>>;
	policies: readonly Policy[];
}

export async function loadAccessSnapshotFromD1(
	db: D1DatabaseLike,
	email: string,
): Promise<AccessSnapshot | null> {
	const userRow = await db
		.prepare("SELECT id, is_admin FROM admin_users WHERE email = ? AND active = 1 LIMIT 1")
		.bind(email)
		.first<{ id: number; is_admin: number }>();
	if (!userRow) return null;

	const userId = userRow.id;
	const isAdmin = userRow.is_admin === 1;

	const [roleRows, attrRows, rolePolicyRows, userPolicyRows] = await Promise.all([
		db
			.prepare(
				"SELECT r.id, r.name FROM access_user_roles ur JOIN access_roles r ON r.id = ur.role_id WHERE ur.user_id = ?",
			)
			.bind(userId)
			.all<{ id: string; name: string }>(),
		db
			.prepare("SELECT key, value FROM access_user_attributes WHERE user_id = ?")
			.bind(userId)
			.all<{ key: string; value: string }>(),
		db
			.prepare(
				`SELECT rp.id, rp.role_id, rp.effect, rp.action, rp.condition_json, rp.priority, r.name AS role_name
					 FROM access_role_policies rp
					 JOIN access_user_roles ur ON ur.role_id = rp.role_id
					 JOIN access_roles r ON r.id = rp.role_id
					 WHERE ur.user_id = ?`,
			)
			.bind(userId)
			.all<RolePolicyRow>(),
		db
			.prepare(
				"SELECT id, effect, action, condition_json, priority FROM access_user_policies WHERE user_id = ?",
			)
			.bind(userId)
			.all<UserPolicyRow>(),
	]);

	const roleIds = (roleRows.results ?? []).map((r) => r.id);
	const attributes: Record<string, AttributeValue> = {};
	for (const r of attrRows.results ?? []) {
		attributes[r.key] = decodeAttribute(r.value);
	}

	const policies: Policy[] = [];
	for (const rp of rolePolicyRows.results ?? []) {
		policies.push({
			id: rp.id,
			effect: rp.effect,
			action: rp.action,
			condition: rp.condition_json ? (JSON.parse(rp.condition_json) as Condition) : undefined,
			priority: rp.priority,
			source: { kind: "role", roleId: rp.role_id, roleName: rp.role_name },
		});
	}
	for (const up of userPolicyRows.results ?? []) {
		policies.push({
			id: up.id,
			effect: up.effect,
			action: up.action,
			condition: up.condition_json ? (JSON.parse(up.condition_json) as Condition) : undefined,
			priority: up.priority,
			source: { kind: "direct" },
		});
	}

	return {
		userId: String(userId),
		isAdmin,
		roles: roleIds,
		attributes,
		policies,
	};
}

interface RolePolicyRow {
	id: string;
	role_id: string;
	role_name: string;
	effect: Effect;
	action: string;
	condition_json: string | null;
	priority: number;
}

interface UserPolicyRow {
	id: string;
	effect: Effect;
	action: string;
	condition_json: string | null;
	priority: number;
}

function decodeAttribute(raw: string): AttributeValue {
	try {
		return JSON.parse(raw) as AttributeValue;
	} catch {
		return raw;
	}
}

src/access/page-guard.ts.source:
/**
 * Page-frontmatter access guard.
 *
 * Replaces the legacy `if (!adminUser || adminUser.role !== "admin") return
 * Astro.redirect(...)` block with a single `await requiresAccess(Astro,
 * "<action>")` call. The guard loads `Astro.locals.access` lazily, evaluates
 * the requested ABAC action, and returns:
 *
 *   - `null` when the subject is allowed (caller continues rendering)
 *   - a `Response` redirect when the subject is unauthenticated or denied
 *
 * Astro frontmatter pattern:
 *
 *   const guard = await requiresAccess(Astro, "settings:edit");
 *   if (guard) return guard;
 *
 * Server-side enforcement is the source of truth. Nav-level filtering is a
 * UI mirror — never rely on hiding a leaf as a security control.
 */

import { logAccessDeny } from "./audit-deny";
import { DEFAULT_FORBIDDEN_PATH, DEFAULT_LOGIN_PATH } from "./page-guard-data.js";
import { getAccessContext } from "./request-context";
import type { Env, Resource } from "./types";

export interface RequiresAccessOptions {
	resource?: Resource;
	env?: Env;
	/** Override the redirect target on deny. Defaults to /ap-admin?error=insufficient-permissions. */
	forbiddenPath?: string;
	/** Override the redirect target when there is no authenticated user. Defaults to /ap-admin/login. */
	loginPath?: string;
}

type AstroLike = {
	locals: App.Locals;
	// Method syntax (not an arrow field) so `status` is checked bivariantly:
	// Astro's `redirect` types it as the narrow ValidRedirectStatus union, which
	// an arrow field's strict contravariance would reject here.
	redirect(path: string, status?: number): Response;
};

export async function requiresAccess(
	astro: AstroLike,
	action: string,
	options: RequiresAccessOptions = {},
): Promise<Response | null> {
	const access = await getAccessContext(astro);

	if (!access) {
		return astro.redirect(options.loginPath ?? DEFAULT_LOGIN_PATH);
	}

	const decision = access.can(action, options.resource, options.env);
	if (decision.decision === "deny") {
		await logAccessDeny(astro.locals, {
			subjectEmail: access.subject.email,
			action,
			decision,
		});
		const reason = encodeURIComponent(decision.reason);
		const fallback = `${DEFAULT_FORBIDDEN_PATH}&reason=${reason}`;
		return astro.redirect(options.forbiddenPath ?? fallback);
	}

	return null;
}

src/access/request-context.ts.source:
/**
 * Per-request access context.
 *
 * Resolves the active subject (id, email, isAdmin, roles, attributes) plus
 * the union of role + direct policies into a snapshot, then constructs a
 * synchronous PolicyEngine that closes over that snapshot. The result is
 * cached on `Astro.locals.access` so a single request only pays the load
 * cost once.
 *
 * Two storage paths are supported via `withLocalStoreFallback`:
 *  - Cloudflare D1: async snapshot loader in `d1-access-store.ts`.
 *  - Local sync sqlite: optional `access` extension on LocalAdminStoreModule.
 *    When the host app has not yet wired it (older consumers, harness),
 *    we degrade gracefully to an admin-only snapshot derived from
 *    `locals.adminUser` — admins bypass policy evaluation, so this keeps
 *    the runtime usable while consumers migrate.
 */

import { withLocalStoreFallback } from "../admin-store-dispatch";
import type { LocalAdminStoreModule } from "../local-runtime-modules";
import type { AuthUser } from "../platform-contracts";
import { isAuthUserAdmin } from "../platform-contracts";
import type { AccessSnapshot } from "./d1-access-store";
import { loadAccessSnapshotFromD1 } from "./d1-access-store";

export type { AccessSnapshot } from "./d1-access-store";

import { createPolicyEngine } from "./engine";
import type { Env, EvaluationResult, PolicyEngine, Resource, Subject } from "./types";

export interface AccessContext {
	subject: Subject;
	engine: PolicyEngine;
	can: (action: string, resource?: Resource, env?: Env) => EvaluationResult;
}

/**
 * Optional access surface that local sqlite admin stores can implement.
 * Cloudflare's D1 path goes through `d1-access-store.ts`; this interface is
 * what the in-process sync store provides.
 */
export interface LocalAccessStoreSurface {
	resolveAccessSnapshotByEmail(email: string): AccessSnapshot | null;
}

/**
 * Lazy resolver. Returns null when there is no authenticated admin user on
 * locals. Caches the resolved AccessContext on `locals.access` for the rest
 * of the request.
 */
export async function getAccessContext(astro: {
	locals: App.Locals;
}): Promise<AccessContext | null> {
	const locals = astro.locals as App.Locals & {
		access?: AccessContext;
		adminUser?: AuthUser & { name?: string };
	};
	if (locals.access) return locals.access;

	const adminUser = locals.adminUser;
	if (!adminUser?.email) return null;

	const snapshot = await loadAccessSnapshot(locals, adminUser);
	const ctx = buildContext(snapshot, adminUser);
	locals.access = ctx;
	return ctx;
}

function buildContext(snap: AccessSnapshot, user: AuthUser): AccessContext {
	const subject: Subject = {
		id: snap.userId,
		email: user.email,
		isAdmin: snap.isAdmin,
		roles: snap.roles,
		attributes: snap.attributes,
	};
	const engine = createPolicyEngine({
		resolvePoliciesForSubject: () => snap.policies,
	});
	return {
		subject,
		engine,
		can: (action, resource, env) => engine.can(subject, action, resource, env),
	};
}

async function loadAccessSnapshot(
	locals: App.Locals | null | undefined,
	adminUser: AuthUser,
): Promise<AccessSnapshot> {
	return withLocalStoreFallback(
		locals,
		async (db) => {
			const fromD1 = await loadAccessSnapshotFromD1(db, adminUser.email);
			if (fromD1) {
				// Honour the legacy admin flag too — covers DBs whose is_admin
				// migration hasn't run yet.
				return {
					...fromD1,
					isAdmin: fromD1.isAdmin || isAuthUserAdmin(adminUser),
				};
			}
			return adminOnlySnapshot(adminUser);
		},
		(store) => Promise.resolve(loadFromLocal(store, adminUser)),
	);
}

function loadFromLocal(store: LocalAdminStoreModule, adminUser: AuthUser): AccessSnapshot {
	const surface = (store as unknown as { access?: LocalAccessStoreSurface }).access;
	const fromStore = surface?.resolveAccessSnapshotByEmail(adminUser.email);
	if (fromStore) {
		const isAdmin = fromStore.isAdmin || isAuthUserAdmin(adminUser);
		return { ...fromStore, isAdmin };
	}
	return adminOnlySnapshot(adminUser);
}

function adminOnlySnapshot(adminUser: AuthUser): AccessSnapshot {
	return {
		userId: adminUser.id ?? `email:${adminUser.email}`,
		isAdmin: isAuthUserAdmin(adminUser),
		roles: [],
		attributes: {},
		policies: [],
	};
}

