src/adapters/appwrite.ts.source:
import {
	type AstropressHostedApiAdapterOptions,
	createAstropressHostedApiAdapter,
} from "../hosted-api-adapter";
import { createAstropressHostedPlatformAdapter } from "../hosted-platform-adapter";
import type { AstropressInMemoryPlatformAdapterOptions } from "../in-memory-platform-adapter";
import { stripTrailingSlashes } from "../path-helpers";
import type { AstropressPlatformAdapter } from "../platform-contracts";
import { FULL_STACK_CAPABILITIES } from "./adapter-record-helpers";

export interface AstropressAppwriteHostedConfig {
	endpoint: string;
	projectId: string;
	apiKey: string;
	databaseId?: string;
	bucketId?: string;
	apiBaseUrl: string;
	previewBaseUrl: string;
}

export type AstropressAppwriteAdapterOptions = Omit<
	AstropressInMemoryPlatformAdapterOptions,
	"capabilities"
> & {
	backingAdapter?: AstropressPlatformAdapter;
};

export function createAstropressAppwriteAdapter(options: AstropressAppwriteAdapterOptions = {}) {
	return createAstropressHostedPlatformAdapter({
		...options,
		providerName: "appwrite",
		defaultCapabilities: {
			...options.defaultCapabilities,
			...FULL_STACK_CAPABILITIES,
			hostPanel: options.defaultCapabilities?.hostPanel ?? {
				mode: "link",
				url: "https://cloud.appwrite.io",
				label: "Appwrite Console",
			},
		},
	});
}

export interface AstropressAppwriteHostedAdapterOptions extends AstropressAppwriteAdapterOptions {
	config?: AstropressAppwriteHostedConfig;
	env?: Record<string, string | undefined>;
	fetchImpl?: AstropressHostedApiAdapterOptions["fetchImpl"];
}

export function readAstropressAppwriteHostedConfig(
	env: Record<string, string | undefined> = process.env,
): AstropressAppwriteHostedConfig {
	const endpoint = env.APPWRITE_ENDPOINT?.trim();
	const projectId = env.APPWRITE_PROJECT_ID?.trim();
	const apiKey = env.APPWRITE_API_KEY?.trim();

	if (!endpoint || !projectId || !apiKey) {
		throw new Error(
			"Appwrite hosted config requires APPWRITE_ENDPOINT, APPWRITE_PROJECT_ID, and APPWRITE_API_KEY.",
		);
	}

	const base = stripTrailingSlashes(endpoint);
	const databaseId = env.APPWRITE_DATABASE_ID?.trim();
	const bucketId = env.APPWRITE_BUCKET_ID?.trim();
	return {
		endpoint,
		projectId,
		apiKey,
		...(databaseId && { databaseId }),
		...(bucketId && { bucketId }),
		apiBaseUrl: `${base}/functions/astropress`,
		previewBaseUrl: `${base}/console/project-${projectId}`,
	};
}

export function createAstropressAppwriteHostedAdapter(
	options: AstropressAppwriteHostedAdapterOptions = {},
) {
	const config = options.config ?? readAstropressAppwriteHostedConfig(options.env);
	const hostPanel = options.defaultCapabilities?.hostPanel ?? {
		mode: "link" as const,
		url: `https://cloud.appwrite.io/console/project-${config.projectId}`,
		label: "Appwrite Console",
	};

	if (
		!options.backingAdapter &&
		!options.content &&
		!options.media &&
		!options.revisions &&
		!options.auth
	) {
		return createAstropressHostedApiAdapter({
			providerName: "appwrite",
			apiBaseUrl: config.apiBaseUrl,
			accessToken: config.apiKey,
			previewBaseUrl: `${stripTrailingSlashes(config.previewBaseUrl)}/preview`,
			fetchImpl: options.fetchImpl,
			defaultCapabilities: {
				...options.defaultCapabilities,
				...FULL_STACK_CAPABILITIES,
				hostPanel,
			},
		});
	}

	return createAstropressHostedPlatformAdapter({
		...options,
		providerName: "appwrite",
		defaultCapabilities: {
			...options.defaultCapabilities,
			...FULL_STACK_CAPABILITIES,
			hostPanel,
		},
		preview: options.preview ?? {
			async create() {
				return {
					url: `${stripTrailingSlashes(config.previewBaseUrl)}/preview`,
				};
			},
		},
	});
}

src/adapters/cloudflare-helpers-data.ts.source:
// stryker-disable-file: data-only — SQL-string constants for the Cloudflare/D1
// adapter. Mutants on these literals are caught by integration tests against the
// live D1 schema, not by Stryker (adapter unit tests use a mock D1 driver, so a
// mutated query string is unobservable); vitest worker-cache also makes the
// static-true variants unkillable per project-static-mutants-empirical.

export const SQL_UPSERT_REDIRECT =
	"INSERT INTO redirect_rules (source_path, target_path, status_code, created_by, deleted_at) VALUES (?, ?, ?, ?, NULL) ON CONFLICT(source_path) DO UPDATE SET target_path = excluded.target_path, status_code = excluded.status_code, created_by = excluded.created_by, deleted_at = NULL";
export const SQL_UPSERT_SETTINGS =
	"INSERT INTO site_settings (id, site_title, site_tagline, donation_url, newsletter_enabled, comments_default_policy, admin_slug, updated_at, updated_by) VALUES (1, ?, ?, ?, ?, ?, ?, ?, ?) ON CONFLICT(id) DO UPDATE SET site_title = excluded.site_title, site_tagline = excluded.site_tagline, donation_url = excluded.donation_url, newsletter_enabled = excluded.newsletter_enabled, comments_default_policy = excluded.comments_default_policy, admin_slug = excluded.admin_slug, updated_at = excluded.updated_at, updated_by = excluded.updated_by";
export const SQL_UPSERT_TRANSLATION =
	"INSERT INTO translation_overrides (route, state, updated_at, updated_by) VALUES (?, ?, ?, ?) ON CONFLICT(route) DO UPDATE SET state = excluded.state, updated_at = excluded.updated_at, updated_by = excluded.updated_by";
export const SQL_INSERT_CONTENT =
	"INSERT INTO content_entries (slug, legacy_url, title, kind, template_key, source_html_path, updated_at, body, summary, seo_title, meta_description, og_title, og_description, og_image) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)";
export const SQL_UPSERT_OVERRIDE =
	"INSERT INTO content_overrides (slug, title, status, scheduled_at, body, seo_title, meta_description, excerpt, og_title, og_description, og_image, canonical_url_override, robots_directive, updated_at, updated_by) VALUES (?, ?, ?, NULL, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?) ON CONFLICT(slug) DO UPDATE SET title = excluded.title, status = excluded.status, body = excluded.body, seo_title = excluded.seo_title, meta_description = excluded.meta_description, excerpt = excluded.excerpt, og_title = excluded.og_title, og_description = excluded.og_description, og_image = excluded.og_image, canonical_url_override = excluded.canonical_url_override, robots_directive = excluded.robots_directive, updated_at = excluded.updated_at, updated_by = excluded.updated_by";
export const SQL_UPSERT_MEDIA =
	"INSERT INTO media_assets (id, source_url, local_path, mime_type, file_size, alt_text, title, uploaded_at, uploaded_by, deleted_at) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, NULL) ON CONFLICT(id) DO UPDATE SET source_url = excluded.source_url, local_path = excluded.local_path, mime_type = excluded.mime_type, file_size = excluded.file_size, alt_text = excluded.alt_text, title = excluded.title, deleted_at = NULL";

src/adapters/local.ts.source:
import type { AstropressPlatformAdapter } from "../platform-contracts";
import { resolveAstropressLocalProviderFromEnv } from "../project-env";
import { type AstropressSqliteAdapterOptions, createAstropressSqliteAdapter } from "./sqlite";
import {
	type AstropressSupabaseSqliteAdapterOptions,
	createAstropressSupabaseSqliteAdapter,
} from "./supabase-sqlite";

export type AstropressLocalProviderKind = "sqlite" | "supabase";

export type AstropressLocalAdapterOptions = AstropressSqliteAdapterOptions & {
	provider?: AstropressLocalProviderKind;
	env?: Record<string, string | undefined>;
};

export function createAstropressLocalAdapter(
	options: AstropressLocalAdapterOptions = {},
): AstropressPlatformAdapter {
	const provider =
		options.provider ?? resolveAstropressLocalProviderFromEnv(options.env ?? process.env);

	if (provider === "supabase") {
		return createAstropressSupabaseSqliteAdapter(
			options satisfies AstropressSupabaseSqliteAdapterOptions,
		);
	}

	return createAstropressSqliteAdapter(options);
}

src/adapters/project.ts.source:
import type { AstropressPlatformAdapter } from "../platform-contracts";
import { resolveAstropressProjectEnvContract } from "../project-env";
import { type AstropressHostedAdapterOptions, createAstropressHostedAdapter } from "./hosted";
import { type AstropressLocalAdapterOptions, createAstropressLocalAdapter } from "./local";

export type AstropressProjectAdapterMode = "local" | "hosted";

export interface AstropressProjectAdapterOptions {
	mode?: AstropressProjectAdapterMode;
	env?: Record<string, string | undefined>;
	local?: AstropressLocalAdapterOptions;
	hosted?: AstropressHostedAdapterOptions;
}

export function resolveAstropressProjectAdapterMode(
	env: Record<string, string | undefined> = process.env,
): AstropressProjectAdapterMode {
	return env.ASTROPRESS_RUNTIME_MODE?.trim() === "hosted" ? "hosted" : "local";
}

export function createAstropressProjectAdapter(
	options: AstropressProjectAdapterOptions = {},
): AstropressPlatformAdapter {
	const env = options.env ?? process.env;
	const mode = options.mode ?? resolveAstropressProjectAdapterMode(env);
	const projectEnv = resolveAstropressProjectEnvContract(env);

	if (mode === "hosted") {
		return createAstropressHostedAdapter({
			env,
			provider: options.hosted?.provider ?? projectEnv.hostedProvider,
			...options.hosted,
		} as AstropressHostedAdapterOptions);
	}

	return createAstropressLocalAdapter({
		env,
		provider: options.local?.provider ?? projectEnv.localProvider,
		...options.local,
	});
}

src/adapters/supabase-sqlite.ts.source:
import type { AstropressSqliteAdapterOptions } from "./sqlite";
import { createAstropressSqliteAdapter } from "./sqlite.js";
import { createAstropressSupabaseAdapter } from "./supabase";

export type AstropressSupabaseSqliteAdapterOptions = AstropressSqliteAdapterOptions;

export function createAstropressSupabaseSqliteAdapter(
	options: AstropressSupabaseSqliteAdapterOptions = {},
) {
	return createAstropressSupabaseAdapter({
		backingAdapter: createAstropressSqliteAdapter(options),
	});
}

src/admin-action-publish.ts.source:
/**
 * Publish action — triggers a new static production build via the configured deploy hook.
 *
 * Each platform uses a different webhook mechanism:
 * - GitHub Actions: repository_dispatch event
 * - Cloudflare Pages: POST to deploy hook URL
 * - Vercel: POST to deploy hook URL
 * - Netlify: POST to build hook URL
 * - Render: POST to deploy hook URL
 */

import { withLocalStoreFallback } from "./admin-store-dispatch";
import { recordD1Audit } from "./d1-audit";
import type { Actor } from "./persistence-types";

export interface PublishTriggerResult {
	ok: boolean;
	buildId?: string;
	statusUrl?: string;
	error?: string;
}

export type DeployHookType =
	| "cloudflare-pages"
	| "vercel"
	| "netlify"
	| "render"
	| "github-actions";

export interface DeployHookConfig {
	type: DeployHookType;
	/** Environment variables map (from process.env or explicit) */
	env: Record<string, string | undefined>;
}

async function triggerCloudflarePages(
	env: Record<string, string | undefined>,
): Promise<PublishTriggerResult> {
	const hookUrl = env.CF_PAGES_DEPLOY_HOOK_URL;
	if (!hookUrl) {
		return { ok: false, error: "CF_PAGES_DEPLOY_HOOK_URL is not set" };
	}

	const res = await fetch(hookUrl, { method: "POST" });
	if (!res.ok) {
		return {
			ok: false,
			error: `Cloudflare Pages deploy hook returned ${res.status}`,
		};
	}

	// audit-boundary: opaque-passthrough -- module-boundary value; narrowed at consumer
	const data = (await res.json().catch(() => ({}))) as Record<string, unknown>;
	return {
		ok: true,
		buildId: typeof data.id === "string" ? data.id : undefined,
	};
}

async function triggerVercel(
	env: Record<string, string | undefined>,
): Promise<PublishTriggerResult> {
	const hookUrl = env.VERCEL_DEPLOY_HOOK_URL;
	if (!hookUrl) {
		return { ok: false, error: "VERCEL_DEPLOY_HOOK_URL is not set" };
	}

	const res = await fetch(hookUrl, { method: "POST" });
	if (!res.ok) {
		return { ok: false, error: `Vercel deploy hook returned ${res.status}` };
	}

	// audit-boundary: opaque-passthrough -- module-boundary value; narrowed at consumer
	const data = (await res.json().catch(() => ({}))) as Record<string, unknown>;
	// audit-boundary: opaque-passthrough -- module-boundary value; narrowed at consumer
	const job = (data.job ?? {}) as Record<string, unknown>;
	return {
		ok: true,
		buildId: typeof job.id === "string" ? job.id : undefined,
	};
}

async function triggerNetlify(
	env: Record<string, string | undefined>,
): Promise<PublishTriggerResult> {
	const hookUrl = env.NETLIFY_BUILD_HOOK_URL;
	if (!hookUrl) {
		return { ok: false, error: "NETLIFY_BUILD_HOOK_URL is not set" };
	}

	const res = await fetch(hookUrl, { method: "POST", body: "{}" });
	if (!res.ok) {
		return { ok: false, error: `Netlify build hook returned ${res.status}` };
	}

	return { ok: true };
}

async function triggerRender(
	env: Record<string, string | undefined>,
): Promise<PublishTriggerResult> {
	const hookUrl = env.RENDER_DEPLOY_HOOK_URL;
	if (!hookUrl) {
		return { ok: false, error: "RENDER_DEPLOY_HOOK_URL is not set" };
	}

	const res = await fetch(hookUrl, { method: "POST" });
	if (!res.ok) {
		return { ok: false, error: `Render deploy hook returned ${res.status}` };
	}

	return { ok: true };
}

async function triggerGitHubActions(
	env: Record<string, string | undefined>,
): Promise<PublishTriggerResult> {
	const token = env.GH_TOKEN;
	const repo = env.GH_REPO; // format: "owner/repo"

	if (!token || !repo) {
		return {
			ok: false,
			error: "GH_TOKEN and GH_REPO must both be set for GitHub Actions deploy",
		};
	}

	const [owner, repoName] = repo.split("/");
	if (!owner || !repoName) {
		return { ok: false, error: 'GH_REPO must be in "owner/repo" format' };
	}

	const url = `https://api.github.com/repos/${owner}/${repoName}/dispatches`;
	const res = await fetch(url, {
		method: "POST",
		headers: {
			Authorization: `Bearer ${token}`,
			Accept: "application/vnd.github.v3+json",
			"Content-Type": "application/json",
			"X-GitHub-Api-Version": "2022-11-28",
		},
		body: JSON.stringify({ event_type: "astropress-publish" }),
	});

	if (res.status === 204) {
		return { ok: true };
	}

	return { ok: false, error: `GitHub Actions dispatch returned ${res.status}` };
}

/**
 * Trigger a static production build using the configured deploy hook.
 */
export async function triggerPublish(config: DeployHookConfig): Promise<PublishTriggerResult> {
	switch (config.type) {
		case "cloudflare-pages":
			return triggerCloudflarePages(config.env);
		case "vercel":
			return triggerVercel(config.env);
		case "netlify":
			return triggerNetlify(config.env);
		case "render":
			return triggerRender(config.env);
		case "github-actions":
			return triggerGitHubActions(config.env);
		default:
			return { ok: false, error: `Unknown deploy hook type: ${config.type}` };
	}
}

export interface PublishAuditPayload {
	hookType: DeployHookType;
	result: PublishTriggerResult;
}

/**
 * Persist a trusted audit record describing a publish trigger. The dashboard
 * surfaces the latest record so editors can see the most recent build status
 * without trusting query-string state from the redirect.
 */
export async function recordPublishAudit(
	locals: App.Locals | null | undefined,
	actor: Actor,
	payload: PublishAuditPayload,
): Promise<void> {
	const { hookType, result } = payload;
	const action = result.ok ? "deployment.trigger" : "deployment.failure";
	const summary = result.ok
		? `Triggered ${hookType} publish${result.buildId ? ` (build ${result.buildId})` : ""}.`
		: `${hookType} publish failed: ${result.error ?? "Unknown error"}`;
	const resourceId = result.buildId ?? hookType;

	await withLocalStoreFallback(
		locals,
		async () => {
			await recordD1Audit(locals, actor, action, "deployment", resourceId, summary);
		},
		async (store) => {
			await store.recordAuditEvent({
				userEmail: actor.email,
				action,
				resourceType: "deployment",
				resourceId,
				summary,
			});
		},
	);
}

/**
 * Resolve the deploy hook config from the process environment.
 * Returns null if no deploy hook is configured.
 */
export function resolveDeployHookFromEnv(
	env: Record<string, string | undefined> = process.env as Record<string, string | undefined>,
): DeployHookConfig | null {
	if (env.CF_PAGES_DEPLOY_HOOK_URL) {
		return { type: "cloudflare-pages", env };
	}
	if (env.VERCEL_DEPLOY_HOOK_URL) {
		return { type: "vercel", env };
	}
	if (env.NETLIFY_BUILD_HOOK_URL) {
		return { type: "netlify", env };
	}
	if (env.RENDER_DEPLOY_HOOK_URL) {
		return { type: "render", env };
	}
	if (env.GH_TOKEN && env.GH_REPO) {
		return { type: "github-actions", env };
	}
	return null;
}

