export interface AstropressResolvedAdminUiConfig {
	branding: {
		appName: string;
		productName: string;
		shellName: string;
		logoSrc: string | null;
		logoHref: string;
		logoAlt: string;
		faviconHref: string | null;
		stylesheetHref: string | null;
	};
	labels: {
		sidebarTitle: string;
		signedInAsPrefix: string;
		signOut: string;
		themeToggleDark: string;
		themeToggleLight: string;
		loginHeading: string;
		loginDescription: string;
		loginSubmit: string;
		loginEmailLabel: string;
		loginPasswordLabel: string;
		forgotPassword: string;
		invalidCredentials: string;
		rateLimited: string;
		challengeRequired: string;
		passwordResetSuccess: string;
		invitationAcceptedSuccess: string;
		acceptInvitationHeading: string;
		acceptInvitationDescription: string;
		acceptInvitationSubmit: string;
		resetPasswordRequestHeading: string;
		resetPasswordRequestDescription: string;
		resetPasswordTokenHeading: string;
		resetPasswordTokenDescription: string;
		resetPasswordRequestSubmit: string;
		resetPasswordTokenSubmit: string;
		backToLogin: string;
		changeLanguage: string;
	};
	navigation: Record<AstropressAdminNavKey, string>;
}

function mergeWithDefaults() {
	const cmsConfig = peekCmsConfig();
	const admin = cmsConfig?.admin;

	return {
		branding: {
			...defaultAdminUiConfig.branding,
			...admin?.branding,
		},
		labels: {
			...defaultAdminUiConfig.labels,
			...admin?.labels,
		},
		navigation: {
			...defaultAdminUiConfig.navigation,
			...admin?.navigation,
		},
	} satisfies AstropressResolvedAdminUiConfig;
}

/**
 * Merge host-provided CMS config with Astropress defaults to produce a complete
 * admin UI configuration object ready for use in admin layout templates.
 *
 * @example
 * ```ts
 * import { resolveAstropressAdminUiConfig } from "@astropress-diy/astropress";
 *
 * const { branding, labels, navigation } = resolveAstropressAdminUiConfig();
 * console.log(branding.appName); // "Astropress" or host-overridden value
 * ```
 */
export function resolveAstropressAdminUiConfig(
	locale?: AdminLocale,
): AstropressResolvedAdminUiConfig {
	const merged = mergeWithDefaults();
	const translated = locale ? applyTranslations(merged, locale) : merged;
	return {
		branding: {
			...translated.branding,
			shellName: translated.branding.shellName || translated.branding.productName,
			logoAlt: translated.branding.logoAlt || translated.branding.productName,
			logoHref: translated.branding.logoHref || "/ap-admin",
			stylesheetHref: translated.branding.stylesheetHref || null,
		},
		labels: translated.labels,
		navigation: translated.navigation,
	};
}

function applyTranslations(
	merged: AstropressResolvedAdminUiConfig,
	locale: AdminLocale,
): AstropressResolvedAdminUiConfig {
	// Pull every value through getAdminLabel so missing keys fall back to
	// English instead of "undefined" — this is the i18n leak guard. The
	// per-property key tables live in admin-ui-translation-keys.ts so the
	// mutation surface in this file stays focused on logic rather than the
	// long list of literal key names.
	const tr = (key: AdminLabelKey, fallback: string): string =>
		getAdminLabel(key, locale) || fallback;
	const labels = { ...merged.labels } as Record<string, string>;
	for (const [outKey, labelKey] of LABEL_TRANSLATION_KEYS) {
		labels[outKey] = tr(labelKey, labels[outKey] ?? "");
	}
	const navigation = { ...merged.navigation } as Record<string, string>;
	for (const [outKey, labelKey] of NAVIGATION_TRANSLATION_KEYS) {
		navigation[outKey] = tr(labelKey, navigation[outKey] ?? "");
	}
	return {
		branding: merged.branding,
		labels: labels as AstropressResolvedAdminUiConfig["labels"],
		navigation: navigation as AstropressResolvedAdminUiConfig["navigation"],
	};
}

src/auth-emergency-revoke-ops.ts.source:
import { DatabaseSync } from "node:sqlite";
import {
	recordEmergencyRevokeAuditEvent,
	revokeApiTokensInDb,
	revokeSessionsInDb,
} from "./sqlite-runtime/auth-emergency-revoke.js";

export type AuthRevokeScope = "all" | "sessions" | "tokens";

export interface AuthEmergencyRevokeInput {
	dbPath: string;
	scope: AuthRevokeScope;
	userEmail?: string;
}

export interface AuthEmergencyRevokeReport {
	dbPath: string;
	scope: AuthRevokeScope;
	userEmail: string | null;
	sessionsRevoked: number;
	tokensRevoked: number;
}

export function runAuthEmergencyRevokeForCli(
	input: AuthEmergencyRevokeInput,
): AuthEmergencyRevokeReport {
	const { dbPath, scope, userEmail } = input;
	const db = new DatabaseSync(dbPath);

	try {
		let sessionsRevoked = 0;
		let tokensRevoked = 0;

		if (scope === "all" || scope === "sessions") {
			sessionsRevoked = revokeSessionsInDb(db, userEmail);
		}

		if (scope === "all" || scope === "tokens") {
			tokensRevoked = revokeApiTokensInDb(db);
		}

		recordEmergencyRevokeAuditEvent(db, scope, userEmail ?? null, sessionsRevoked, tokensRevoked);

		return {
			dbPath,
			scope,
			userEmail: userEmail ?? null,
			sessionsRevoked,
			tokensRevoked,
		};
	} finally {
		db.close();
	}
}

src/build-time-content-loader.ts.source:
import type {
	AstropressPlatformAdapter,
	ContentStoreRecord,
	ReadableContentKind,
} from "./platform-contracts";

export interface AstropressBuildTimeLoaderOptions {
	/** Locale to filter content by. Defaults to all locales. */
	locale?: string;
}

/**
 * A lazy loader that fetches a collection of records from the provider at
 * build time and returns them for use in Astro content collections.
 */
export interface AstropressContentLoader {
	/**
	 * Fetch all records of this kind from the provider.
	 * By default, only "published" records are returned.
	 */
	load(): Promise<ContentStoreRecord[]>;
	/** The content kind this loader targets. */
	readonly kind: ReadableContentKind;
}

/**
 * Create build-time content collection loaders for a given provider adapter.
 *
 * Each loader calls ContentStore.list with status "published" so that draft
 * content is never included in the static production build.
 *
 * @example
 * ```ts
 * // astro.config.mjs (public site project)
 * import { defineCollection } from "astro:content";
 * import { createAstropressBuildTimeLoader } from "@astropress-diy/astropress";
 * import { adapter } from "./src/astropress/local-runtime-modules";
 *
 * const loader = createAstropressBuildTimeLoader(adapter);
 *
 * export const collections = {
 *   posts: defineCollection({ loader: loader.posts() }),
 *   pages: defineCollection({ loader: loader.pages() }),
 * };
 * ```
 */
export function createAstropressBuildTimeLoader(
	provider: AstropressPlatformAdapter,
	options: AstropressBuildTimeLoaderOptions = {},
): {
	posts(): AstropressContentLoader;
	pages(): AstropressContentLoader;
} {
	function makeLoader(kind: "post" | "page"): AstropressContentLoader {
		return {
			kind,
			async load() {
				const records = await provider.content.list(kind, {
					status: "published",
					locale: options.locale,
				});
				return records;
			},
		};
	}

	return {
		posts: () => makeLoader("post"),
		pages: () => makeLoader("page"),
	};
}

