import { stat } from "node:fs/promises";
import path from "node:path";
import type {
	AstropressWordPressImportLocalApplyReport,
	AstropressWordPressImportPlan,
} from "../platform-contracts";
import { createAstropressSqliteAdminRuntime } from "../sqlite-admin-runtime";
import { createDefaultAstropressSqliteSeedToolkit } from "../sqlite-bootstrap";
import {
	SQL_SELECT_AUTHOR_ID,
	SQL_SELECT_CATEGORY_ID,
	SQL_SELECT_TAG_ID,
	SQL_UPDATE_ENTRY_LEGACY,
	SQL_UPDATE_ENTRY_LEGACY_FULL,
	SQL_UPSERT_AUTHOR,
	SQL_UPSERT_CATEGORY,
	SQL_UPSERT_COMMENT,
	SQL_UPSERT_MEDIA,
	SQL_UPSERT_REDIRECT,
	SQL_UPSERT_TAG,
	WORDPRESS_IMPORT_ACTOR,
} from "./wordpress-apply-data.js";
import type { ParsedBundle } from "./wordpress-xml.js";

export function resolveLocalAdminDbPath(workspaceRoot: string, adminDbPath?: string) {
	if (adminDbPath) {
		return path.isAbsolute(adminDbPath) ? adminDbPath : path.join(workspaceRoot, adminDbPath);
	}
	return createDefaultAstropressSqliteSeedToolkit().getDefaultAdminDbPath(workspaceRoot);
}

export async function fileSizeOrNull(targetPath: string) {
	try {
		const details = await stat(targetPath);
		return details.size;
	} catch {
		return null;
	}
}

type AdminDb = ReturnType<
	ReturnType<typeof createDefaultAstropressSqliteSeedToolkit>["openSeedDatabase"]
>;
type AdminRuntime = ReturnType<typeof createAstropressSqliteAdminRuntime>;

function importTerms(
	db: AdminDb,
	bundle: ParsedBundle,
): {
	categoryIdsBySlug: Map<string, number>;
	tagIdsBySlug: Map<string, number>;
} {
	const upsertCategory = db.prepare(SQL_UPSERT_CATEGORY);
	const upsertTag = db.prepare(SQL_UPSERT_TAG);
	const selectCategoryId = db.prepare(SQL_SELECT_CATEGORY_ID);
	const selectTagId = db.prepare(SQL_SELECT_TAG_ID);
	const categoryIdsBySlug = new Map<string, number>();
	const tagIdsBySlug = new Map<string, number>();
	for (const term of bundle.terms) {
		if (term.kind === "category") {
			upsertCategory.run(term.slug, term.name, null);
			const row = selectCategoryId.get(term.slug) as { id: number } | undefined;
			if (row) categoryIdsBySlug.set(term.slug, row.id);
		} else {
			upsertTag.run(term.slug, term.name, null);
			const row = selectTagId.get(term.slug) as { id: number } | undefined;
			if (row) tagIdsBySlug.set(term.slug, row.id);
		}
	}
	return { categoryIdsBySlug, tagIdsBySlug };
}

function importContentRecords(
	db: AdminDb,
	runtime: AdminRuntime,
	bundle: ParsedBundle,
	authorIdsByLogin: Map<string, number>,
	categoryIdsBySlug: Map<string, number>,
	tagIdsBySlug: Map<string, number>,
): Map<string, string> {
	const contentRouteByImportId = new Map<string, string>();
	for (const record of bundle.contentRecords) {
		const existing = runtime.sqliteAdminStore.content.getContentState(record.slug);
		const contentStatus =
			record.status === "archived" ? "archived" : record.status === "draft" ? "draft" : "published";
		const authorIds = record.authorLogins
			.map((l) => authorIdsByLogin.get(l))
			.filter((v): v is number => typeof v === "number");
		const categoryIds = record.categorySlugs
			.map((s) => categoryIdsBySlug.get(s))
			.filter((v): v is number => typeof v === "number");
		const tagIds = record.tagSlugs
			.map((s) => tagIdsBySlug.get(s))
			.filter((v): v is number => typeof v === "number");
		const revisionInput = {
			title: record.title,
			status: contentStatus,
			body: record.body,
			seoTitle: record.title,
			metaDescription: record.excerpt ?? record.title,
			excerpt: record.excerpt,
			authorIds,
			categoryIds,
			tagIds,
			revisionNote: `WordPress import ${record.legacyId}`,
		};

		if (existing) {
			const result = runtime.sqliteAdminStore.content.saveContentState(
				record.slug,
				revisionInput,
				WORDPRESS_IMPORT_ACTOR,
			);
			if (!result.ok) throw new Error(result.error);
			db.prepare(SQL_UPDATE_ENTRY_LEGACY).run(
				record.legacyUrl,
				record.excerpt ?? "",
				record.kind,
				record.slug,
			);
		} else {
			const created = runtime.sqliteAdminStore.content.createContentRecord(
				{
					title: record.title,
					slug: record.slug,
					legacyUrl: record.legacyUrl,
					body: record.body,
					summary: record.excerpt ?? "",
					status: contentStatus,
					seoTitle: record.title,
					metaDescription: record.excerpt ?? record.title,
					excerpt: record.excerpt,
				},
				WORDPRESS_IMPORT_ACTOR,
			);
			if (!created.ok) throw new Error(created.error);
			const saved = runtime.sqliteAdminStore.content.saveContentState(
				record.slug,
				revisionInput,
				WORDPRESS_IMPORT_ACTOR,
			);
			if (!saved.ok) throw new Error(saved.error);
			db.prepare(SQL_UPDATE_ENTRY_LEGACY_FULL).run(
				record.kind,
				record.legacyUrl,
				record.excerpt ?? "",
				record.slug,
			);
		}
		contentRouteByImportId.set(record.id, record.legacyUrl);
		contentRouteByImportId.set(record.legacyId, record.legacyUrl);
	}
	return contentRouteByImportId;
}

async function importMediaAssets(
	db: AdminDb,
	bundle: ParsedBundle,
	artifactDir: string | undefined,
) {
	const upsertMedia = db.prepare(SQL_UPSERT_MEDIA);
	for (const asset of bundle.mediaAssets) {
		const downloadedPath = artifactDir
			? path.join(artifactDir, "downloads", path.basename(asset.filename))
			: undefined;
		const hasDownloadedFile = downloadedPath
			? (await fileSizeOrNull(downloadedPath)) !== null
			: false;
		const localPath = hasDownloadedFile ? (downloadedPath as string) : asset.legacyUrl;
		upsertMedia.run(
			asset.id,
			asset.sourceUrl,
			localPath,
			asset.mimeType,
			hasDownloadedFile ? await fileSizeOrNull(downloadedPath as string) : null,
			"",
			asset.title,
			WORDPRESS_IMPORT_ACTOR.email,
		);
	}
}

export async function applyImportToLocalRuntime(input: {
	bundle: ParsedBundle;
	artifactDir?: string;
	workspaceRoot: string;
	adminDbPath?: string;
	plan: AstropressWordPressImportPlan;
}): Promise<AstropressWordPressImportLocalApplyReport> {
	const seedToolkit = createDefaultAstropressSqliteSeedToolkit();
	const resolvedDbPath = resolveLocalAdminDbPath(input.workspaceRoot, input.adminDbPath);
	seedToolkit.seedDatabase({
		dbPath: resolvedDbPath,
		workspaceRoot: input.workspaceRoot,
	});

	const db = seedToolkit.openSeedDatabase(resolvedDbPath);
	const runtime = createAstropressSqliteAdminRuntime({ getDatabase: () => db });

	try {
		db.exec("BEGIN");

		const upsertAuthor = db.prepare(SQL_UPSERT_AUTHOR);
		const selectAuthorId = db.prepare(SQL_SELECT_AUTHOR_ID);
		const authorIdsByLogin = new Map<string, number>();
		if (input.plan.includeUsers) {
			for (const author of input.bundle.authors) {
				upsertAuthor.run(author.login, author.displayName, null);
				const row = selectAuthorId.get(author.login) as { id: number } | undefined;
				if (row) authorIdsByLogin.set(author.login, row.id);
			}
		}

		const { categoryIdsBySlug, tagIdsBySlug } = importTerms(db, input.bundle);
		const contentRouteByImportId = importContentRecords(
			db,
			runtime,
			input.bundle,
			authorIdsByLogin,
			categoryIdsBySlug,
			tagIdsBySlug,
		);

		const upsertComment = db.prepare(SQL_UPSERT_COMMENT);
		const upsertRedirect = db.prepare(SQL_UPSERT_REDIRECT);
		if (input.plan.includeComments) {
			for (const comment of input.bundle.comments) {
				upsertComment.run(
					comment.id,
					comment.authorName,
					comment.authorEmail ?? null,
					comment.body,
					contentRouteByImportId.get(comment.recordId) ?? "/",
					comment.status,
					"legacy-readonly",
					comment.createdAt ?? new Date().toISOString(),
				);
			}
		}

		if (input.plan.includeMedia) {
			await importMediaAssets(db, input.bundle, input.artifactDir);
		}

		for (const redirect of input.bundle.redirects) {
			upsertRedirect.run(
				redirect.sourcePath,
				redirect.targetPath,
				301,
				WORDPRESS_IMPORT_ACTOR.email,
			);
		}

		db.exec("COMMIT");
		return {
			runtime: "sqlite-local",
			workspaceRoot: input.workspaceRoot,
			adminDbPath: resolvedDbPath,
			appliedRecords: input.bundle.contentRecords.length,
			appliedMedia: input.plan.includeMedia ? input.bundle.mediaAssets.length : 0,
			appliedComments: input.plan.includeComments ? input.bundle.comments.length : 0,
			appliedUsers: input.plan.includeUsers ? input.bundle.authors.length : 0,
			appliedRedirects: input.bundle.redirects.length,
		};
	} catch (error) {
		db.exec("ROLLBACK");
		throw error;
	} finally {
		db.close();
	}
}

src/import/wordpress.ts.source:
import { mkdir, readFile, writeFile } from "node:fs/promises";
import path from "node:path";
import type {
	AstropressWordPressImportArtifacts,
	AstropressWordPressImportInventory,
	AstropressWordPressImportPlan,
	AstropressWordPressImportReport,
	ImportSource,
} from "../platform-contracts";
import { downloadMediaToFile } from "./download-media.js";
import { applyImportToLocalRuntime, fileSizeOrNull } from "./wordpress-apply.js";
import type { ParsedBundle } from "./wordpress-xml.js";
import { detectUnsupportedPatterns, parseWordPressExport } from "./wordpress-xml.js";

export interface AstropressWordPressImportSourceOptions {
	sourceUrl?: string;
}

type DownloadState = {
	completed: string[];
	failed: Array<{ id: string; sourceUrl?: string; reason: string }>;
};

async function readDownloadState(downloadStateFile: string): Promise<DownloadState> {
	try {
		return JSON.parse(await readFile(downloadStateFile, "utf8")) as DownloadState;
	} catch {
		return { completed: [], failed: [] };
	}
}

async function writeJsonArtifact(targetPath: string, value: unknown) {
	await writeFile(targetPath, `${JSON.stringify(value, null, 2)}\n`, "utf8");
}

async function downloadMediaAssets(
	mediaAssets: ParsedBundle["mediaAssets"],
	artifactDir: string,
	resumeFrom?: string,
) {
	const downloadsDir = path.join(artifactDir, "downloads");
	const downloadStateFile = path.join(artifactDir, "download-state.json");
	await mkdir(downloadsDir, { recursive: true });

	const state = await readDownloadState(resumeFrom || downloadStateFile);
	const completed = new Set(state.completed);
	const failed: DownloadState["failed"] = [...state.failed];
	let downloadedMedia = 0;

	for (const asset of mediaAssets) {
		const assetTarget = path.join(downloadsDir, path.basename(asset.filename));
		if (completed.has(asset.id) && (await fileSizeOrNull(assetTarget)) !== null) continue;
		try {
			await downloadMediaToFile(asset.sourceUrl, assetTarget);
			completed.add(asset.id);
			downloadedMedia += 1;
		} catch (error) {
			failed.push({
				id: asset.id,
				sourceUrl: asset.sourceUrl,
				reason: error instanceof Error ? error.message : "Unknown media download error",
			});
		}
	}

	const normalizedState: DownloadState = {
		completed: [...completed].sort(),
		failed: failed.filter(
			(e, i, all) => all.findIndex((c) => c.id === e.id && c.reason === e.reason) === i,
		),
	};
	await writeJsonArtifact(downloadStateFile, normalizedState);
	return {
		downloadStateFile,
		downloadedMedia,
		failedMedia: normalizedState.failed,
	};
}

async function parseImportInput(input: Parameters<ImportSource["importWordPress"]>[0]) {
	if (!input.exportFile) throw new Error("WordPress import requires an `exportFile` path.");
	const source = await readFile(input.exportFile, "utf8");
	const bundle = parseWordPressExport(source);
	const inventory = buildInventory(input, bundle);
	return { source, bundle, inventory };
}

function buildInventory(
	input: { exportFile?: string; sourceUrl?: string },
	bundle: ParsedBundle,
): AstropressWordPressImportInventory {
	const unsupported = detectUnsupportedPatterns(
		bundle.contentRecords.map((r) => `${r.body}\n${r.excerpt ?? ""}`).join("\n"),
	);
	return {
		exportFile: input.exportFile,
		sourceUrl: input.sourceUrl,
		detectedRecords: bundle.contentRecords.length + bundle.mediaAssets.length,
		detectedMedia: bundle.mediaAssets.length,
		detectedComments: bundle.comments.length,
		detectedUsers: bundle.authors.length,
		detectedShortcodes: unsupported.shortcodeMatches,
		detectedBuilderMarkers: unsupported.builderMatches,
		entityCounts: bundle.entityCounts,
		unsupportedPatterns: bundle.unsupportedPatterns,
		remediationCandidates: bundle.remediationCandidates,
		warnings: bundle.warnings,
	};
}

function buildImportPlan(
	inventory: AstropressWordPressImportInventory,
	overrides: Pick<
		AstropressWordPressImportPlan,
		"includeComments" | "includeUsers" | "includeMedia" | "downloadMedia" | "applyLocal"
	> & {
		artifactDir?: string;
	} = {
		includeComments: true,
		includeUsers: true,
		includeMedia: true,
		downloadMedia: false,
		applyLocal: false,
	},
): AstropressWordPressImportPlan {
	const includeComments = overrides.includeComments ?? inventory.detectedComments > 0;
	const includeUsers = overrides.includeUsers ?? inventory.detectedUsers > 0;
	const includeMedia = overrides.includeMedia ?? inventory.detectedMedia > 0;
	const downloadMedia = includeMedia && (overrides.downloadMedia ?? false);
	const applyLocal = overrides.applyLocal ?? false;
	const manualTasks = [...inventory.warnings];

	if (inventory.remediationCandidates.length > 0) {
		manualTasks.push(
			"Review remediation-candidates.json for shortcode or page-builder cleanup before publishing staged content.",
		);
	}
	if (downloadMedia && !overrides.artifactDir) {
		manualTasks.push(
			"Media download was requested without an artifact directory; downloads will be skipped.",
		);
	}

	return {
		sourceUrl: inventory.sourceUrl,
		exportFile: inventory.exportFile,
		artifactDir: overrides.artifactDir,
		includeComments,
		includeUsers,
		includeMedia,
		downloadMedia: downloadMedia && Boolean(overrides.artifactDir),
		applyLocal,
		permalinkStrategy: "preserve-wordpress-links",
		resumeSupported: true,
		entityCounts: inventory.entityCounts,
		reviewRequired: inventory.unsupportedPatterns.length > 0,
		manualTasks: [...new Set(manualTasks)],
	};
}

async function stageArtifacts(
	artifactDir: string,
	inventory: AstropressWordPressImportInventory,
	plan: AstropressWordPressImportPlan,
	bundle: ParsedBundle,
	resumeFrom?: string,
): Promise<{
	artifacts: AstropressWordPressImportArtifacts;
	downloadedMedia: number;
	failedMedia: AstropressWordPressImportReport["failedMedia"];
}> {
	await mkdir(artifactDir, { recursive: true });

	// Hold the paths as locals (always `string`) so we don't read them back
	// through the artifacts object's optional `?: string` fields, which the
	// shared AstropressWordPressImportArtifacts contract keeps optional for
	// partially-built reports elsewhere.
	const inventoryFile = path.join(artifactDir, "wordpress.inventory.json");
	const planFile = path.join(artifactDir, "wordpress.plan.json");
	const contentFile = path.join(artifactDir, "content-records.json");
	const mediaFile = path.join(artifactDir, "media-manifest.json");
	const commentFile = path.join(artifactDir, "comment-records.json");
	const userFile = path.join(artifactDir, "user-records.json");
	const redirectFile = path.join(artifactDir, "redirect-records.json");
	const taxonomyFile = path.join(artifactDir, "taxonomy-records.json");
	const remediationFile = path.join(artifactDir, "remediation-candidates.json");
	const downloadStateFile = path.join(artifactDir, "download-state.json");
	const artifacts: AstropressWordPressImportArtifacts = {
		artifactDir,
		inventoryFile,
		planFile,
		contentFile,
		mediaFile,
		commentFile,
		userFile,
		redirectFile,
		taxonomyFile,
		remediationFile,
		downloadStateFile,
	};

	await writeJsonArtifact(inventoryFile, inventory);
	await writeJsonArtifact(planFile, plan);
	await writeJsonArtifact(contentFile, bundle.contentRecords);
	await writeJsonArtifact(mediaFile, bundle.mediaAssets);
	await writeJsonArtifact(commentFile, bundle.comments);
	await writeJsonArtifact(userFile, bundle.authors);
	await writeJsonArtifact(redirectFile, bundle.redirects);
	await writeJsonArtifact(taxonomyFile, bundle.terms);
	await writeJsonArtifact(remediationFile, bundle.remediationCandidates);

	if (!plan.downloadMedia) {
		await writeJsonArtifact(downloadStateFile, {
			completed: [],
			failed: [],
		} satisfies DownloadState);
		return { artifacts, downloadedMedia: 0, failedMedia: [] };
	}

	const downloadOutcome = await downloadMediaAssets(bundle.mediaAssets, artifactDir, resumeFrom);
	artifacts.downloadStateFile = downloadOutcome.downloadStateFile;
	return {
		artifacts,
		downloadedMedia: downloadOutcome.downloadedMedia,
		failedMedia: downloadOutcome.failedMedia,
	};
}

function resolveImportOverrides(input: {
	includeComments?: boolean;
	includeUsers?: boolean;
	includeMedia?: boolean;
	downloadMedia?: boolean;
	artifactDir?: string;
	applyLocal?: boolean;
}) {
	return {
		includeComments: input.includeComments ?? true,
		includeUsers: input.includeUsers ?? true,
		includeMedia: input.includeMedia ?? true,
		downloadMedia: input.downloadMedia ?? false,
		artifactDir: input.artifactDir,
		applyLocal: input.applyLocal ?? false,
	};
}

function resolveImportStatus(
	plan: AstropressWordPressImportPlan,
	failedMedia: AstropressWordPressImportReport["failedMedia"],
): AstropressWordPressImportReport["status"] {
	return plan.reviewRequired || failedMedia.length > 0 ? "completed_with_warnings" : "completed";
}

export function createAstropressWordPressImportSource(
	options: AstropressWordPressImportSourceOptions = {},
): ImportSource {
	return {
		async inspectWordPress(input) {
			const { inventory } = await parseImportInput({
				...input,
				sourceUrl: input.sourceUrl ?? options.sourceUrl,
			});
			return inventory;
		},
		async planWordPressImport(input) {
			return buildImportPlan(input.inventory, resolveImportOverrides(input));
		},
		async importWordPress(input) {
			const { bundle, inventory } = await parseImportInput({
				...input,
				sourceUrl: input.sourceUrl ?? options.sourceUrl,
			});
			const plan = input.plan ?? buildImportPlan(inventory, resolveImportOverrides(input));

			const artifactsOutcome = plan.artifactDir
				? await stageArtifacts(plan.artifactDir, inventory, plan, bundle, input.resumeFrom)
				: { artifacts: undefined, downloadedMedia: 0, failedMedia: [] };

			const localApply = plan.applyLocal
				? await applyImportToLocalRuntime({
						bundle,
						artifactDir: plan.artifactDir,
						workspaceRoot: input.workspaceRoot ?? process.cwd(),
						adminDbPath: input.adminDbPath,
						plan,
					})
				: undefined;

			if (plan.applyLocal && plan.artifactDir) {
				const localApplyReportFile = path.join(plan.artifactDir, "wordpress.local-apply.json");
				await writeJsonArtifact(localApplyReportFile, localApply);
				if (artifactsOutcome.artifacts)
					artifactsOutcome.artifacts.localApplyReportFile = localApplyReportFile;
			}

			if (plan.artifactDir && artifactsOutcome.artifacts) {
				const reportFile = path.join(plan.artifactDir, "import-report.json");
				await writeJsonArtifact(reportFile, {
					generatedAt: new Date().toISOString(),
					status: resolveImportStatus(plan, artifactsOutcome.failedMedia),
					counts: bundle.entityCounts,
					mediaErrors: artifactsOutcome.failedMedia.map((f) => ({
						id: f.id,
						sourceUrl: f.sourceUrl,
						reason: f.reason,
					})),
					manualReviewFlags: bundle.remediationCandidates,
					warnings: plan.manualTasks,
				});
				artifactsOutcome.artifacts.reportFile = reportFile;
			}

			return {
				status: resolveImportStatus(plan, artifactsOutcome.failedMedia),
				importedRecords: bundle.contentRecords.length,
				importedMedia: plan.includeMedia ? bundle.mediaAssets.length : 0,
				importedComments: plan.includeComments ? bundle.comments.length : 0,
				importedUsers: plan.includeUsers ? bundle.authors.length : 0,
				importedRedirects: bundle.redirects.length,
				downloadedMedia: artifactsOutcome.downloadedMedia,
				failedMedia: artifactsOutcome.failedMedia,
				reviewRequired: plan.reviewRequired,
				manualTasks: plan.manualTasks,
				plan,
				inventory,
				artifacts: artifactsOutcome.artifacts,
				localApply,
				warnings: [
					...new Set([
						...inventory.warnings,
						...plan.manualTasks,
						...(localApply
							? [`Applied WordPress import into local SQLite runtime at ${localApply.adminDbPath}.`]
							: []),
						...artifactsOutcome.failedMedia.map(
							(e) => `Media download failed for ${e.id}: ${e.reason}`,
						),
					]),
				],
			} satisfies AstropressWordPressImportReport;
		},
		async resumeWordPressImport(input) {
			return this.importWordPress({
				...input,
				sourceUrl: input.sourceUrl ?? options.sourceUrl,
				artifactDir: input.artifactDir,
				resumeFrom: path.join(input.artifactDir, "download-state.json"),
			});
		},
	};
}

