import { withLocalStoreFallback } from "./admin-store-dispatch";
import { recordD1Audit } from "./d1-audit";
import type { Actor } from "./persistence-types";

/**
 * Tables that support soft-delete undo via this restore action.
 * Must be an exact match — never accept arbitrary user input as a table name.
 */
const RESTORABLE_TABLES = ["authors", "media_assets", "categories", "tags"] as const;
type RestorableTable = (typeof RESTORABLE_TABLES)[number];

export function isRestorableTable(table: string): table is RestorableTable {
	return (RESTORABLE_TABLES as readonly string[]).includes(table);
}

/**
 * Clears `deleted_at` for the given record, effectively undoing a soft delete.
 * Only operates on tables in the RESTORABLE_TABLES allowlist.
 */
export async function restoreRuntimeRecord(
	table: RestorableTable,
	id: number,
	actor: Actor,
	locals?: App.Locals | null,
): Promise<{ ok: true } | { ok: false; error: string }> {
	if (!Number.isFinite(id) || id <= 0) {
		return { ok: false, error: "Invalid id" };
	}

	return withLocalStoreFallback(
		locals,
		async (db) => {
			const result = await db
				.prepare(
					`UPDATE ${table} SET deleted_at = NULL, updated_at = CURRENT_TIMESTAMP WHERE id = ? AND deleted_at IS NOT NULL`,
				)
				.bind(id)
				.run();

			/* v8 ignore next 3 */
			if (!result.success) {
				return { ok: false as const, error: "Restore query failed" };
			}

			if ((result.meta?.changes ?? 0) === 0) {
				return { ok: false as const, error: "Record not found or not deleted" };
			}

			await recordD1Audit(
				locals,
				actor,
				"record.restore",
				table,
				String(id),
				`Restored ${table} id=${id}.`,
			);
			return { ok: true as const };
		},
		/* v8 ignore next 3 */
		async () => {
			return {
				ok: false as const,
				error: "Restore is not supported on this storage backend",
			};
		},
	);
}

src/runtime-health.ts.source:
const startTime = Date.now();

export interface HealthStatus {
	status: "ok" | "degraded";
	version: string;
	uptime: number;
	timestamp: string;
}

function resolveVersion(): string {
	try {
		// Resolved at runtime from the nearest package.json
		const pkg = (globalThis as { __ASTROPRESS_VERSION__?: unknown }).__ASTROPRESS_VERSION__;
		if (typeof pkg === "string") return pkg;
	} catch {
		// ignore
	}
	return "unknown";
}

type HealthCheckFn = () => Promise<void> | void;

let _healthCheck: HealthCheckFn | null = null;

export function registerHealthCheck(fn: HealthCheckFn): void {
	_healthCheck = fn;
}

export async function handleHealthRequest(_request: Request): Promise<Response> {
	let status: "ok" | "degraded" = "ok";
	if (_healthCheck) {
		try {
			await _healthCheck();
		} catch {
			status = "degraded";
		}
	}

	const body: HealthStatus = {
		status,
		version: resolveVersion(),
		uptime: Math.floor((Date.now() - startTime) / 1000),
		timestamp: new Date().toISOString(),
	};
	return new Response(JSON.stringify(body), {
		status: status === "ok" ? 200 : 503,
		headers: {
			"Content-Type": "application/json",
			"Cache-Control": "no-store",
		},
	});
}

