import type { AstropressSqliteDatabaseLike } from "./utils";

export interface ContentLockResult {
	ok: true;
	lockToken: string;
	expiresAt: string;
}

export interface ContentLockConflict {
	ok: false;
	conflict: true;
	lockedByEmail: string;
	lockedByName: string;
	expiresAt: string;
}

const LOCK_TTL_MINUTES = 5;

function lockExpiresAt(): string {
	const d = new Date();
	d.setMinutes(d.getMinutes() + LOCK_TTL_MINUTES);
	return d.toISOString();
}

export function createSqliteLocksOps(getDb: () => AstropressSqliteDatabaseLike) {
	return {
		acquireLock(
			slug: string,
			email: string,
			name: string,
		): ContentLockResult | ContentLockConflict {
			const db = getDb();
			db.exec("BEGIN IMMEDIATE");
			try {
				db.prepare("DELETE FROM content_locks WHERE expires_at <= ?").run(new Date().toISOString());

				const existing = db
					.prepare(
						"SELECT locked_by_email, locked_by_name, expires_at FROM content_locks WHERE slug = ? LIMIT 1",
					)
					.get(slug) as
					| {
							locked_by_email: string;
							locked_by_name: string;
							expires_at: string;
					  }
					| undefined;

				if (existing && existing.locked_by_email !== email) {
					db.exec("ROLLBACK");
					return {
						ok: false,
						conflict: true,
						lockedByEmail: existing.locked_by_email,
						lockedByName: existing.locked_by_name,
						expiresAt: existing.expires_at,
					};
				}

				const lockToken = crypto.randomUUID();
				const expiresAt = lockExpiresAt();
				db.prepare(
					`INSERT INTO content_locks (slug, locked_by_email, locked_by_name, lock_token, expires_at)
             VALUES (?, ?, ?, ?, ?)
             ON CONFLICT(slug) DO UPDATE SET
               locked_by_email = excluded.locked_by_email,
               locked_by_name = excluded.locked_by_name,
               lock_token = excluded.lock_token,
               expires_at = excluded.expires_at`,
				).run(slug, email, name, lockToken, expiresAt);
				db.exec("COMMIT");
				return { ok: true, lockToken, expiresAt };
			} catch (e) {
				db.exec("ROLLBACK");
				throw e;
			}
		},

		refreshLock(slug: string, lockToken: string): boolean {
			const expiresAt = lockExpiresAt();
			const result = getDb()
				.prepare("UPDATE content_locks SET expires_at = ? WHERE slug = ? AND lock_token = ?")
				.run(expiresAt, slug, lockToken);
			return (result.changes as number) > 0;
		},

		releaseLock(slug: string, lockToken: string): boolean {
			const result = getDb()
				.prepare("DELETE FROM content_locks WHERE slug = ? AND lock_token = ?")
				.run(slug, lockToken);
			return (result.changes as number) > 0;
		},
	};
}

src/sqlite-runtime/search.ts.source:
import type { ContentRecord } from "../persistence-types";
import type { AstropressSqliteDatabaseLike } from "./utils";

/**
 * Search content_overrides using the FTS5 virtual table.
 * Requires ensureFts5SearchIndex to have been called at boot.
 */
export function searchContentOverrides(
	db: AstropressSqliteDatabaseLike,
	query: string,
): ContentRecord[] {
	return db
		.prepare(
			`SELECT co.* FROM content_overrides co
       WHERE co.rowid IN (SELECT rowid FROM content_fts(?) ORDER BY rank)`,
		)
		.all(query) as ContentRecord[];
}

src/sqlite-runtime/webhooks-d1.ts.source:
/**
 * D1 sibling of `webhooks.ts`. Implements the same {@link WebhookStore}
 * contract over D1's promise-returning SDK. The SQL bodies and column lists
 * match the sqlite store byte-for-byte; the ML-DSA signing surface
 * (`createMlDsaKeyPair` / `signMlDsaMessage`) is shared and host-agnostic.
 *
 * The dispatch seam (`admin-store-dispatch.ts` `resolveApiRuntime`) selects
 * this backend whenever a D1 binding is present, so the REST webhook surface
 * and the admin webhook UI no longer require the local runtime alias on a
 * D1-backed host. See issue #137.
 */

import { randomBytes } from "node:crypto";
import { createMlDsaKeyPair, secretKeyToBase64, signMlDsaMessage } from "../crypto-primitives";
import type { D1DatabaseLike } from "../d1-database";
import type { WebhookEvent, WebhookRecord, WebhookStore } from "../platform-contracts";
import { createLogger } from "../runtime-logger";

const logger = createLogger("Webhook");

interface WebhookRow {
	id: string;
	url: string;
	events: string;
	secret_hash: string; // stores the ML-DSA secret key (field naming is historical)
	active: number;
	created_at: string;
	last_fired_at: string | null;
}

const SELECT_COLUMNS = "id, url, events, secret_hash, active, created_at, last_fired_at";

function rowToRecord(row: WebhookRow): WebhookRecord {
	return {
		id: row.id,
		url: row.url,
		events: JSON.parse(row.events) as WebhookEvent[],
		active: row.active === 1,
		createdAt: row.created_at,
		lastFiredAt: row.last_fired_at ?? null,
	};
}

export function createD1WebhookStore(
	db: D1DatabaseLike,
	fetchImpl: typeof fetch = fetch,
): WebhookStore {
	return {
		async list() {
			const { results } = await db
				.prepare(
					`SELECT ${SELECT_COLUMNS} FROM webhooks WHERE deleted_at IS NULL ORDER BY created_at DESC`,
				)
				.all<WebhookRow>();
			return results.map(rowToRecord);
		},

		async create({ url, events }) {
			const id = `wh_${randomBytes(12).toString("hex")}`;
			const keyPair = createMlDsaKeyPair(id, randomBytes(32));
			const now = new Date().toISOString();

			await db
				.prepare(
					"INSERT INTO webhooks (id, url, events, secret_hash, active, created_at) VALUES (?, ?, ?, ?, 1, ?)",
				)
				.bind(id, url, JSON.stringify(events), secretKeyToBase64(keyPair.secretKey), now)
				.run();

			const record: WebhookRecord = {
				id,
				url,
				events,
				active: true,
				createdAt: now,
				lastFiredAt: null,
			};

			return { record, verification: keyPair.verification };
		},

		async delete(id) {
			const now = new Date().toISOString();
			await db
				.prepare("UPDATE webhooks SET deleted_at = ?, active = 0 WHERE id = ?")
				.bind(now, id)
				.run();
		},

		async dispatch(event, payload) {
			const { results } = await db
				.prepare(`SELECT ${SELECT_COLUMNS} FROM webhooks WHERE deleted_at IS NULL AND active = 1`)
				.all<WebhookRow>();

			const subscribers = results.filter((row) => {
				const events = JSON.parse(row.events) as WebhookEvent[];
				return events.includes(event);
			});

			if (subscribers.length === 0) return;

			const bodyText = JSON.stringify({
				event,
				payload,
				timestamp: new Date().toISOString(),
			});
			const now = new Date().toISOString();

			await Promise.allSettled(
				subscribers.map(async (row) => {
					const signature = signMlDsaMessage(bodyText, row.secret_hash);
					try {
						await fetchImpl(
							new Request(row.url, {
								method: "POST",
								headers: {
									"Content-Type": "application/json",
									"X-Astropress-Event": event,
									"X-Astropress-Signature": signature,
									"X-Astropress-Signature-Alg": "ML-DSA-65",
									"X-Astropress-Key-Id": row.id,
								},
								body: bodyText,
							}),
						);
					} catch (err) {
						logger.error(`Failed to dispatch ${event} to ${row.url}`, {
							error: err,
						});
						return;
					}

					await db
						.prepare("UPDATE webhooks SET last_fired_at = ? WHERE id = ?")
						.bind(now, row.id)
						.run();
				}),
			);
		},
	};
}

src/sqlite-seed-helpers.ts.source:
import { hashPasswordArgon2id } from "./crypto-primitives";
import type { SqliteDatabaseLike } from "./sqlite-bootstrap.js";
import { getTableColumns } from "./sqlite-schema-compat.js";

export function hashPasswordSync(password: string, iterations = 2) {
	return hashPasswordArgon2id(password, { iterations });
}

export function guessMimeType(pathname: string) {
	const lower = pathname.toLowerCase();
	if (lower.endsWith(".png")) return "image/png";
	if (lower.endsWith(".webp")) return "image/webp";
	if (lower.endsWith(".gif")) return "image/gif";
	return "image/jpeg";
}

export function toSqlLiteral(value: unknown): string {
	if (value === null || value === undefined) return "NULL";
	if (typeof value === "number" || typeof value === "bigint") return String(value);
	if (typeof value === "boolean") return value ? "1" : "0";
	if (value instanceof Uint8Array) return `X'${Buffer.from(value).toString("hex")}'`;
	return `'${String(value).replaceAll("'", "''")}'`;
}

export function buildTableImportStatements(db: SqliteDatabaseLike, table: string) {
	const columns = getTableColumns(db, table);
	if (columns.length === 0) return [] as string[];

	// audit-boundary: opaque-passthrough -- SQL row-shape mirror; columns narrowed at row-mapper boundary
	const rows = db.prepare(`SELECT * FROM ${table}`).all() as Record<string, unknown>[];
	const statements = [`DELETE FROM ${table};`];
	for (const row of rows) {
		const serializedValues = columns.map((column) => toSqlLiteral(row[column]));
		statements.push(
			`INSERT INTO ${table} (${columns.join(", ")}) VALUES (${serializedValues.join(", ")});`,
		);
	}
	return statements;
}

export function buildTableImportSql(db: SqliteDatabaseLike, table: string) {
	return buildTableImportStatements(db, table).join("\n");
}

src/taxonomy-repository-factory.ts.source:
import type { Actor, TaxonomyKind, TaxonomyRepository } from "./persistence-types";

type TaxonomyTable = "categories" | "tags";

export interface AstropressTaxonomyRepositoryInput {
	listCategories: TaxonomyRepository["listCategories"];
	listTags: TaxonomyRepository["listTags"];
	slugifyTerm(value: string): string;
	createTaxonomyTerm(input: {
		table: TaxonomyTable;
		slug: string;
		name: string;
		description: string;
	}): boolean;
	updateTaxonomyTerm(input: {
		table: TaxonomyTable;
		id: number;
		slug: string;
		name: string;
		description: string;
	}): boolean;
	deleteTaxonomyTerm(input: { table: TaxonomyTable; id: number }): boolean;
	recordTaxonomyAudit(input: {
		actor: Actor;
		action: `${TaxonomyKind}.create` | `${TaxonomyKind}.update` | `${TaxonomyKind}.delete`;
		summary: string;
		targetId: string;
	}): void;
}

function createTerm(
	input: AstropressTaxonomyRepositoryInput,
	table: TaxonomyTable,
	kind: TaxonomyKind,
	rawInput: { name: string; slug?: string; description?: string },
	actor: Actor,
) {
	const name = rawInput.name.trim();
	const slug = input.slugifyTerm(rawInput.slug?.trim() || name);
	if (!name || !slug) {
		return { ok: false as const, error: `${kind} name and slug are required.` };
	}

	const created = input.createTaxonomyTerm({
		table,
		slug,
		name,
		description: rawInput.description?.trim() ?? "",
	});
	if (!created) {
		return {
			ok: false as const,
			error: `That ${kind} name or slug is already in use.`,
		};
	}

	input.recordTaxonomyAudit({
		actor,
		action: `${kind}.create`,
		summary: `Created ${kind} ${name}.`,
		targetId: slug,
	});
	return { ok: true as const };
}

function updateTerm(
	input: AstropressTaxonomyRepositoryInput,
	table: TaxonomyTable,
	kind: TaxonomyKind,
	rawInput: { id: number; name: string; slug?: string; description?: string },
	actor: Actor,
) {
	const name = rawInput.name.trim();
	const slug = input.slugifyTerm(rawInput.slug?.trim() || name);
	if (!rawInput.id || !name || !slug) {
		return {
			ok: false as const,
			error: `${kind} id, name, and slug are required.`,
		};
	}

	const updated = input.updateTaxonomyTerm({
		table,
		id: rawInput.id,
		slug,
		name,
		description: rawInput.description?.trim() ?? "",
	});
	if (!updated) {
		return { ok: false as const, error: `That ${kind} could not be updated.` };
	}

	input.recordTaxonomyAudit({
		actor,
		action: `${kind}.update`,
		summary: `Updated ${kind} ${name}.`,
		targetId: String(rawInput.id),
	});
	return { ok: true as const };
}

function deleteTerm(
	input: AstropressTaxonomyRepositoryInput,
	table: TaxonomyTable,
	kind: TaxonomyKind,
	id: number,
	actor: Actor,
) {
	const deleted = input.deleteTaxonomyTerm({ table, id });
	if (!deleted) {
		return { ok: false as const, error: `That ${kind} could not be deleted.` };
	}

	input.recordTaxonomyAudit({
		actor,
		action: `${kind}.delete`,
		summary: `Deleted ${kind} ${id}.`,
		targetId: String(id),
	});
	return { ok: true as const };
}

export function createAstropressTaxonomyRepository(
	input: AstropressTaxonomyRepositoryInput,
): TaxonomyRepository {
	return {
		listCategories: (...args) => input.listCategories(...args),
		listTags: (...args) => input.listTags(...args),
		createCategory: (rawInput, actor) =>
			createTerm(input, "categories", "category", rawInput, actor),
		updateCategory: (rawInput, actor) =>
			updateTerm(input, "categories", "category", rawInput, actor),
		deleteCategory: (id, actor) => deleteTerm(input, "categories", "category", id, actor),
		createTag: (rawInput, actor) => createTerm(input, "tags", "tag", rawInput, actor),
		updateTag: (rawInput, actor) => updateTerm(input, "tags", "tag", rawInput, actor),
		deleteTag: (id, actor) => deleteTerm(input, "tags", "tag", id, actor),
	};
}

src/turnstile.ts.source:
import { getLoginSecurityConfig, isProductionRuntime } from "./runtime-env";

interface TurnstileVerificationResult {
	ok: boolean;
	error?: string;
}

interface TurnstileResponsePayload {
	success?: boolean;
	"error-codes"?: string[];
}

export function isTurnstileEnabled(locals?: App.Locals | null) {
	return Boolean(getLoginSecurityConfig(locals).turnstileSecretKey);
}

export async function verifyTurnstileToken(input: {
	token: string | null | undefined;
	ipAddress?: string | null;
	locals?: App.Locals | null;
	requireConfigured?: boolean;
}): Promise<TurnstileVerificationResult> {
	const { turnstileSecretKey } = getLoginSecurityConfig(input.locals);
	if (!turnstileSecretKey) {
		if (input.requireConfigured && isProductionRuntime()) {
			return { ok: false, error: "Security challenge is not configured." };
		}

		return { ok: true };
	}

	const token = input.token?.trim();
	if (!token) {
		return { ok: false, error: "Security challenge is required." };
	}

	const payload = new URLSearchParams({
		secret: turnstileSecretKey,
		response: token,
	});

	if (input.ipAddress) {
		payload.set("remoteip", input.ipAddress);
	}

	try {
		const response = await fetch("https://challenges.cloudflare.com/turnstile/v0/siteverify", {
			method: "POST",
			headers: {
				"Content-Type": "application/x-www-form-urlencoded",
			},
			body: payload,
		});

		if (!response.ok) {
			return { ok: false, error: "Security challenge could not be verified." };
		}

		const result = (await response.json()) as TurnstileResponsePayload;
		if (!result.success) {
			return {
				ok: false,
				error: result["error-codes"]?.join(", ") || "Security challenge failed.",
			};
		}

		return { ok: true };
	} catch {
		return { ok: false, error: "Security challenge could not be verified." };
	}
}

src/vitest-runtime-alias.ts.source:
export type AstropressVitestPlugin = {
	name: string;
	enforce?: "pre" | "post";
	resolveId: (id: string, importer?: string) => string | undefined;
};

export function isLocalRuntimeModuleId(id: string): boolean {
	return /local-runtime-modules(?:\.[jt]s)?$/.test(id);
}

export function isAstropressSrcImporter(importer: string): boolean {
	const norm = importer.replace(/\\/g, "/");
	if (norm.includes("/astropress/packages/astropress/src/")) return true;
	if (norm.includes("/node_modules/astropress/src/")) return true;
	if (norm.includes("/node_modules/.bun/")) {
		return norm.includes("/astropress/src/");
	}
	return false;
}

export function createAstropressVitestLocalRuntimePlugins(
	localRuntimeModulesPath: string,
): AstropressVitestPlugin[] {
	return [
		{
			name: "astropress-local-runtime-modules-replacer",
			enforce: "pre",
			resolveId(id) {
				if (isLocalRuntimeModuleId(id)) {
					return localRuntimeModulesPath;
				}
			},
		},
		{
			name: "astropress-external-source-rewriter",
			enforce: "pre",
			resolveId(id, importer) {
				if (importer && isAstropressSrcImporter(importer) && isLocalRuntimeModuleId(id)) {
					return localRuntimeModulesPath;
				}
			},
		},
	];
}

src/admin-slug-cache.ts.source:
import type { APIContext } from "astro";

import { getRuntimeSettings } from "./runtime-page-store";

const ADMIN_SLUG_CACHE_TTL_MS = 60_000;

let cachedAdminSlug: string | null = null;
let cachedAdminSlugAt = 0;

export function invalidateAstropressAdminSlugCache() {
	cachedAdminSlug = null;
}

// Inlined literal (rather than a module-level const) so the StringLiteral
// mutation lives inside this function body — every call covers it,
// rather than only the first test that loads the module.
function defaultAdminSlug(): "ap-admin" {
	return "ap-admin";
}

export async function resolveAstropressAdminSlug(locals: APIContext["locals"]) {
	const now = Date.now();
	if (cachedAdminSlug !== null && now - cachedAdminSlugAt < ADMIN_SLUG_CACHE_TTL_MS) {
		return cachedAdminSlug;
	}

	try {
		const settings = await getRuntimeSettings(locals);
		cachedAdminSlug = settings.adminSlug || defaultAdminSlug();
		cachedAdminSlugAt = now;
		return cachedAdminSlug;
	} catch {
		return defaultAdminSlug();
	}
}

src/api-middleware-error-shapes.ts.source:
// stryker-disable-file: data-only — pure error-response shape table.
// Each entry is a thin Response builder: HTTP status + machine-readable
// `code` + the supplied detail. Mutating the literals here would only
// change the wire shape; behavioral coverage lives in the consumer
// (api-middleware.ts authorize/rate-limit paths) which already exercises
// representative shapes through integration tests.

import type { JsonValue } from "./json-types";

function jsonError(status: number, body: Record<string, JsonValue>) {
	return new Response(JSON.stringify(body), {
		status,
		headers: { "Content-Type": "application/json" },
	});
}

export const API_ERROR_SHAPES = {
	unauthorized: (detail: string) => jsonError(401, { error: detail, code: "unauthorized" }),
	forbidden: (detail: string) => jsonError(403, { error: detail, code: "forbidden" }),
	rateLimited: () => jsonError(429, { error: "Too many requests.", code: "rate_limited" }),
	notFound: (detail = "Not found.") => jsonError(404, { error: detail, code: "not_found" }),
	validationError: (detail: string) => jsonError(422, { error: detail, code: "validation_error" }),
	fileTooLarge: (maxBytes: number, uploadedBytes: number) =>
		jsonError(413, {
			error: "FILE_TOO_LARGE",
			code: "file_too_large",
			maxBytes,
			uploadedBytes,
		}),
	unsupportedMediaType: (mimeType: string, allowed: string[]) =>
		jsonError(415, {
			error: "UNSUPPORTED_MEDIA_TYPE",
			code: "unsupported_media_type",
			mimeType,
			allowed: allowed as unknown as JsonValue,
		}),
};

src/auth-repository-helpers.ts.source:
import type { Actor, SessionUser } from "./persistence-types";

export interface AstropressAuthSessionRow extends SessionUser {
	id: string;
	csrfToken: string;
	lastActiveAt: string;
}

export interface AstropressInviteTokenRecord extends SessionUser {
	id: string;
	userId: number;
	expiresAt: string;
	acceptedAt: string | null;
	active: boolean;
}

export interface AstropressPasswordResetTokenRecord extends SessionUser {
	id: string;
	userId: number;
	expiresAt: string;
	consumedAt: string | null;
	active: boolean;
}

export interface AstropressAuthRepositoryInput {
	sessionTtlMs: number;
	now(): number;
	randomId(): string;
	hashOpaqueToken(value: string): string;
	hashPassword(value: string): string;
	verifyPassword(password: string, storedHash: string): boolean;
	cleanupExpiredSessions(): void;
	findActiveAdminUserByEmail(email: string):
		| {
				id: number;
				email: string;
				passwordHash: string;
				role: SessionUser["role"];
				name: string;
		  }
		| null
		| undefined;
	findActiveAdminUserIdByEmail(email: string): number | null | undefined;
	insertSession(input: {
		sessionToken: string;
		userId: number;
		csrfToken: string;
		ipAddress?: string | null;
		userAgent?: string | null;
	}): void;
	findLiveSessionById(sessionToken: string): AstropressAuthSessionRow | null | undefined;
	touchSession(sessionToken: string): void;
	revokeSessionById(sessionToken: string): void;
	findInviteTokenByHash(tokenHash: string): AstropressInviteTokenRecord | null | undefined;
	updateAdminUserPassword(userId: number, passwordHash: string): void;
	acceptInvitesForUser(userId: number): void;
	findPasswordResetUserByEmail(
		email: string,
	): { id: number; email: string; role: SessionUser["role"]; name: string } | null | undefined;
	consumePasswordResetTokensForUser(userId: number): void;
	insertPasswordResetToken(input: {
		tokenId: string;
		userId: number;
		tokenHash: string;
		expiresAt: string;
		requestedBy: string | null;
	}): void;
	findPasswordResetTokenByHash(
		tokenHash: string,
	): AstropressPasswordResetTokenRecord | null | undefined;
	markPasswordResetTokenConsumed(tokenId: string): void;
	revokeSessionsForUser(userId: number): void;
	recordAuthAudit(input: {
		actor: Actor;
		action:
			| "auth.login"
			| "auth.logout"
			| "auth.invite_accept"
			| "auth.password_reset_issue"
			| "auth.password_reset_complete";
		summary: string;
		targetId: string;
	}): void;
}

export function mapSessionUser(
	row: Pick<AstropressAuthSessionRow, "email" | "role" | "name">,
): SessionUser {
	return {
		email: row.email,
		role: row.role,
		name: row.name,
	};
}

/**
 * Parse a stored timestamp to epoch millis, treating SQLite's offset-less
 * `CURRENT_TIMESTAMP` format ("YYYY-MM-DD HH:MM:SS", always UTC) as UTC.
 * Date.parse alone reads that format as *local* time, which skews session
 * ages by the server's UTC offset (#195). ISO-8601 strings pass through
 * unchanged.
 */
export function parseUtcTimestamp(value: string): number {
	const sqliteUtc = /^\d{4}-\d{2}-\d{2} \d{2}:\d{2}:\d{2}(\.\d+)?$/;
	return Date.parse(sqliteUtc.test(value) ? `${value.replace(" ", "T")}Z` : value);
}

export function isUsableToken(
	expiresAt: string,
	consumedAt: string | null,
	active: boolean,
	now: number,
): boolean {
	return !consumedAt && active && Date.parse(expiresAt) >= now;
}

export function resolveValidSession(
	sessionToken: string | null | undefined,
	deps: AstropressAuthRepositoryInput,
): AstropressAuthSessionRow | null {
	if (!sessionToken) {
		return null;
	}

	deps.cleanupExpiredSessions();
	const row = deps.findLiveSessionById(sessionToken);
	if (!row) {
		return null;
	}

	const lastActiveAt = parseUtcTimestamp(row.lastActiveAt);
	if (!Number.isFinite(lastActiveAt) || deps.now() - lastActiveAt > deps.sessionTtlMs) {
		deps.revokeSessionById(sessionToken);
		return null;
	}

	deps.touchSession(sessionToken);
	return row;
}

export function resolveUsableInviteToken(
	rawToken: string,
	deps: AstropressAuthRepositoryInput,
): AstropressInviteTokenRecord | null {
	const trimmedToken = rawToken.trim();
	if (!trimmedToken) {
		return null;
	}

	const row = deps.findInviteTokenByHash(deps.hashOpaqueToken(trimmedToken));
	if (!row || !isUsableToken(row.expiresAt, row.acceptedAt, row.active, deps.now())) {
		return null;
	}

	return row;
}

export function resolveUsablePasswordResetToken(
	rawToken: string,
	deps: AstropressAuthRepositoryInput,
): AstropressPasswordResetTokenRecord | null {
	const trimmedToken = rawToken.trim();
	if (!trimmedToken) {
		return null;
	}

	const row = deps.findPasswordResetTokenByHash(deps.hashOpaqueToken(trimmedToken));
	if (!row || !isUsableToken(row.expiresAt, row.consumedAt, row.active, deps.now())) {
		return null;
	}

	return row;
}

export function validatePasswordInput(password: string) {
	const trimmedPassword = password.trim();
	if (trimmedPassword.length < 12) {
		return { ok: false as const, trimmedPassword: "" };
	}
	return { ok: true as const, trimmedPassword };
}

export function buildResetUrl(rawToken: string): string {
	return `/ap-admin/reset-password?token=${encodeURIComponent(rawToken)}`;
}

export function issuePasswordResetToken(
	email: string,
	actor: Actor | undefined,
	deps: AstropressAuthRepositoryInput,
) {
	const normalizedEmail = email.trim().toLowerCase();
	if (!normalizedEmail) {
		return { ok: false as const, error: "Email is required." };
	}

	const user = deps.findPasswordResetUserByEmail(normalizedEmail);
	if (!user) {
		return actor
			? { ok: false as const, error: "That admin user could not be found." }
			: { ok: true as const, resetUrl: null as string | null };
	}

	deps.consumePasswordResetTokensForUser(user.id);

	const rawToken = deps.randomId();
	const tokenId = `reset-${deps.randomId()}`;
	const expiresAt = new Date(deps.now() + 60 * 60 * 1000).toISOString();
	deps.insertPasswordResetToken({
		tokenId,
		userId: user.id,
		tokenHash: deps.hashOpaqueToken(rawToken),
		expiresAt,
		requestedBy: actor?.email ?? null,
	});

	if (actor) {
		deps.recordAuthAudit({
			actor,
			action: "auth.password_reset_issue",
			summary: `Issued a password reset link for ${normalizedEmail}.`,
			targetId: normalizedEmail,
		});
	}

	return { ok: true as const, resetUrl: buildResetUrl(rawToken) };
}

src/canonical-origin.ts.source:
import { peekCmsConfig } from "./config.js";

/**
 * Resolve the canonical site origin for machine-consumed public outputs
 * (sitemap.xml, robots.txt, llms.txt).
 *
 * Trusted-origin resolution rule:
 *   1. If `CmsConfig.siteUrl` is configured and parseable, its origin wins.
 *      This keeps these outputs stable behind proxies, alternate hosts, and
 *      SSR adapters that rewrite the inbound `request.url` host.
 *   2. Otherwise fall back to the request-derived origin so the routes still
 *      work in zero-config / preview setups where no siteUrl is registered.
 *
 * Using the configured origin (rather than `new URL(request.url).origin`)
 * means an attacker-controlled `Host`/`X-Forwarded-Host` header cannot poison
 * the canonical URLs we advertise to crawlers. See issue #124.
 */
export function resolveCanonicalOrigin(request: { url: string }): string {
	const configured = peekCmsConfig()?.siteUrl;
	if (configured) {
		try {
			return new URL(configured).origin;
		} catch {
			// Malformed siteUrl — fall through to the request-derived origin.
		}
	}
	return new URL(request.url).origin;
}

