/**
 * config-store.ts — low-level global config storage.
 *
 * Extracted from config.ts so that plugin-dispatch.ts can read the config
 * without creating a circular dependency (config.ts re-exports from
 * plugin-dispatch.ts, and plugin-dispatch.ts needs peekCmsConfig).
 */
import type { CmsConfig } from "./config.js";

const CMS_CONFIG_KEY = Symbol.for("astropress.cms-config");

type AstropressGlobalWithConfig = typeof globalThis & {
	[CMS_CONFIG_KEY]?: CmsConfig | null;
};

function getConfigStore(): AstropressGlobalWithConfig {
	return globalThis as AstropressGlobalWithConfig;
}

export function setStoreConfig(config: CmsConfig): void {
	getConfigStore()[CMS_CONFIG_KEY] = config;
}

export function peekCmsConfig(): CmsConfig | null {
	return getConfigStore()[CMS_CONFIG_KEY] ?? null;
}

export function getCmsConfigOrThrow(): CmsConfig {
	const config = getConfigStore()[CMS_CONFIG_KEY] ?? null;
	if (!config) {
		throw new Error("Astropress not initialized — call registerCms() before using astropress.");
	}
	return config;
}

src/integrations/badge-tone.ts.source:
/**
 * Pure helpers for `IntegrationStatusBadge.astro`. The component is
 * SSR-only; pulling the discrete decisions out into TypeScript lets
 * the mapping be unit-tested (and mutation-tested) without bringing
 * an Astro container into the test runner.
 *
 * The four-state space mirrors `connected_integrations.status` from
 * Phase 2 plus the synthetic `not-connected` state used when a domain
 * has no row at all.
 */

export type IntegrationStatusBadgeKind = "connected" | "error" | "paused" | "not-connected";

export type IntegrationStatusBadgeTone = "ok" | "err" | "warn" | "muted";

export interface IntegrationStatusBadgeLabels {
	readonly connected: string;
	readonly error: string;
	readonly paused: string;
	readonly notConnected: string;
}

export function integrationStatusBadgeTone(
	status: IntegrationStatusBadgeKind,
): IntegrationStatusBadgeTone {
	if (status === "connected") return "ok";
	if (status === "error") return "err";
	if (status === "paused") return "warn";
	return "muted";
}

export function integrationStatusBadgeText(
	status: IntegrationStatusBadgeKind,
	labels: IntegrationStatusBadgeLabels,
): string {
	if (status === "connected") return labels.connected;
	if (status === "error") return labels.error;
	if (status === "paused") return labels.paused;
	return labels.notConnected;
}

src/integrations/oauth/replay.ts.source:
/**
 * OAuth state-nonce replay protection.
 *
 * The OAuth state token is stateless and signed (see `state.ts`), which makes
 * it unforgeable but NOT single-use on its own: a captured-but-valid state can
 * be replayed against the callback until it expires. `verifyOAuthState` returns
 * the per-flow `nonce` precisely so the callback can record first use and
 * reject replays (#122).
 *
 * Rather than introduce a new table we record the nonce in the existing
 * rate-limit window with `max = 1`: the first callback for a given nonce is
 * "under limit" (allowed), every subsequent one is "over limit" (rejected).
 * The window TTL matches the state's own lifetime so the record outlives any
 * state that could still verify.
 */

import { checkRuntimeRateLimit } from "../../runtime-mutation-store.js";
import { DEFAULT_OAUTH_STATE_TTL_MS } from "./state.js";

/** Namespacing prefix so OAuth nonces never collide with other rate-limit keys. */
export const OAUTH_NONCE_RATE_KEY_PREFIX = "oauth-state-nonce:";

/**
 * Atomically records that `nonce` has been seen. Returns `true` on the first
 * call for a nonce (the caller should proceed) and `false` on every later call
 * (a replay — the caller must reject). `ttlMs` defaults to the state TTL.
 */
export async function consumeOAuthStateNonce(
	locals: App.Locals | null | undefined,
	nonce: string,
	ttlMs: number = DEFAULT_OAUTH_STATE_TTL_MS,
): Promise<boolean> {
	return checkRuntimeRateLimit(`${OAUTH_NONCE_RATE_KEY_PREFIX}${nonce}`, 1, ttlMs, locals);
}

src/integrations/oauth/token-exchange.ts.source:
/**
 * Pure helper that exchanges an authorization-code for an access token
 * against the standard OAuth 2.0 token endpoint shape (RFC 6749 §4.1.3).
 *
 * The Astro callback route layer is then responsible for:
 *
 *   1. ABAC + state verification (already covered in
 *      `oauth/state.ts` and the surrounding admin-action utilities);
 *   2. Calling this helper with the registered provider's
 *      `tokenUrl`, the env-resolved client id/secret, and the
 *      `code` returned by the IdP;
 *   3. Sealing the resulting tokens via the Phase 2 envelope.
 *
 * Splitting this out means the network branches (200 / 4xx / 5xx /
 * malformed JSON) are fully unit-testable with an injected fetch.
 */

export interface ExchangeCodeForTokenArgs {
	readonly tokenUrl: string;
	readonly clientId: string;
	readonly clientSecret: string;
	readonly code: string;
	readonly redirectUri: string;
	readonly fetch?: typeof fetch;
}

export interface OAuthTokenSet {
	readonly accessToken: string;
	readonly tokenType: string;
	readonly refreshToken?: string;
	readonly expiresIn?: number;
	readonly scope?: string;
}

export type OAuthTokenExchangeErrorCode =
	| "TOKEN_HTTP_ERROR"
	| "TOKEN_MALFORMED"
	| "TOKEN_NETWORK_ERROR";

export type OAuthTokenExchangeResult =
	| { readonly ok: true; readonly tokens: OAuthTokenSet }
	| {
			readonly ok: false;
			readonly code: OAuthTokenExchangeErrorCode;
			readonly status?: number;
	  };

interface RawTokenResponse {
	access_token?: unknown;
	token_type?: unknown;
	refresh_token?: unknown;
	expires_in?: unknown;
	scope?: unknown;
}

function parseTokenResponse(raw: unknown): OAuthTokenSet | null {
	// `(raw ?? {})` handles null; for primitives, accessing `.access_token`
	// returns undefined which fails the string check below. No need for
	// an explicit `typeof !== "object"` guard.
	const r = (raw ?? {}) as RawTokenResponse;
	if (typeof r.access_token !== "string" || r.access_token.length === 0) {
		return null;
	}
	const tokenType =
		typeof r.token_type === "string" && r.token_type.length > 0 ? r.token_type : "bearer";
	// Number.isFinite is strict — only true for actual finite numbers,
	// so a redundant `typeof === "number"` would just create equivalent
	// mutants without strengthening the guard.
	const tokens: OAuthTokenSet = {
		accessToken: r.access_token,
		tokenType,
		...(typeof r.refresh_token === "string" && r.refresh_token.length > 0
			? { refreshToken: r.refresh_token }
			: {}),
		...(Number.isFinite(r.expires_in) ? { expiresIn: r.expires_in as number } : {}),
		...(typeof r.scope === "string" ? { scope: r.scope } : {}),
	};
	return tokens;
}

export async function exchangeCodeForToken(
	args: ExchangeCodeForTokenArgs,
): Promise<OAuthTokenExchangeResult> {
	const fetchImpl = args.fetch ?? fetch;
	const body = new URLSearchParams({
		grant_type: "authorization_code",
		code: args.code,
		redirect_uri: args.redirectUri,
		client_id: args.clientId,
		client_secret: args.clientSecret,
	});
	let response: Response;
	try {
		response = await fetchImpl(args.tokenUrl, {
			method: "POST",
			headers: {
				Accept: "application/json",
				"Content-Type": "application/x-www-form-urlencoded",
			},
			body: body.toString(),
		});
	} catch {
		return { ok: false, code: "TOKEN_NETWORK_ERROR" };
	}
	if (!response.ok) {
		return { ok: false, code: "TOKEN_HTTP_ERROR", status: response.status };
	}
	try {
		const tokens = parseTokenResponse(await response.json());
		if (!tokens) return { ok: false, code: "TOKEN_MALFORMED" };
		return { ok: true, tokens };
	} catch {
		return { ok: false, code: "TOKEN_MALFORMED" };
	}
}

