		const result = await buildMediaPageModel(locals);
		expect(result.status).toBe("ok");
		expect(Array.isArray(result.data.mediaWithResolvedUrls)).toBe(true);
		expect(Array.isArray(result.data.auditEvents)).toBe(true);
	});

