			"<wp:author_id>1</wp:author_id>",
			"<wp:author_login><![CDATA[alice]]></wp:author_login>",
			"<wp:author_email><![CDATA[alice@example.com]]></wp:author_email>",
			"<wp:author_display_name><![CDATA[Alice]]></wp:author_display_name>",
