		expect(insertContentEntry).toHaveBeenCalledWith({
			slug: "new-post",
			legacyUrl: "/new-post",
			title: "New post",
			body: "<p>Body</p>",
			summary: "Summary",
			seoTitle: "SEO",
			metaDescription: "Meta",
			ogTitle: "OG Title",
			ogDescription: "OG Description",
			ogImage: "https://cdn.example.com/og.png",
		});
		expect(upsertContentOverride).toHaveBeenCalledWith(
			"new-post",
			{
				title: "New post",
				status: "published",
				body: "<p>Body</p>",
				seoTitle: "SEO",
				metaDescription: "Meta",
				excerpt: "Excerpt",
				ogTitle: "OG Title",
				ogDescription: "OG Description",
				ogImage: "https://cdn.example.com/og.png",
				canonicalUrlOverride: "https://example.com/new-post",
				robotsDirective: "noindex",
			},
			actor,
		);
		expect(insertReviewedRevision).toHaveBeenCalledWith(
			"new-post",
			{
				title: "New post",
				status: "published",
				body: "<p>Body</p>",
				seoTitle: "SEO",
				metaDescription: "Meta",
				excerpt: "Excerpt",
				ogTitle: "OG Title",
				ogDescription: "OG Description",
				ogImage: "https://cdn.example.com/og.png",
