			)
			.run("group-rich-sitemap", "system", "generated_xml", "en", "/rich-sitemap.xml");
		cmsDb
			.prepare(
				"INSERT INTO cms_route_variants (id, group_id, locale, path, status, title, summary, body_html, settings_json, updated_by) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)",
			)
			.run(
