import { describe, expect, it, vi } from "vitest";
import {
	createAstropressNhostAdapter,
	createAstropressNhostHostedAdapter,
	readAstropressNhostHostedConfig,
} from "../src/adapters/nhost.js";
import { createAstropressInMemoryPlatformAdapter } from "../src/in-memory-platform-adapter.js";

describe("readAstropressNhostHostedConfig", () => {
	const validEnv = {
		NHOST_SUBDOMAIN: "abcdefgh",
		NHOST_REGION: "eu-central-1",
		NHOST_ADMIN_SECRET: "super-secret-key",
	};

	it("reads all required env vars", () => {
		const config = readAstropressNhostHostedConfig(validEnv);
		expect(config.subdomain).toBe("abcdefgh");
		expect(config.region).toBe("eu-central-1");
		expect(config.adminSecret).toBe("super-secret-key");
	});

	it("builds the correct API base URL", () => {
		const config = readAstropressNhostHostedConfig(validEnv);
		expect(config.apiBaseUrl).toBe(
			"https://abcdefgh.eu-central-1.nhost.run/v1/functions/astropress",
		);
	});

	it("builds the correct preview (console) URL", () => {
		const config = readAstropressNhostHostedConfig(validEnv);
		expect(config.previewBaseUrl).toBe("https://abcdefgh.eu-central-1.nhost.run/console");
	});

	it("throws when NHOST_SUBDOMAIN is missing", () => {
		expect(() =>
			readAstropressNhostHostedConfig({
				...validEnv,
				NHOST_SUBDOMAIN: undefined,
			}),
		).toThrow(/NHOST_SUBDOMAIN/);
	});

	it("throws when NHOST_REGION is missing", () => {
		expect(() => readAstropressNhostHostedConfig({ ...validEnv, NHOST_REGION: undefined })).toThrow(
			/NHOST_REGION/,
		);
	});

	it("throws when NHOST_ADMIN_SECRET is missing", () => {
		expect(() =>
			readAstropressNhostHostedConfig({
				...validEnv,
				NHOST_ADMIN_SECRET: undefined,
			}),
		).toThrow(/NHOST_ADMIN_SECRET/);
	});

	it("strips whitespace from env values", () => {
		const config = readAstropressNhostHostedConfig({
			NHOST_SUBDOMAIN: "  abcdefgh  ",
			NHOST_REGION: "  eu-central-1  ",
			NHOST_ADMIN_SECRET: "  secret  ",
		});
		expect(config.subdomain).toBe("abcdefgh");
		expect(config.region).toBe("eu-central-1");
		expect(config.adminSecret).toBe("secret");
	});
});

describe("createAstropressNhostAdapter", () => {
	it("creates an adapter with full capabilities", () => {
		const adapter = createAstropressNhostAdapter();
		expect(adapter.capabilities.name).toBe("nhost");
		expect(adapter.capabilities.database).toBe(true);
		expect(adapter.capabilities.objectStorage).toBe(true);
		expect(adapter.capabilities.serverRuntime).toBe(true);
		expect(adapter.capabilities.hostedAdmin).toBe(true);
	});
});

describe("createAstropressNhostHostedAdapter", () => {
	const validEnv = {
		NHOST_SUBDOMAIN: "abcdefgh",
		NHOST_REGION: "eu-central-1",
		NHOST_ADMIN_SECRET: "super-secret-key",
	};

	it("creates a hosted API adapter with full capabilities", () => {
		const adapter = createAstropressNhostHostedAdapter({ env: validEnv });
		expect(adapter.capabilities.name).toBe("nhost");
		expect(adapter.capabilities.database).toBe(true);
		expect(adapter.capabilities.objectStorage).toBe(true);
		expect(adapter.capabilities.serverRuntime).toBe(true);
		expect(adapter.capabilities.hostedAdmin).toBe(true);
	});

	it("sets the Nhost Console hostPanel link", () => {
		const adapter = createAstropressNhostHostedAdapter({ env: validEnv });
		const panel = adapter.capabilities.hostPanel as {
			url: string;
			label: string;
			mode: string;
		};
		expect(panel).toBeTruthy();
		expect(panel.url).toBe("https://abcdefgh.eu-central-1.nhost.run/console");
		expect(panel.label).toBe("Nhost Console");
		// Pins L94 StringLiteral `mode: "link"`.
		expect(panel.mode).toBe("link");
	});

	it("routes through the hosted-API adapter when no stores are provided and invokes fetchImpl (pins L78 condition chain)", async () => {
		const fetchImpl = vi.fn(async () => new Response(JSON.stringify([]), { status: 200 }) as never);
		const adapter = createAstropressNhostHostedAdapter({
			env: validEnv,
			fetchImpl: fetchImpl as never,
		});
		await adapter.content.list("post");
		expect(fetchImpl).toHaveBeenCalled();
		expect(String(fetchImpl.mock.calls[0]?.[0])).toContain("functions/astropress");
	});

	it.each([["backingAdapter"], ["content"], ["media"], ["revisions"], ["auth"]] as const)(
		"does NOT call fetchImpl when only `%s` is supplied (pins each L78 `!options.x &&` clause)",
		async (key) => {
			const fetchImpl = vi.fn(async () => new Response("nope", { status: 500 }) as never);
			const backing = createAstropressInMemoryPlatformAdapter({
				capabilities: { name: "sqlite" },
			});
			const isolated: Record<string, unknown> = {};
			if (key === "backingAdapter") {
				isolated.backingAdapter = backing;
			} else {
				isolated[key] = backing[key as "content" | "media" | "revisions" | "auth"];
			}
			const adapter = createAstropressNhostHostedAdapter({
				env: validEnv,
				...(isolated as Parameters<typeof createAstropressNhostHostedAdapter>[0]),
				fetchImpl: fetchImpl as never,
			});
			await adapter.content.list("post");
			expect(fetchImpl).not.toHaveBeenCalled();
		},
	);

	it("accepts explicit config bypassing env read", () => {
		const adapter = createAstropressNhostHostedAdapter({
			config: {
				subdomain: "xyz",
				region: "us-east-1",
				adminSecret: "s3cr3t",
				apiBaseUrl: "https://xyz.us-east-1.nhost.run/v1/functions/astropress",
				previewBaseUrl: "https://xyz.us-east-1.nhost.run/console",
			},
		});
		expect(adapter.capabilities.name).toBe("nhost");
	});

	it("falls back to hosted platform adapter when backing stores are provided", () => {
		const mockContent = {
			async list() {
				return [];
			},
			async get() {
				return null;
			},
			async save(r: unknown) {
				return r as never;
			},
			async delete() {},
		};
		const adapter = createAstropressNhostHostedAdapter({
			env: validEnv,
			content: mockContent,
		});
		expect(adapter.capabilities.name).toBe("nhost");
	});

	it("throws when required env vars are missing and no explicit config", () => {
		expect(() => createAstropressNhostHostedAdapter({ env: {} })).toThrow(/NHOST_SUBDOMAIN/);
	});

	it("trims whitespace from NHOST_SUBDOMAIN (pins L53 .trim())", () => {
		const config = readAstropressNhostHostedConfig({
			NHOST_SUBDOMAIN: "  xyz  ",
			NHOST_REGION: "us-east-1",
			NHOST_ADMIN_SECRET: "secret",
		});
		expect(config.subdomain).toBe("xyz");
	});

	it("treats whitespace-only NHOST_SUBDOMAIN as missing", () => {
		expect(() =>
			readAstropressNhostHostedConfig({
				NHOST_SUBDOMAIN: "   ",
				NHOST_REGION: "us-east-1",
				NHOST_ADMIN_SECRET: "secret",
			}),
		).toThrow();
	});

	it("trims whitespace from NHOST_REGION (pins L54 .trim())", () => {
		const config = readAstropressNhostHostedConfig({
			NHOST_SUBDOMAIN: "xyz",
			NHOST_REGION: "  us-east-1  ",
			NHOST_ADMIN_SECRET: "secret",
		});
		expect(config.region).toBe("us-east-1");
	});

	it("trims whitespace from NHOST_ADMIN_SECRET (pins L55 .trim())", () => {
		const config = readAstropressNhostHostedConfig({
			NHOST_SUBDOMAIN: "xyz",
			NHOST_REGION: "us-east-1",
			NHOST_ADMIN_SECRET: "  secret  ",
		});
		expect(config.adminSecret).toBe("secret");
	});
});

tests/webhooks-d1.test.ts.source:
// Mutation-coverage + behavioral tests for the D1 webhook store
// (src/sqlite-runtime/webhooks-d1.ts), exercised through the SqliteBackedD1Database
// fixture. The D1 sibling #137 added must match the sqlite store's create /
// list / delete / dispatch semantics — including the ML-DSA signing headers and
// the last_fired_at bookkeeping — on every host that provides a D1 binding.
import { describe, expect, it, vi } from "vitest";

import { verifyMlDsaMessage } from "../src/crypto-primitives.js";
import { createD1WebhookStore } from "../src/sqlite-runtime/webhooks-d1.js";
import { makeDb } from "./helpers/make-db.js";
import { SqliteBackedD1Database } from "./helpers/provider-test-fixtures.js";

const { loggerErrorSpy } = vi.hoisted(() => ({ loggerErrorSpy: vi.fn() }));

vi.mock("../src/runtime-logger", () => ({
	createLogger: () => ({
		info: vi.fn(),
		warn: vi.fn(),
		error: loggerErrorSpy,
	}),
}));

function makeStore(fetchImpl: typeof fetch = fetch) {
	const db = makeDb();
	const d1 = new SqliteBackedD1Database(db);
	return { db, store: createD1WebhookStore(d1, fetchImpl) };
}

describe("createD1WebhookStore", () => {
	it("create: returns a one-time ML-DSA verification bundle and stores only the secret", async () => {
		const { db, store } = makeStore();
		const { record, verification } = await store.create({
			url: "https://example.com/hook",
			events: ["content.published"],
		});

		expect(verification.algorithm).toBe("ML-DSA-65");
		expect(verification.keyId).toBe(record.id);
		expect(verification.publicKey.length).toBeGreaterThan(100);
		expect(record.id.startsWith("wh_")).toBe(true);
		expect(record.active).toBe(true);
		expect(record.events).toEqual(["content.published"]);

		const row = db.prepare("SELECT secret_hash FROM webhooks WHERE id = ?").get(record.id) as {
			secret_hash: string;
		};
		expect(row.secret_hash).not.toBe(verification.publicKey);
	});

	it("list: returns only active, non-deleted webhooks newest-first", async () => {
		const { store } = makeStore();
		const { record: r1 } = await store.create({
			url: "https://a.com/hook",
			events: ["content.published"],
		});
		const { record: r2 } = await store.create({
			url: "https://b.com/hook",
			events: ["media.uploaded"],
		});
		await store.delete(r1.id);

		const active = await store.list();
		expect(active.some((w) => w.id === r2.id)).toBe(true);
		expect(active.some((w) => w.id === r1.id)).toBe(false);
	});

	it("list: maps the active column to a boolean", async () => {
		const { db, store } = makeStore();
		db.prepare(
			"INSERT INTO webhooks (id, url, events, secret_hash, active) VALUES (?, ?, ?, ?, ?)",
		).run("wh_on", "https://on.example.com", JSON.stringify(["content.published"]), "secret", 1);
		db.prepare(
			"INSERT INTO webhooks (id, url, events, secret_hash, active) VALUES (?, ?, ?, ?, ?)",
		).run("wh_off", "https://off.example.com", JSON.stringify(["content.published"]), "secret", 0);

		const list = await store.list();
		expect(list.find((w) => w.id === "wh_on")?.active).toBe(true);
		expect(list.find((w) => w.id === "wh_off")?.active).toBe(false);
	});

	it("delete: soft-deletes (sets deleted_at) so the webhook drops out of list", async () => {
		const { db, store } = makeStore();
		const { record } = await store.create({
			url: "https://c.com/hook",
			events: ["content.deleted"],
		});

		await store.delete(record.id);
		const row = db.prepare("SELECT deleted_at FROM webhooks WHERE id = ?").get(record.id) as {
			deleted_at: string | null;
		};
		expect(row.deleted_at).not.toBeNull();
		expect((await store.list()).some((w) => w.id === record.id)).toBe(false);
	});

	it("dispatch: POSTs an ML-DSA-65 signed body with the documented headers", async () => {
		let captured: Request | undefined;
		const mockFetch = async (req: Request) => {
			captured = req;
			return new Response("ok", { status: 200 });
		};
		const { store } = makeStore(mockFetch as typeof fetch);
		const { record, verification } = await store.create({
			url: "https://hooks.example.com/receive",
			events: ["content.published"],
		});

		await store.dispatch("content.published", { id: "post-1", status: "published" });

		expect(captured?.method).toBe("POST");
		expect(captured?.headers.get("content-type")).toBe("application/json");
		expect(captured?.headers.get("x-astropress-signature-alg")).toBe("ML-DSA-65");
		expect(captured?.headers.get("x-astropress-key-id")).toBe(record.id);

		const sig = captured?.headers.get("x-astropress-signature");
		const body = await captured?.clone().text();
		expect(verifyMlDsaMessage(body, sig as string, verification.publicKey)).toBe(true);

		const parsed = JSON.parse(body ?? "{}") as {
			event?: string;
			payload?: { id?: string; status?: string };
			timestamp?: string;
		};
		expect(parsed.event).toBe("content.published");
		expect(parsed.payload).toEqual({ id: "post-1", status: "published" });
		expect(typeof parsed.timestamp).toBe("string");
	});

	it("dispatch: skips webhooks not subscribed to the event", async () => {
		let callCount = 0;
		const mockFetch = async () => {
			callCount++;
			return new Response("ok", { status: 200 });
		};
		const { store } = makeStore(mockFetch as typeof fetch);
		await store.create({ url: "https://media.example.com/hook", events: ["media.uploaded"] });

		await store.dispatch("content.published", { id: "x" });
		expect(callCount).toBe(0);
	});

	it("dispatch: records last_fired_at on success", async () => {
		const mockFetch = async () => new Response("ok", { status: 200 });
		const { db, store } = makeStore(mockFetch as typeof fetch);
		const { record } = await store.create({
			url: "https://hooks.example.com/receive",
			events: ["content.published"],
		});

		await store.dispatch("content.published", { id: "x" });
		const row = db.prepare("SELECT last_fired_at FROM webhooks WHERE id = ?").get(record.id) as {
			last_fired_at: string | null;
		};
		expect(row.last_fired_at).not.toBeNull();

		const listed = (await store.list()).find((w) => w.id === record.id);
		expect(typeof listed?.lastFiredAt).toBe("string");
	});

	it("dispatch: a failed delivery leaves last_fired_at NULL, logs the error, and does not throw", async () => {
		loggerErrorSpy.mockClear();
		const mockFetch = async () => {
			throw new Error("Network error");
		};
		const { db, store } = makeStore(mockFetch as typeof fetch);
		const { record } = await store.create({
			url: "https://fail.example.com/hook",
			events: ["content.updated"],
		});

		await expect(store.dispatch("content.updated", { id: "x" })).resolves.not.toThrow();

		const row = db.prepare("SELECT last_fired_at FROM webhooks WHERE id = ?").get(record.id) as {
			last_fired_at: string | null;
		};
		expect(row.last_fired_at).toBeNull();

		expect(loggerErrorSpy).toHaveBeenCalledTimes(1);
		const [message, meta] = loggerErrorSpy.mock.calls[0] as [string, { error?: unknown }];
		expect(message).toContain("content.updated");
		expect(message).toContain("https://fail.example.com/hook");
		expect(meta.error).toBeInstanceOf(Error);
	});
});

tests/platform-contracts.test.ts.source:
import {
	type AstropressPlatformAdapter,
	type AuthUser,
	assertProviderContract,
	type ContentStoreRecord,
	isAuthUserAdmin,
	type MediaAssetRecord,
	normalizeProviderCapabilities,
	type RevisionRecord,
} from "@astropress-diy/astropress";
import { describe, expect, it } from "vitest";

function createInMemoryAdapter(): AstropressPlatformAdapter {
	const records = new Map<string, ContentStoreRecord>();
	const media = new Map<string, MediaAssetRecord>();
	const revisions = new Map<string, RevisionRecord[]>();
	const sessions = new Map<string, AuthUser>();

	return {
		capabilities: normalizeProviderCapabilities({
			name: "custom",
			hostedAdmin: true,
			database: true,
			gitSync: true,
		}),
		content: {
			async list(kind) {
				return [...records.values()].filter((record) => !kind || record.kind === kind);
			},
			async get(id) {
				return records.get(id) ?? null;
			},
			async save(record) {
				records.set(record.id, record);
				return record;
			},
			async delete(id) {
				records.delete(id);
			},
		},
		media: {
			async put(asset) {
				media.set(asset.id, asset);
				return asset;
			},
			async get(id) {
				return media.get(id) ?? null;
			},
			async delete(id) {
				media.delete(id);
			},
		},
		revisions: {
			async list(recordId) {
				return revisions.get(recordId) ?? [];
			},
			async append(revision) {
				const existing = revisions.get(revision.recordId) ?? [];
				existing.push(revision);
				revisions.set(revision.recordId, existing);
				return revision;
			},
		},
		auth: {
			async signIn(email) {
				const user = { id: "u1", email, role: "admin" as const };
				sessions.set("session-1", user);
				return user;
			},
			async signOut(sessionId) {
				sessions.delete(sessionId);
			},
			async getSession(sessionId) {
				return sessions.get(sessionId) ?? null;
			},
		},
		gitSync: {
			async exportSnapshot(targetDir) {
				return { targetDir, fileCount: 4 };
			},
			async importSnapshot(sourceDir) {
				return { sourceDir, fileCount: 4 };
			},
		},
	};
}

describe("platform contracts", () => {
	it("fills omitted capability flags with false and preserves explicitly set flags", () => {
		const result = normalizeProviderCapabilities({
			name: "supabase",
			database: true,
		});
		expect(result.name).toBe("supabase");
		expect(result.database).toBe(true);
		const defaultFalseFlags = [
			"staticPublishing",
			"hostedAdmin",
			"previewEnvironments",
			"serverRuntime",
			"objectStorage",
			"gitSync",
		] as const;
		for (const flag of defaultFalseFlags) {
			expect(result[flag]).toBe(false);
		}
	});

	it("defaults database flag to false when omitted", () => {
		const result = normalizeProviderCapabilities({ name: "static-only" });
		expect(result.database).toBe(false);
	});

	it("preserves unknown provider names as-is", () => {
		const result = normalizeProviderCapabilities({
			name: "my-custom-provider",
		});
		expect(result.name).toBe("my-custom-provider");
	});

	it("accepts an adapter that satisfies the required contracts", async () => {
		const adapter = assertProviderContract(createInMemoryAdapter());
		const saved = await adapter.content.save({
			id: "page-1",
			kind: "page",
			slug: "home",
			status: "draft",
			title: "Home",
		});

		expect(saved.slug).toBe("home");
		expect((await adapter.content.list("page")).length).toBe(1);
	});

	it("rejects adapters that omit required stores", () => {
		expect(() =>
			assertProviderContract({
				capabilities: normalizeProviderCapabilities({ name: "custom" }),
			} as unknown as AstropressPlatformAdapter),
		).toThrow(/missing one or more required stores/i);
	});

	it("rejects adapters with no capabilities name", () => {
		expect(() =>
			assertProviderContract({
				...createInMemoryAdapter(),
				capabilities: { ...normalizeProviderCapabilities({ name: "" }) },
			}),
		).toThrow(/must declare a name/i);
	});

	it("rejects an adapter missing only the content store", () => {
		const base = createInMemoryAdapter();
		expect(() =>
			assertProviderContract({
				...base,
				content: undefined,
			} as unknown as AstropressPlatformAdapter),
		).toThrow(/missing one or more required stores/i);
	});

	it("rejects an adapter missing only the media store", () => {
		const base = createInMemoryAdapter();
		expect(() =>
			assertProviderContract({
				...base,
				media: undefined,
			} as unknown as AstropressPlatformAdapter),
		).toThrow(/missing one or more required stores/i);
	});

	it("rejects an adapter missing only the revisions store", () => {
		const base = createInMemoryAdapter();
		expect(() =>
			assertProviderContract({
				...base,
				revisions: undefined,
			} as unknown as AstropressPlatformAdapter),
		).toThrow(/missing one or more required stores/i);
	});

	it("rejects an adapter missing only the auth store", () => {
		const base = createInMemoryAdapter();
		expect(() =>
			assertProviderContract({
				...base,
				auth: undefined,
			} as unknown as AstropressPlatformAdapter),
		).toThrow(/missing one or more required stores/i);
	});

	it("normalizeProviderCapabilities preserves an explicitly-provided hostPanel and deployHook", () => {
		const result = normalizeProviderCapabilities({
			name: "custom",
			hostPanel: { url: "https://panel.example" },
			deployHook: { url: "https://deploy.example" },
		});
		expect(result.hostPanel).toEqual({ url: "https://panel.example" });
		expect(result.deployHook).toEqual({ url: "https://deploy.example" });
	});

	describe("isAuthUserAdmin", () => {
		const base: AuthUser = { id: "u", email: "x@y", role: "admin" };
		it("returns true when isAdmin === true", () => {
			expect(isAuthUserAdmin({ ...base, isAdmin: true })).toBe(true);
		});
		it("returns false when isAdmin is false", () => {
			expect(isAuthUserAdmin({ ...base, isAdmin: false })).toBe(false);
		});
		it("returns false when isAdmin is undefined", () => {
			expect(isAuthUserAdmin(base)).toBe(false);
		});
		// Pin the strict equality check: isAdmin === true must reject truthy non-true.
		it("returns false when isAdmin is a truthy non-boolean (1)", () => {
			expect(isAuthUserAdmin({ ...base, isAdmin: 1 as unknown as boolean })).toBe(false);
		});
	});

	it("supports full content CRUD lifecycle", async () => {
		const adapter = assertProviderContract(createInMemoryAdapter());

		const record = await adapter.content.save({
			id: "post-1",
			kind: "post",
			slug: "hello",
			status: "draft",
			title: "Hello",
		});
		expect(record.id).toBe("post-1");

		const fetched = await adapter.content.get("post-1");
		expect(fetched?.slug).toBe("hello");

		const all = await adapter.content.list("post");
		expect(all).toHaveLength(1);

		await adapter.content.delete("post-1");
		expect(await adapter.content.get("post-1")).toBeNull();
		expect(await adapter.content.list("post")).toHaveLength(0);
	});
});

tests/neon-adapter.test.ts.source:
import { describe, expect, it } from "vitest";
import {
	createAstropressNeonAdapter,
	createAstropressNeonHostedAdapter,
	readAstropressNeonHostedConfig,
} from "../src/adapters/neon.js";

describe("readAstropressNeonHostedConfig", () => {
	it("reads DATABASE_URL from env", () => {
		const config = readAstropressNeonHostedConfig({
			DATABASE_URL: "postgresql://user:pass@ep-example.us-east-1.aws.neon.tech/neondb",
		});
		expect(config.databaseUrl).toBe(
			"postgresql://user:pass@ep-example.us-east-1.aws.neon.tech/neondb",
		);
		expect(config.projectId).toBeUndefined();
		expect(config.apiBaseUrl).toBe("https://console.neon.tech");
	});

	it("includes project console URL when NEON_PROJECT_ID is set", () => {
		const config = readAstropressNeonHostedConfig({
			DATABASE_URL: "postgres://user:pass@ep-example.us-east-1.aws.neon.tech/neondb",
			NEON_PROJECT_ID: "proj-quiet-moon-123456",
		});
		expect(config.projectId).toBe("proj-quiet-moon-123456");
		expect(config.apiBaseUrl).toBe("https://console.neon.tech/app/projects/proj-quiet-moon-123456");
	});

	it("throws when DATABASE_URL is missing", () => {
		expect(() => readAstropressNeonHostedConfig({})).toThrow(/DATABASE_URL/);
	});

	it("throws when DATABASE_URL is not a postgres URL", () => {
		expect(() =>
			readAstropressNeonHostedConfig({
				DATABASE_URL: "mysql://user:pass@host/db",
			}),
		).toThrow(/postgres/);
	});

	it("accepts both postgres:// and postgresql:// schemes", () => {
		expect(() =>
			readAstropressNeonHostedConfig({
				DATABASE_URL: "postgres://u:p@host/db",
			}),
		).not.toThrow();
		expect(() =>
			readAstropressNeonHostedConfig({
				DATABASE_URL: "postgresql://u:p@host/db",
			}),
		).not.toThrow();
	});

	it("strips trailing whitespace from DATABASE_URL", () => {
		const config = readAstropressNeonHostedConfig({
			DATABASE_URL: "  postgres://u:p@host/db  ",
		});
		expect(config.databaseUrl).toBe("postgres://u:p@host/db");
	});
});

describe("createAstropressNeonAdapter", () => {
	it("creates an adapter with database-only capabilities", () => {
		const adapter = createAstropressNeonAdapter();
		expect(adapter.capabilities.name).toBe("neon");
		expect(adapter.capabilities.database).toBe(true);
		expect(adapter.capabilities.objectStorage).toBe(false);
		expect(adapter.capabilities.serverRuntime).toBe(false);
		expect(adapter.capabilities.hostedAdmin).toBe(false);
		expect(adapter.capabilities.previewEnvironments).toBe(false);
		expect(adapter.capabilities.gitSync).toBe(false);
	});

	it("accepts custom backing adapter options", () => {
		const adapter = createAstropressNeonAdapter({
			defaultCapabilities: { gitSync: true },
		});
		expect(adapter.capabilities.gitSync).toBe(true);
		expect(adapter.capabilities.database).toBe(true);
	});
});

describe("createAstropressNeonHostedAdapter", () => {
	const validEnv = {
		DATABASE_URL: "postgres://user:pass@ep-example.us-east-1.aws.neon.tech/neondb",
		NEON_PROJECT_ID: "proj-silent-leaf-987654",
	};

	it("creates an adapter with database-only capabilities", () => {
		const adapter = createAstropressNeonHostedAdapter({ env: validEnv });
		expect(adapter.capabilities.name).toBe("neon");
		expect(adapter.capabilities.database).toBe(true);
		expect(adapter.capabilities.objectStorage).toBe(false);
		expect(adapter.capabilities.serverRuntime).toBe(false);
		expect(adapter.capabilities.hostedAdmin).toBe(false);
		expect(adapter.capabilities.previewEnvironments).toBe(false);
		expect(adapter.capabilities.gitSync).toBe(false);
	});

	it("sets the Neon Console hostPanel link with project id in the URL and 'Neon Console' label", () => {
		const adapter = createAstropressNeonHostedAdapter({ env: validEnv });
		const panel = adapter.capabilities.hostPanel as {
			mode: string;
			url: string;
			label: string;
		};
		expect(panel).toBeTruthy();
		expect(panel.mode).toBe("link");
		expect(panel.url).toBe("https://console.neon.tech/app/projects/proj-silent-leaf-987654");
		expect(panel.label).toBe("Neon Console");
	});

	it("falls back to generic Neon Console URL when no project ID", () => {
		const adapter = createAstropressNeonHostedAdapter({
			env: { DATABASE_URL: "postgres://u:p@host/db" },
		});
		const panel = adapter.capabilities.hostPanel as { url: string };
		expect(panel.url).toBe("https://console.neon.tech");
	});

	it("accepts explicit config bypassing env read", () => {
		const adapter = createAstropressNeonHostedAdapter({
			config: {
				databaseUrl: "postgres://u:p@host/db",
				apiBaseUrl: "https://console.neon.tech",
			},
		});
		expect(adapter.capabilities.name).toBe("neon");
	});

	it("throws when DATABASE_URL is missing and no explicit config", () => {
		expect(() => createAstropressNeonHostedAdapter({ env: {} })).toThrow(/DATABASE_URL/);
	});

	it("prefers NEON_DATABASE_URL over DATABASE_URL (pins ?? operand order)", () => {
		const config = readAstropressNeonHostedConfig({
			NEON_DATABASE_URL: "postgres://neon:pw@neon-host/db",
			DATABASE_URL: "postgres://other:pw@other-host/db",
		});
		expect(config.databaseUrl).toBe("postgres://neon:pw@neon-host/db");
	});

	it("trims whitespace from NEON_PROJECT_ID (pins .trim() call)", () => {
		const config = readAstropressNeonHostedConfig({
			DATABASE_URL: "postgres://u:p@host/db",
			NEON_PROJECT_ID: "  proj-spaced-id  ",
		});
		expect(config.projectId).toBe("proj-spaced-id");
	});

	it("trims whitespace from NEON_DATABASE_URL (pins .trim() call)", () => {
		const config = readAstropressNeonHostedConfig({
			NEON_DATABASE_URL: "  postgres://neon:pw@host/db  ",
		});
		expect(config.databaseUrl).toBe("postgres://neon:pw@host/db");
	});

	it("explicit defaultCapabilities.hostPanel overrides the Neon Console default (pins ?? fallback)", () => {
		const customPanel = {
			mode: "iframe" as const,
			url: "https://my-custom-panel.example",
			label: "Custom",
		};
		const adapter = createAstropressNeonHostedAdapter({
			env: validEnv,
			defaultCapabilities: { hostPanel: customPanel },
		});
		expect(adapter.capabilities.hostPanel).toEqual(customPanel);
	});

	it("createAstropressNeonAdapter merges user-supplied defaultCapabilities (pins spread order)", () => {
		// User overrides hostedAdmin → true. The spread {...options.defaultCapabilities}
		// AFTER the literal must apply, so hostedAdmin should be true here.
		const adapter = createAstropressNeonAdapter({
			defaultCapabilities: { hostedAdmin: true, objectStorage: true },
		});
		expect(adapter.capabilities.hostedAdmin).toBe(true);
		expect(adapter.capabilities.objectStorage).toBe(true);
		// database: true comes from the literal and is NOT overridden by the spread.
		expect(adapter.capabilities.database).toBe(true);
	});
});

tests/upgrade-path-e2e.test.ts.source:
/**
 * Upgrade path E2E tests — verifies schema migration, compat layer, and rollback round-trips.
 *
 * All tests are fully in-process: DatabaseSync + real schema SQL, no CLI invocations.
 */

import { mkdirSync, mkdtempSync, rmSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { DatabaseSync } from "node:sqlite";
import { afterEach, beforeEach, describe, expect, it } from "vitest";

import {
	checkSchemaVersionAhead,
	rollbackAstropressLastMigration,
	runAstropressMigrations,
} from "../src/sqlite-bootstrap.js";
import { ensureLegacySchemaCompatibility, getTableColumns } from "../src/sqlite-schema-compat.js";
import { makeDb } from "./helpers/make-db.js";

// Minimal v0.0.1 schema — mirrors what a real pre-upgrade backup would contain
const V001_SCHEMA = `
  CREATE TABLE IF NOT EXISTS content_entries (
    slug TEXT PRIMARY KEY,
    title TEXT NOT NULL,
    kind TEXT NOT NULL DEFAULT 'post'
  );

  CREATE TABLE IF NOT EXISTS content_overrides (
    slug TEXT PRIMARY KEY,
    title TEXT NOT NULL,
    status TEXT NOT NULL CHECK(status IN ('draft', 'published')),
    body TEXT,
    seo_title TEXT,
    meta_description TEXT,
    excerpt TEXT,
    og_title TEXT,
    og_description TEXT,
    og_image TEXT,
    canonical_url_override TEXT,
    robots_directive TEXT,
    updated_at TEXT DEFAULT CURRENT_TIMESTAMP,
    updated_by TEXT NOT NULL
  );

  CREATE TABLE IF NOT EXISTS content_revisions (
    id TEXT PRIMARY KEY,
    slug TEXT NOT NULL,
    source TEXT NOT NULL DEFAULT 'reviewed',
    title TEXT NOT NULL,
    status TEXT NOT NULL,
    body TEXT,
    seo_title TEXT,
    meta_description TEXT,
    excerpt TEXT,
    og_title TEXT,
    og_description TEXT,
    og_image TEXT,
    canonical_url_override TEXT,
    robots_directive TEXT,
    created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
    created_by TEXT,
    updated_at TEXT NOT NULL,
    updated_by TEXT NOT NULL
  );

  CREATE TABLE IF NOT EXISTS media_assets (
    id TEXT PRIMARY KEY,
    filename TEXT NOT NULL,
    mime_type TEXT NOT NULL
  );

  CREATE TABLE IF NOT EXISTS schema_migrations (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    name TEXT NOT NULL UNIQUE,
    applied_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
  );

  CREATE TABLE IF NOT EXISTS admin_users (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    email TEXT NOT NULL UNIQUE,
    password_hash TEXT NOT NULL,
    role TEXT NOT NULL DEFAULT 'editor'
  );
`;

let tempDir: string;

beforeEach(() => {
	tempDir = mkdtempSync(join(tmpdir(), "astropress-upgrade-"));
});

afterEach(() => {
	rmSync(tempDir, { recursive: true, force: true });
});

describe("compat upgrade: old schema → current schema", () => {
	it("ensureLegacySchemaCompatibility adds metadata and scheduled_at to v0.0.1 schema", () => {
		const db = new DatabaseSync(":memory:");
		db.exec(V001_SCHEMA);

		const overrideCols = getTableColumns(db, "content_overrides");
		expect(overrideCols).not.toContain("metadata");

		ensureLegacySchemaCompatibility(db);

		const colsAfter = getTableColumns(db, "content_overrides");
		expect(colsAfter).toContain("metadata");
		expect(colsAfter).toContain("scheduled_at");
		db.close();
	});

	it("content rows survive the compat upgrade", () => {
		const db = new DatabaseSync(":memory:");
		db.exec(V001_SCHEMA);

		db.prepare(
			`INSERT INTO content_overrides (slug, title, status, updated_by)
       VALUES ('surviving-post', 'Surviving Post', 'published', 'admin@example.com')`,
		).run();

		ensureLegacySchemaCompatibility(db);

		const row = db
			.prepare("SELECT slug, title FROM content_overrides WHERE slug = 'surviving-post'")
			.get() as { slug: string; title: string } | undefined;

		expect(row?.slug).toBe("surviving-post");
		expect(row?.title).toBe("Surviving Post");
		db.close();
	});
});

describe("migration runner", () => {
	it("applies pending migrations and records them in schema_migrations", () => {
		const db = makeDb();

		const migrationsDir = join(tempDir, "migrations");
		mkdirSync(migrationsDir);
		writeFileSync(
			join(migrationsDir, "0001_add_test_column.sql"),
			"ALTER TABLE content_overrides ADD COLUMN upgrade_test_col TEXT;",
		);
		writeFileSync(
			join(migrationsDir, "0001_add_test_column.down.sql"),
			"-- cannot drop column in SQLite",
		);

		const result = runAstropressMigrations(db, migrationsDir);
		expect(result.applied).toContain("0001_add_test_column.sql");

		const cols = getTableColumns(db, "content_overrides");
		expect(cols).toContain("upgrade_test_col");
		db.close();
	});

	it("rollbackAstropressLastMigration removes the last migration record", () => {
		const db = makeDb();

		const migrationsDir = join(tempDir, "migrations");
		mkdirSync(migrationsDir);
		writeFileSync(
			join(migrationsDir, "0001_rollback_test.sql"),
			"ALTER TABLE content_overrides ADD COLUMN rollback_test_col TEXT;",
		);
		writeFileSync(
			join(migrationsDir, "0001_rollback_test.down.sql"),
			"-- rollback: column removal not supported in SQLite without table rebuild",
		);

		runAstropressMigrations(db, migrationsDir);

		const beforeCount = (
			db.prepare("SELECT COUNT(*) as c FROM schema_migrations").get() as {
				c: number;
			}
		).c;
		const rolledBack = rollbackAstropressLastMigration(db);
		const afterCount = (
			db.prepare("SELECT COUNT(*) as c FROM schema_migrations").get() as {
				c: number;
			}
		).c;

		expect(rolledBack).toBe("0001_rollback_test.sql");
		expect(afterCount).toBe(beforeCount - 1);
		db.close();
	});
});

describe("checkSchemaVersionAhead", () => {
	it("returns isAhead:true when DB has more migrations than the baseline", () => {
		const db = makeDb();

		const migrationsDir = join(tempDir, "migrations");
		mkdirSync(migrationsDir);
		for (let i = 1; i <= 5; i++) {
			writeFileSync(
				join(migrationsDir, `000${i}_migration.sql`),
				`ALTER TABLE content_overrides ADD COLUMN extra_col_${i} TEXT;`,
			);
		}

		runAstropressMigrations(db, migrationsDir);

		const result = checkSchemaVersionAhead(db, 1);
		expect(result).not.toBeNull();
		expect(result?.isAhead).toBe(true);
		expect(result?.dbCount).toBeGreaterThan(1);
		db.close();
	});

	it("returns isAhead:false on a fresh schema with no extra migrations", () => {
		const db = makeDb();

		// No migrations applied — baseline is 1 (framework migration)
		const result = checkSchemaVersionAhead(db, 1);
		expect(result).not.toBeNull();
		// The fresh schema has 0 rows in schema_migrations (framework uses ensureLegacySchemaCompatibility, not migrations table)
		expect(result?.isAhead).toBe(false);
		db.close();
	});
});

