import { describe, expect, it } from "vitest";
import { collectMediaIds, selectTestimonialsForSection } from "../../src/sections/render-prep";
import type { Section, TestimonialsSection } from "../../src/sections/schema";

describe("collectMediaIds — coverage", () => {
	it("returns empty array for empty input", () => {
		expect(collectMediaIds([])).toEqual([]);
	});

	it("hero without mediaId yields no id", () => {
		const r = collectMediaIds([{ id: "h", kind: "hero", headline: "h", alignment: "start" }]);
		expect(r).toEqual([]);
	});

	it("image-text empty mediaId yields no id", () => {
		const r = collectMediaIds([
			{
				id: "i",
				kind: "image-text",
				heading: "H",
				body: "<p>b</p>",
				mediaId: "",
				imageSide: "start",
			},
		]);
		expect(r).toEqual([]);
	});

	it("preserves first-seen ordering across kinds", () => {
		const sections: Section[] = [
			{
				id: "1",
				kind: "hero",
				headline: "h",
				alignment: "start",
				mediaId: "m1",
			},
			{ id: "2", kind: "gallery", mediaIds: ["m2", "m1"], columns: 3 },
			{
				id: "3",
				kind: "image-text",
				heading: "x",
				body: "<p>x</p>",
				mediaId: "m3",
				imageSide: "start",
			},
		];
		expect(collectMediaIds(sections)).toEqual(["m1", "m2", "m3"]);
	});

	it("ignores other kinds (testimonials, faq, cta-banner, rich-text, feature-grid)", () => {
		const sections: Section[] = [
			{ id: "t", kind: "testimonials", source: "approved", layout: "grid" },
			{ id: "f", kind: "faq", items: [] },
			{
				id: "c",
				kind: "cta-banner",
				headline: "x",
				primaryCta: { label: "x", href: "/" },
				tone: "neutral",
			},
			{ id: "r", kind: "rich-text", html: "<p>x</p>" },
			{ id: "fg", kind: "feature-grid", heading: "h", columns: 3, items: [] },
		];
		expect(collectMediaIds(sections)).toEqual([]);
	});
});

describe("selectTestimonialsForSection — coverage", () => {
	const all = [
		{ id: "a", name: "A", quote: "q", featured: true, status: "approved" },
		{ id: "b", name: "B", quote: "q", featured: false, status: "approved" },
		{ id: "c", name: "C", quote: "q", featured: true, status: "pending" },
		{ id: "d", name: "D", quote: "q", featured: true }, // status undefined
	];

	it("featured: missing status defaults to 'approved' and is included", () => {
		const sec: TestimonialsSection = {
			id: "t",
			kind: "testimonials",
			source: "featured",
			layout: "grid",
		};
		const picked = selectTestimonialsForSection(sec, all);
		expect(picked.map((p) => p.id).sort()).toEqual(["a", "d"]);
	});

	it("featured: featured=false excluded even when approved", () => {
		const sec: TestimonialsSection = {
			id: "t",
			kind: "testimonials",
			source: "featured",
			layout: "grid",
		};
		const picked = selectTestimonialsForSection(sec, all);
		expect(picked.find((p) => p.id === "b")).toBeUndefined();
	});

	it("approved: includes 'd' (undefined status defaults to approved)", () => {
		const sec: TestimonialsSection = {
			id: "t",
			kind: "testimonials",
			source: "approved",
			layout: "grid",
		};
		const picked = selectTestimonialsForSection(sec, all);
		expect(picked.find((p) => p.id === "d")).toBeDefined();
	});

	it("approved: pending status excluded", () => {
		const sec: TestimonialsSection = {
			id: "t",
			kind: "testimonials",
			source: "approved",
			layout: "grid",
		};
		const picked = selectTestimonialsForSection(sec, all);
		expect(picked.find((p) => p.id === "c")).toBeUndefined();
	});

	it("ids without ids array falls through to approved-filter branch", () => {
		// The runtime logic checks `section.source === "ids" && section.ids`
		// so when ids array is missing it falls into the else (approved branch).
		const sec = {
			id: "t",
			kind: "testimonials",
			source: "ids",
			layout: "grid",
		} as TestimonialsSection;
		const picked = selectTestimonialsForSection(sec, all);
		// Falls through to the second `if (source === featured)` test (false),
		// then the final approved branch — so we get all approved ones.
		expect(picked.map((p) => p.id).sort()).toEqual(["a", "b", "d"]);
	});

	it("ids with empty list selects nothing", () => {
		const sec: TestimonialsSection = {
			id: "t",
			kind: "testimonials",
			source: "ids",
			layout: "grid",
			ids: [],
		};
		// Empty Set means filter excludes all — returns [].
		// But the runtime check `section.ids` is truthy for empty array,
		// so the ids branch IS taken.
		const picked = selectTestimonialsForSection(sec, all);
		expect(picked).toEqual([]);
	});

	it("ids does not match unknown id", () => {
		const sec: TestimonialsSection = {
			id: "t",
			kind: "testimonials",
			source: "ids",
			layout: "grid",
			ids: ["zzz"],
		};
		expect(selectTestimonialsForSection(sec, all)).toEqual([]);
	});
});

tests/admin-session-middleware.test.ts.source:
import { beforeEach, describe, expect, it, vi } from "vitest";

// Pull in the ambient `App.Locals` augmentation (contributes no runtime code).
import type {} from "../src/access/locals";
import {
	LEGACY_SESSION_COOKIE,
	LOCAL_SESSION_COOKIE,
	SECURE_SESSION_COOKIE,
} from "../src/admin-action-utils-data";

const getRuntimeSessionUser = vi.fn();
const getRuntimeCsrfToken = vi.fn();
const getLoginSecurityConfig = vi.fn();

vi.mock("../src/runtime-admin-auth", () => ({
	getRuntimeSessionUser: (...args: unknown[]) => getRuntimeSessionUser(...args),
	getRuntimeCsrfToken: (...args: unknown[]) => getRuntimeCsrfToken(...args),
}));
vi.mock("../src/runtime-env", () => ({
	getLoginSecurityConfig: (...args: unknown[]) => getLoginSecurityConfig(...args),
}));

const { createAstropressAdminSessionMiddleware } = await import("../src/admin-session-middleware");

type Cookie = { value: string };

function makeContext(cookies: Record<string, string>, seedLocals: Record<string, unknown> = {}) {
	const locals = { ...seedLocals } as App.Locals;
	return {
		cookies: {
			get(name: string): Cookie | undefined {
				return name in cookies ? { value: cookies[name] } : undefined;
			},
		},
		locals,
	};
}

const response = new Response("ok");
const next = vi.fn(async () => response);

beforeEach(() => {
	vi.clearAllMocks();
	getLoginSecurityConfig.mockReturnValue({ secureCookies: false });
	next.mockResolvedValue(response);
});

describe("createAstropressAdminSessionMiddleware", () => {
	it("populates locals.adminUser and csrfToken from a valid local session cookie", async () => {
		getRuntimeSessionUser.mockResolvedValue({
			email: "admin@example.com",
			role: "admin",
			name: "Admin",
			isAdmin: true,
		});
		getRuntimeCsrfToken.mockResolvedValue("csrf-123");

		const mw = createAstropressAdminSessionMiddleware();
		const ctx = makeContext({ [LOCAL_SESSION_COOKIE]: "tok" });
		const result = await mw(ctx, next);

		expect(getRuntimeSessionUser).toHaveBeenCalledWith("tok", ctx.locals);
		expect(ctx.locals.adminUser).toEqual({
			id: "admin@example.com",
			email: "admin@example.com",
			isAdmin: true,
			name: "Admin",
		});
		expect(ctx.locals.csrfToken).toBe("csrf-123");
		expect(next).toHaveBeenCalledOnce();
		expect(result).toBe(response);
	});

	it("reads the secure cookie when secureCookies is true", async () => {
		getLoginSecurityConfig.mockReturnValue({ secureCookies: true });
		getRuntimeSessionUser.mockResolvedValue({
			email: "e@example.com",
			role: "editor",
			name: "Ed",
			isAdmin: false,
		});
		getRuntimeCsrfToken.mockResolvedValue("csrf");

		const mw = createAstropressAdminSessionMiddleware();
		// Only the secure cookie is present; a local cookie must be ignored here.
		const ctx = makeContext({ [SECURE_SESSION_COOKIE]: "sec-tok" });
		await mw(ctx, next);

		expect(getRuntimeSessionUser).toHaveBeenCalledWith("sec-tok", ctx.locals);
		expect(ctx.locals.adminUser?.isAdmin).toBe(false);
	});

	it("falls back to the legacy cookie", async () => {
		getRuntimeSessionUser.mockResolvedValue({
			email: "a@example.com",
			role: "admin",
			name: "A",
			isAdmin: true,
		});
		getRuntimeCsrfToken.mockResolvedValue(null);

		const mw = createAstropressAdminSessionMiddleware();
		const ctx = makeContext({ [LEGACY_SESSION_COOKIE]: "legacy-tok" });
		await mw(ctx, next);

		expect(getRuntimeSessionUser).toHaveBeenCalledWith("legacy-tok", ctx.locals);
		expect(ctx.locals.adminUser?.email).toBe("a@example.com");
		expect(ctx.locals.csrfToken).toBeUndefined();
	});

	it("no-ops when no session cookie is present", async () => {
		const mw = createAstropressAdminSessionMiddleware();
		const ctx = makeContext({});
		await mw(ctx, next);

		expect(getRuntimeSessionUser).not.toHaveBeenCalled();
		expect(ctx.locals.adminUser).toBeUndefined();
		expect(next).toHaveBeenCalledOnce();
	});

	it("leaves adminUser undefined when the token resolves to no user", async () => {
		getRuntimeSessionUser.mockResolvedValue(null);

		const mw = createAstropressAdminSessionMiddleware();
		const ctx = makeContext({ [LOCAL_SESSION_COOKIE]: "stale" });
		await mw(ctx, next);

		expect(getRuntimeSessionUser).toHaveBeenCalledOnce();
		expect(getRuntimeCsrfToken).not.toHaveBeenCalled();
		expect(ctx.locals.adminUser).toBeUndefined();
	});

	it("never clobbers an adminUser a host or the harness already set", async () => {
		const preset = { id: "harness", email: "harness@example.com", isAdmin: true, name: "Harness" };
		const mw = createAstropressAdminSessionMiddleware();
		const ctx = makeContext({ [LOCAL_SESSION_COOKIE]: "tok" }, { adminUser: preset });
		await mw(ctx, next);

		expect(getRuntimeSessionUser).not.toHaveBeenCalled();
		expect(ctx.locals.adminUser).toBe(preset);
	});
});

