// Local-store fallback paths for runtime-actions-password-reset.ts.
// When App.Locals has no D1 binding, withLocalStoreFallback dispatches to the
// LocalAdminStore module — these tests assert that the arrow-function fallbacks
// forward their arguments and return values rather than returning undefined.
import { afterAll, afterEach, beforeEach, describe, expect, it, vi } from "vitest";

const { localStoreMock } = vi.hoisted(() => ({
	localStoreMock: {
		createPasswordResetToken: vi.fn(),
		getPasswordResetRequest: vi.fn(),
		consumePasswordResetToken: vi.fn(),
	},
}));

vi.mock("../src/local-runtime-modules", () => ({
	loadLocalAdminStore: vi.fn().mockResolvedValue(localStoreMock),
}));
vi.mock("../src/local-runtime-modules.js", () => ({
	loadLocalAdminStore: vi.fn().mockResolvedValue(localStoreMock),
}));

// biome-ignore format: single-line typeof import required for esbuild/oxc compatibility
let createRuntimePasswordResetToken: typeof import("../src/runtime-actions-password-reset.js").createRuntimePasswordResetToken;
// biome-ignore format: single-line typeof import required for esbuild/oxc compatibility
let getRuntimePasswordResetRequest: typeof import("../src/runtime-actions-password-reset.js").getRuntimePasswordResetRequest;
// biome-ignore format: single-line typeof import required for esbuild/oxc compatibility
let consumeRuntimePasswordResetToken: typeof import("../src/runtime-actions-password-reset.js").consumeRuntimePasswordResetToken;

const NO_DB_LOCALS = undefined;

beforeEach(async () => {
	vi.resetModules();
	({
		createRuntimePasswordResetToken,
		getRuntimePasswordResetRequest,
		consumeRuntimePasswordResetToken,
	} = await import("../src/runtime-actions-password-reset.js"));
	localStoreMock.createPasswordResetToken.mockReset();
	localStoreMock.getPasswordResetRequest.mockReset();
	localStoreMock.consumePasswordResetToken.mockReset();
});

afterEach(() => {
	vi.clearAllMocks();
});

afterAll(() => {
	vi.resetModules();
});

describe("createRuntimePasswordResetToken — local fallback", () => {
	it("forwards (email, actor) to localStore.createPasswordResetToken and returns its result", async () => {
		const sentinel = { ok: true as const, resetUrl: "/local/reset?token=xyz" };
		localStoreMock.createPasswordResetToken.mockResolvedValueOnce(sentinel);
		const actor = { email: "admin@local", role: "admin" as const, name: "Local Admin" };
		const result = await createRuntimePasswordResetToken("u@local", actor, NO_DB_LOCALS);
		expect(localStoreMock.createPasswordResetToken).toHaveBeenCalledWith("u@local", actor);
		expect(result).toBe(sentinel);
	});

	it("coerces an undefined actor to null when forwarding", async () => {
		const sentinel = { ok: true as const, resetUrl: null };
		localStoreMock.createPasswordResetToken.mockResolvedValueOnce(sentinel);
		const result = await createRuntimePasswordResetToken("u@local", undefined, NO_DB_LOCALS);
		expect(localStoreMock.createPasswordResetToken).toHaveBeenCalledWith("u@local", null);
		expect(result).toBe(sentinel);
	});
});

describe("getRuntimePasswordResetRequest — local fallback", () => {
	it("forwards the token to localStore.getPasswordResetRequest and returns its result", async () => {
		const sentinel = { email: "u@local", name: "U", role: "editor" as const, expiresAt: "x" };
		localStoreMock.getPasswordResetRequest.mockResolvedValueOnce(sentinel);
		const result = await getRuntimePasswordResetRequest("raw-token", NO_DB_LOCALS);
		expect(localStoreMock.getPasswordResetRequest).toHaveBeenCalledWith("raw-token");
		expect(result).toBe(sentinel);
	});
});

describe("consumeRuntimePasswordResetToken — local fallback", () => {
	it("forwards (token, password) to localStore.consumePasswordResetToken and returns its result", async () => {
		const sentinel = { ok: true as const, user: { email: "u@local", role: "editor", name: "U" } };
		localStoreMock.consumePasswordResetToken.mockResolvedValueOnce(sentinel);
		const result = await consumeRuntimePasswordResetToken("raw-token", "pw", NO_DB_LOCALS);
		expect(localStoreMock.consumePasswordResetToken).toHaveBeenCalledWith("raw-token", "pw");
		expect(result).toBe(sentinel);
	});
});

tests/admin-embed-url.test.ts.source:
// Scheme/host validation for operator-configured embed URLs (#109). The admin
// CMS + host panels feed these into iframe src / href, so the allowed set
// (https anywhere, http only for loopback) and the rejected set (every other
// scheme + malformed values) are both asserted.
import { describe, expect, it } from "vitest";

import { validateEmbedUrl } from "../src/admin-embed-url.js";

describe("validateEmbedUrl — allowed", () => {
	it("accepts an https URL and returns the normalised href", () => {
		const r = validateEmbedUrl("https://cms.example.com/admin");
		expect(r.ok).toBe(true);
		expect(r.url).toBe("https://cms.example.com/admin");
	});

	it("accepts http only for loopback hosts", () => {
		for (const host of ["localhost", "127.0.0.1", "[::1]", "0.0.0.0", "app.localhost"]) {
			const r = validateEmbedUrl(`http://${host}:4321/panel`);
			expect(r.ok, host).toBe(true);
		}
	});
});

describe("validateEmbedUrl — rejected", () => {
	it("rejects http to a non-loopback host", () => {
		const r = validateEmbedUrl("http://cms.example.com/admin");
		expect(r.ok).toBe(false);
		expect(r.reason).toMatch(/https/i);
	});

	it("rejects javascript: URLs", () => {
		expect(validateEmbedUrl("javascript:alert(document.cookie)").ok).toBe(false);
	});

	it("rejects data: URLs", () => {
		expect(validateEmbedUrl("data:text/html,<script>alert(1)</script>").ok).toBe(false);
	});

	it("rejects file: URLs", () => {
		expect(validateEmbedUrl("file:///etc/passwd").ok).toBe(false);
	});

	it("rejects vbscript: and blob: URLs", () => {
		expect(validateEmbedUrl("vbscript:msgbox(1)").ok).toBe(false);
		expect(validateEmbedUrl("blob:https://x/y").ok).toBe(false);
	});

	it("rejects empty, whitespace, and missing values", () => {
		expect(validateEmbedUrl("").ok).toBe(false);
		expect(validateEmbedUrl("   ").ok).toBe(false);
		expect(validateEmbedUrl(null).ok).toBe(false);
		expect(validateEmbedUrl(undefined).ok).toBe(false);
	});

	it("rejects a relative or non-absolute value", () => {
		expect(validateEmbedUrl("/just/a/path").ok).toBe(false);
		expect(validateEmbedUrl("not a url").ok).toBe(false);
	});

	it("never returns a url on rejection", () => {
		const r = validateEmbedUrl("javascript:alert(1)");
		expect(r.ok).toBe(false);
		expect(r.url).toBeUndefined();
		expect(typeof r.reason).toBe("string");
	});

	// Each rejection path returns a DISTINCT reason; asserting the exact string
	// pins the branch (kills the ConditionalExpression/StringLiteral mutants that
	// only an `.ok === false` check would let survive).
	it("reports the no-URL reason for empty / whitespace-only input", () => {
		expect(validateEmbedUrl("").reason).toBe("No embed URL is configured.");
		// `.trim()` matters: whitespace must be treated as empty, not parsed.
		expect(validateEmbedUrl("   ").reason).toBe("No embed URL is configured.");
		expect(validateEmbedUrl(null).reason).toBe("No embed URL is configured.");
	});

	it("reports the not-a-valid-URL reason for an unparseable value", () => {
		expect(validateEmbedUrl("not a url").reason).toBe("Embed URL is not a valid absolute URL.");
	});

	it("reports the https-required reason for http to a non-loopback host", () => {
		expect(validateEmbedUrl("http://cms.example.com/x").reason).toBe(
			"Embed URL must use https (http is allowed only for localhost).",
		);
	});

	it("reports the scheme-not-allowed reason naming the rejected scheme", () => {
		// Template-literal + final-branch coverage: the scheme must appear verbatim.
		expect(validateEmbedUrl("ftp://example.com/x").reason).toBe(
			'Embed URL scheme "ftp:" is not allowed.',
		);
		expect(validateEmbedUrl("file:///etc/passwd").reason).toBe(
			'Embed URL scheme "file:" is not allowed.',
		);
	});

	it("accepts https but rejects every non-loopback non-https scheme reaching the parser", () => {
		// Pins the `=== "https:"` branch: a parseable non-https URL is never ok.
		expect(validateEmbedUrl("https://ok.example.com/").ok).toBe(true);
		expect(validateEmbedUrl("ftp://ok.example.com/").ok).toBe(false);
	});
});

tests/image-srcset.test.ts.source:
import { describe, expect, it } from "vitest";
import { generateSrcset } from "../src/local-image-storage.js";
import { ensureLegacySchemaCompatibility, getTableColumns } from "../src/sqlite-schema-compat.js";
import { makeDb } from "./helpers/make-db.js";

// ─── generateSrcset ───────────────────────────────────────────────────────────

describe("generateSrcset() — basic output format", () => {
	it("returns null when Sharp is unavailable (storeVariant never called)", async () => {
		// In the test environment Sharp may or may not be available.
		// We test the null-return path by injecting a storeVariant that always returns null.
		// If Sharp IS available this exercises the full path but still returns null due to storeVariant.
		const result = await generateSrcset(
			new Uint8Array([0xff, 0xd8, 0xff]), // minimal JPEG magic bytes
			"/images/uploads/test.jpg",
			async () => null,
		);
		expect(result).toBeNull();
	});

	it("builds a srcset string from stored variant paths", async () => {
		// Inject a mock storeVariant that returns deterministic paths
		const stored: string[] = [];
		const storeVariant = async (filename: string, _bytes: Uint8Array): Promise<string | null> => {
			const path = `/images/uploads/${filename}`;
			stored.push(path);
			return path;
		};

		// Use a 1×1 white PNG as minimal image data that Sharp can process
		// (base64: iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAYAAAAfFcSJAAAADUlEQVR42mNkYPhfDwAChwGA60e6kgAAAABJRU5ErkJggg==)
		const pngBase64 =
			"iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAYAAAAfFcSJAAAADUlEQVR42mNkYPhfDwAChwGA60e6kgAAAABJRU5ErkJggg==";
		let pngBytes: Uint8Array;
		try {
			pngBytes = new Uint8Array(Buffer.from(pngBase64, "base64"));
		} catch {
			pngBytes = new Uint8Array(0);
		}

		if (pngBytes.length === 0) {
			return; // Skip if Buffer not available
		}

		const result = await generateSrcset(pngBytes, "/images/uploads/photo.jpg", storeVariant);

		if (result === null) {
			// Sharp not available in this environment — null is the correct graceful fallback
			expect(result).toBeNull();
			return;
		}

		// When Sharp is available, result should be a space-separated srcset string
		expect(typeof result).toBe("string");
		const parts = result.split(", ");
		// Each part must end with a width descriptor like "400w"
		for (const part of parts) {
			expect(part).toMatch(/\d+w$/);
		}
	});
});

// ─── Structural: srcset field on MediaAssetRecord ─────────────────────────────

describe("MediaAssetRecord.srcset field", () => {
	it("is defined as an optional string on the MediaAssetRecord interface", async () => {
		const { platform_contracts } = await import("../src/platform-contracts.js").catch(() => ({
			platform_contracts: null,
		}));
		// Structural test: TypeScript compilation catches type errors.
		// At runtime we verify the shape is valid by constructing a conforming object.
		const record = {
			id: "media-1",
			filename: "photo.jpg",
			mimeType: "image/jpeg",
			srcset: "/images/photo-400w.webp 400w, /images/photo-800w.webp 800w",
		};
		expect(record.srcset).toContain("400w");
		expect(record.srcset).toContain("800w");
		void platform_contracts;
	});

	it("srcset is optional — record without it is valid", () => {
		const record = {
			id: "media-2",
			filename: "icon.png",
			mimeType: "image/png",
		};
		expect((record as Record<string, unknown>).srcset).toBeUndefined();
	});
});

// ─── sqlite-schema-compat: srcset column migration ───────────────────────────

describe("srcset column migration (ensureLegacySchemaCompatibility)", () => {
	it("adds srcset column to media_assets when missing", () => {
		const db = makeDb();
		ensureLegacySchemaCompatibility(db);
		expect(getTableColumns(db, "media_assets")).toContain("srcset");
	});
});

