import {
	getRuntimeMediaResolutionOptions,
	resolveMediaUrl,
	resolveRuntimeMediaUrl,
} from "@astropress-diy/astropress";
import { describe, expect, it } from "vitest";

const sampleRecord = {
	id: "img-001",
	sourceUrl: "https://legacy.example.org/wp-content/uploads/hero.jpg",
	localPath: "/images/home/community-garden-hero.jpg",
	r2Key: "images/home/community-garden-hero.jpg",
};

describe("resolveMediaUrl()", () => {
	it("returns localPath in development mode", () => {
		const url = resolveMediaUrl(sampleRecord, { mode: "development" });
		expect(url).toBe(sampleRecord.localPath);
	});

	it("development mode short-circuits even when r2BaseUrl is set (kills dev-branch mutants)", () => {
		// Critical: dev mode must NOT build an R2 URL even if one is configured.
		// Original returns localPath; if the dev short-circuit were removed we'd
		// fall through to the deployment branch and synthesize an R2 URL.
		const url = resolveMediaUrl(sampleRecord, {
			mode: "development",
			r2BaseUrl: "https://cdn.example.org",
		});
		expect(url).toBe(sampleRecord.localPath);
		expect(url).not.toContain("cdn.example.org");
	});

	it("returns localPath in deployment mode when no r2BaseUrl is provided", () => {
		const url = resolveMediaUrl(sampleRecord, { mode: "deployment" });
		expect(url).toBe(sampleRecord.localPath);
	});

	it("returns r2 URL in deployment mode when r2BaseUrl is provided", () => {
		const url = resolveMediaUrl(sampleRecord, {
			mode: "deployment",
			r2BaseUrl: "https://cdn.example.org",
		});
		expect(url).toBe("https://cdn.example.org/images/home/community-garden-hero.jpg");
	});

	it("strips trailing slash from r2BaseUrl before joining", () => {
		const url = resolveMediaUrl(sampleRecord, {
			mode: "deployment",
			r2BaseUrl: "https://cdn.example.org/",
		});
		expect(url).not.toContain("//images");
		expect(url).toBe("https://cdn.example.org/images/home/community-garden-hero.jpg");
	});

	it("keeps localPath when no r2 key exists", () => {
		const url = resolveMediaUrl(
			{ ...sampleRecord, r2Key: null },
			{ mode: "deployment", r2BaseUrl: "https://cdn.example.org" },
		);
		expect(url).toBe(sampleRecord.localPath);
	});

	it("builds runtime media options from env defaults", () => {
		expect(getRuntimeMediaResolutionOptions()).toEqual({
			mode: "development",
			r2BaseUrl: undefined,
		});
	});

	it("switches runtime media options to deployment when an R2 base URL is configured", () => {
		expect(
			getRuntimeMediaResolutionOptions({
				runtime: { env: { PUBLIC_R2_BASE_URL: "https://cdn.example.org" } },
			} as App.Locals),
		).toEqual({
			mode: "deployment",
			r2BaseUrl: "https://cdn.example.org",
		});
	});

	it("resolves runtime media URLs with local defaults", () => {
		expect(resolveRuntimeMediaUrl(sampleRecord)).toBe(sampleRecord.localPath);
	});

	it("resolves runtime media URLs to R2 when configured through runtime bindings", () => {
		expect(
			resolveRuntimeMediaUrl(sampleRecord, {
				runtime: { env: { PUBLIC_R2_BASE_URL: "https://cdn.example.org" } },
			} as App.Locals),
		).toBe("https://cdn.example.org/images/home/community-garden-hero.jpg");
	});
});

tests/adapters/supabase-sqlite.test.ts.source:
import { mkdtemp } from "node:fs/promises";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { afterEach, describe, expect, it } from "vitest";

import { createAstropressSupabaseSqliteAdapter } from "../../src/adapters/supabase-sqlite";

const workspaces: string[] = [];
afterEach(() => {
	workspaces.length = 0;
});

async function freshWorkspace(): Promise<string> {
	const w = await mkdtemp(join(tmpdir(), "astropress-supabase-sqlite-"));
	workspaces.push(w);
	return w;
}

describe("createAstropressSupabaseSqliteAdapter", () => {
	it("returns an adapter with the supabase capability profile", async () => {
		const workspace = await freshWorkspace();
		const adapter = createAstropressSupabaseSqliteAdapter({
			workspaceRoot: workspace,
			dbPath: join(workspace, "supabase-admin.sqlite"),
		});
		expect(adapter).toBeDefined();
		// supabase wraps sqlite: the resulting adapter must expose the
		// supabase identity, not the bare sqlite identity.
		expect(adapter.capabilities.name).toBe("supabase");
	});

	it("accepts an empty options object via the default argument", async () => {
		// Pins the default-arg mutation: `options = {}` → `options = "Stryker was here"`.
		const adapter = createAstropressSupabaseSqliteAdapter();
		expect(adapter).toBeDefined();
		expect(adapter.capabilities.name).toBe("supabase");
	});

	it("propagates the workspaceRoot through to the wrapped sqlite adapter", async () => {
		const workspace = await freshWorkspace();
		const adapter = createAstropressSupabaseSqliteAdapter({
			workspaceRoot: workspace,
		});
		// The supabase wrapper exposes the inner sqlite adapter via the
		// capability profile; both should agree the adapter is set up.
		expect(adapter.capabilities.database).toBe(true);
	});

	it("end-to-end: sign-in works (proves backingAdapter actually wires sqlite)", async () => {
		// Pins the ObjectLiteral mutation that drops the backingAdapter:
		// without sqlite underneath, signIn would not resolve a user record.
		const workspace = await freshWorkspace();
		const adapter = createAstropressSupabaseSqliteAdapter({
			workspaceRoot: workspace,
			dbPath: join(workspace, "supabase-admin.sqlite"),
		});
		const user = await adapter.auth.signIn("admin@example.com", "password");
		// The sqlite-backed signIn returns an admin user envelope shaped
		// { id, email, isAdmin }. The hosted-API path either throws at
		// config-read time (no SUPABASE_URL) or resolves over fetch — either
		// way it cannot produce this exact local-sqlite shape with the seed
		// admin's email and admin role flag.
		expect(user).toMatchObject({
			email: "admin@example.com",
			isAdmin: true,
		});
		expect(typeof user?.id).toBe("string");
		// Distinguishes the sqlite-backed signIn from the in-memory fallback:
		// sqlite returns a generated session id, while the default in-memory
		// auth store always returns the seed user's literal id "admin-1".
		// This kills the ObjectLiteral mutation that drops backingAdapter.
		expect(user?.id).not.toBe("admin-1");
	});
});

tests/flash-d1.test.ts.source:
// Behavioral + mutation-coverage tests for the D1 flash store
// (src/sqlite-runtime/flash-d1.ts), exercised through the SqliteBackedD1Database
// fixture. The D1 sibling must behave identically to the sqlite store on every
// host that provides a D1 binding — same single-use + expiry guarantees that
// make the opaque `flash=<id>` redirect safe. See #113/#115/#133.
import { describe, expect, it, vi } from "vitest";

import { createD1FlashStore } from "../src/sqlite-runtime/flash-d1.js";
import { makeDb } from "./helpers/make-db.js";
import { SqliteBackedD1Database } from "./helpers/provider-test-fixtures.js";

function makeStore() {
	const db = makeDb();
	const d1 = new SqliteBackedD1Database(db);
	return { db, store: createD1FlashStore(d1) };
}

describe("createD1FlashStore", () => {
	it("put then consume returns the payload exactly once", async () => {
		const { store } = makeStore();
		const { id } = await store.put("d1-secret");
		expect(id).toMatch(/^flash_[0-9a-f]{36}$/);
		expect(await store.consume(id)).toBe("d1-secret");
		expect(await store.consume(id)).toBeNull();
	});

	it("consume deletes the row (no residue)", async () => {
		const { db, store } = makeStore();
		const { id } = await store.put("gone");
		await store.consume(id);
		expect(db.prepare("SELECT id FROM admin_flash WHERE id = ?").get(id)).toBeUndefined();
	});

	it("unknown id returns null", async () => {
		const { store } = makeStore();
		expect(await store.consume("flash_nope")).toBeNull();
	});

	it("expired entry is not readable and is deleted on read", async () => {
		const { db, store } = makeStore();
		const { id } = await store.put("stale", -1);
		expect(await store.consume(id)).toBeNull();
		expect(db.prepare("SELECT id FROM admin_flash WHERE id = ?").get(id)).toBeUndefined();
	});

	it("put sweeps expired rows", async () => {
		const { db, store } = makeStore();
		await store.put("old", -1);
		await store.put("fresh");
		const remaining = db.prepare("SELECT payload FROM admin_flash").all() as Array<{
			payload: string;
		}>;
		expect(remaining.map((r) => r.payload)).toEqual(["fresh"]);
	});

	it("treats an entry whose expiry equals the current instant as expired (boundary: <=)", async () => {
		const fixed = 1_700_000_000_000;
		const spy = vi.spyOn(Date, "now").mockReturnValue(fixed);
		try {
			const { db, store } = makeStore();
			const { id } = await store.put("edge", 0); // expires_at_ms = fixed
			expect(await store.consume(id)).toBeNull();
			expect(db.prepare("SELECT id FROM admin_flash WHERE id = ?").get(id)).toBeUndefined();
		} finally {
			spy.mockRestore();
		}
	});

	it("round-trips a JSON payload (webhook verification bundle shape)", async () => {
		const { store } = makeStore();
		const payload = JSON.stringify({ algorithm: "ml-dsa-65", publicKey: "abc123" });
		const { id } = await store.put(payload);
		expect(JSON.parse((await store.consume(id)) ?? "")).toEqual({
			algorithm: "ml-dsa-65",
			publicKey: "abc123",
		});
	});
});

tests/integrations/oauth/registry.test.t.source:
import { afterEach, describe, expect, it } from "vitest";

import {
	_resetOAuthRegistryForTests,
	getOAuthProvider,
	listOAuthProviders,
	OAuthRegistryError,
	registerOAuthProvider,
} from "../../../src/integrations/oauth/registry";

const GITHUB = {
	id: "github",
	domain: "deploy-hooks" as const,
	label: "GitHub",
	authorizationUrl: "https://github.com/login/oauth/authorize",
	tokenUrl: "https://github.com/login/oauth/access_token",
	scopes: ["repo:status", "read:org"] as const,
	clientIdEnv: "GITHUB_OAUTH_CLIENT_ID",
	clientSecretEnv: "GITHUB_OAUTH_CLIENT_SECRET",
	redirectPath: "/ap-admin/oauth/callback/github",
};

afterEach(() => _resetOAuthRegistryForTests());

describe("registerOAuthProvider", () => {
	it("registers and returns the same definition", () => {
		const r = registerOAuthProvider({ ...GITHUB });
		expect(r).toEqual(GITHUB);
	});

	it("getOAuthProvider returns the registered definition for matching (domain, id)", () => {
		registerOAuthProvider({ ...GITHUB });
		expect(getOAuthProvider("deploy-hooks", "github")).toEqual(GITHUB);
	});

	it("getOAuthProvider returns undefined for the wrong domain even if id matches", () => {
		registerOAuthProvider({ ...GITHUB });
		expect(getOAuthProvider("newsletter", "github")).toBeUndefined();
	});

	it("getOAuthProvider returns undefined for the wrong id even if domain matches", () => {
		registerOAuthProvider({ ...GITHUB });
		expect(getOAuthProvider("deploy-hooks", "gitlab")).toBeUndefined();
	});

	it("rejects duplicate (domain, id) pairs with DUPLICATE_PROVIDER", () => {
		registerOAuthProvider({ ...GITHUB });
		let caught: unknown;
		try {
			registerOAuthProvider({ ...GITHUB });
		} catch (e) {
			caught = e;
		}
		expect(caught).toBeInstanceOf(OAuthRegistryError);
		const err = caught as OAuthRegistryError;
		expect(err.name).toBe("OAuthRegistryError");
		expect(err.code).toBe("DUPLICATE_PROVIDER");
		expect(err.message).toContain("github");
		expect(err.message).toContain("deploy-hooks");
		expect(err.message).toContain("already registered");
	});

	it("allows the same providerId across different domains", () => {
		registerOAuthProvider({ ...GITHUB });
		expect(() => registerOAuthProvider({ ...GITHUB, domain: "newsletter" })).not.toThrow();
	});

	it("listOAuthProviders is domain-scoped", () => {
		registerOAuthProvider({ ...GITHUB });
		registerOAuthProvider({ ...GITHUB, id: "gitlab" });
		registerOAuthProvider({ ...GITHUB, domain: "newsletter", id: "mailchimp" });
		const deploy = listOAuthProviders("deploy-hooks");
		expect(deploy.map((p) => p.id).sort()).toEqual(["github", "gitlab"]);
		const newsletter = listOAuthProviders("newsletter");
		expect(newsletter.map((p) => p.id)).toEqual(["mailchimp"]);
	});

	it("listOAuthProviders returns an empty array for an unregistered domain", () => {
		expect(listOAuthProviders("analytics")).toEqual([]);
	});
});

tests/crypto-utils.test.ts.source:
import { describe, expect, it } from "vitest";
import { createKmacDigest } from "../src/crypto-primitives.js";
import { createSessionTokenDigest, hashPassword, verifyPassword } from "../src/crypto-utils.js";

describe("session token digest", () => {
	it("produces a deterministic hex digest that does not equal the raw token", async () => {
		const token = "session-token";
		const secret = "replace-with-a-long-random-session-secret";

		const first = await createSessionTokenDigest(token, secret);
		const second = await createSessionTokenDigest(token, secret);

		expect(first).toBe(second);
		expect(first).not.toBe(token);
		expect(first).toMatch(/^[a-f0-9]{64}$/);
	});

	it("matches createKmacDigest invoked with the documented 'session-token' purpose tag", async () => {
		// Pins the purpose-tag string literal: any other value (including "")
		// produces a different KMAC digest under domain separation.
		const digest = await createSessionTokenDigest("the-token", "the-secret");
		const expected = createKmacDigest("the-token", "the-secret", "session-token");
		expect(digest).toBe(expected);
	});

	it("differs from a digest computed under a different purpose tag", async () => {
		const digest = await createSessionTokenDigest("t", "s");
		expect(digest).not.toBe(createKmacDigest("t", "s", ""));
		expect(digest).not.toBe(createKmacDigest("t", "s", "other-purpose"));
	});
});

describe("hashPassword / verifyPassword", () => {
	it("verifies a freshly hashed password", { timeout: 60_000 }, async () => {
		const hash = await hashPassword("correct-horse-battery");
		expect(await verifyPassword("correct-horse-battery", hash)).toBe(true);
		expect(await verifyPassword("wrong-password", hash)).toBe(false);
	});

	it("returns false for a malformed hash (no dollar-sign separators)", async () => {
		expect(await verifyPassword("password", "not-a-valid-hash")).toBe(false);
	});

	it("returns false when hash parts are empty (missing iterations)", async () => {
		expect(await verifyPassword("password", "$$")).toBe(false);
	});

	it("returns false when the stored hash has a truncated hash segment (length mismatch triggers constantTimeEqual short-circuit)", async () => {
		// Build a real hash then corrupt the third segment to a shorter base64
		const real = await hashPassword("password");
		const [iter, salt] = real.split("$");
		const corrupted = `${iter}$${salt}$YWJj`; // "abc" in base64 — much shorter than 64-byte hash
		expect(await verifyPassword("password", corrupted)).toBe(false);
	});

	it("returns false when base64 decode throws (catch branch)", async () => {
		// A stored hash where base64 decoding the salt would throw (invalid base64 chars)
		expect(await verifyPassword("password", "100000$!!!invalid!!!$aaaa")).toBe(false);
	});
});

