import { describe, expect, it } from "vitest";

import { resolveAnalyticsStats } from "../../../src/integrations/resolvers/analytics-stats-resolver";

const REG = {
	host: "https://plausible.io",
	siteId: "example.com",
	apiKey: "plausible-token",
};

describe("resolveAnalyticsStats", () => {
	it("returns plausible kind with all fields when registry is fully populated", () => {
		expect(resolveAnalyticsStats({ registry: REG })).toEqual({
			kind: "plausible",
			host: "https://plausible.io",
			siteId: "example.com",
			apiKey: "plausible-token",
		});
	});

	it("returns kind: 'none' when registry is null", () => {
		expect(resolveAnalyticsStats({ registry: null })).toEqual({ kind: "none" });
	});

	it("returns kind: 'none' when registry is undefined (input is empty)", () => {
		expect(resolveAnalyticsStats({})).toEqual({ kind: "none" });
	});

	it("returns kind: 'none' when host is empty", () => {
		expect(resolveAnalyticsStats({ registry: { ...REG, host: "" } })).toEqual({
			kind: "none",
		});
	});

	it("returns kind: 'none' when siteId is empty", () => {
		expect(resolveAnalyticsStats({ registry: { ...REG, siteId: "" } })).toEqual({ kind: "none" });
	});

	it("returns kind: 'none' when apiKey is empty", () => {
		expect(resolveAnalyticsStats({ registry: { ...REG, apiKey: "" } })).toEqual({ kind: "none" });
	});

	it("propagates the registry's host verbatim (does not normalize trailing slash)", () => {
		const r = resolveAnalyticsStats({
			registry: { ...REG, host: "https://stats.example.com/" },
		});
		expect(r).toMatchObject({ host: "https://stats.example.com/" });
	});

	it("propagates the registry's siteId verbatim (no URL-decoding etc.)", () => {
		const r = resolveAnalyticsStats({
			registry: { ...REG, siteId: "team/site:prod" },
		});
		expect(r).toMatchObject({ siteId: "team/site:prod" });
	});

	it("propagates the registry's apiKey verbatim (no trim)", () => {
		const r = resolveAnalyticsStats({
			registry: { ...REG, apiKey: "  pad  " },
		});
		expect(r).toMatchObject({ apiKey: "  pad  " });
	});
});

tests/integrations/oauth/replay.test.ts.source:
// Behavioral test for OAuth state-nonce replay protection
// (src/integrations/oauth/replay.ts). Proves the property #122 requires:
// the first callback for a nonce proceeds, every replay of the same nonce is
// rejected — exercised against a real D1-backed rate-limit window.
import { describe, expect, it } from "vitest";

import {
	consumeOAuthStateNonce,
	OAUTH_NONCE_RATE_KEY_PREFIX,
} from "../../../src/integrations/oauth/replay.js";
import { makeDb } from "../../helpers/make-db.js";
import { makeLocals } from "../../helpers/make-locals.js";

describe("consumeOAuthStateNonce", () => {
	it("allows the first use of a nonce and rejects every replay", async () => {
		const locals = makeLocals(makeDb());
		const nonce = "abc123def456";

		expect(await consumeOAuthStateNonce(locals, nonce)).toBe(true);
		expect(await consumeOAuthStateNonce(locals, nonce)).toBe(false);
		expect(await consumeOAuthStateNonce(locals, nonce)).toBe(false);
	});

	it("treats distinct nonces independently", async () => {
		const locals = makeLocals(makeDb());
		expect(await consumeOAuthStateNonce(locals, "nonce-a")).toBe(true);
		expect(await consumeOAuthStateNonce(locals, "nonce-b")).toBe(true);
		expect(await consumeOAuthStateNonce(locals, "nonce-a")).toBe(false);
	});

	it("records the nonce under the namespaced rate-limit key", async () => {
		const db = makeDb();
		const locals = makeLocals(db);
		await consumeOAuthStateNonce(locals, "keycheck");
		const row = db
			.prepare("SELECT key FROM rate_limits WHERE key = ?")
			.get(`${OAUTH_NONCE_RATE_KEY_PREFIX}keycheck`) as { key: string } | undefined;
		expect(row?.key).toBe(`${OAUTH_NONCE_RATE_KEY_PREFIX}keycheck`);
	});

	it("re-uses across a fresh window are still rejected within TTL", async () => {
		const locals = makeLocals(makeDb());
		// A very long TTL keeps the window open, so a replay stays blocked.
		expect(await consumeOAuthStateNonce(locals, "ttl", 60_000)).toBe(true);
		expect(await consumeOAuthStateNonce(locals, "ttl", 60_000)).toBe(false);
	});
});

