	it("Webhook non-ok log message includes slug + status + body (pins L58 template)", async () => {
		const { fetch } = makeFetchMock(502, "bad-gateway-body");
		await purgeCdnCacheForResolved(
			"hook-slug",
			{ kind: "webhook", url: "https://x", source: "config" },
