import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";

import {
	buildPlausibleAuthHeader,
	buildPlausibleSiteUrl,
	PLAUSIBLE_FIELDS,
	PlausibleVerifyError,
	registerPlausible,
	verifyPlausible,
} from "../../../src/integrations/providers/plausible";
import { _resetRegistryForTests, getProvider } from "../../../src/integrations/registry";

interface CapturedCall {
	url: string;
	method: string | undefined;
	authorization: string | null;
	signalIs: AbortSignal | undefined;
}

function makeFetchMock(response: { status: number }): {
	fetch: typeof fetch;
	calls: CapturedCall[];
} {
	const calls: CapturedCall[] = [];
	const f: typeof fetch = async (input, init) => {
		const url = typeof input === "string" ? input : input.toString();
		const headers =
			init?.headers instanceof Headers
				? init.headers
				: new Headers((init?.headers as Record<string, string>) ?? {});
		calls.push({
			url,
			method: init?.method,
			authorization: headers.get("authorization"),
			signalIs: init?.signal ?? undefined,
		});
		return new Response(null, { status: response.status });
	};
	return { fetch: f, calls };
}

const FIELDS = {
	host: "https://plausible.io",
	siteId: "example.com",
	apiKey: "plausible-token-xyz",
};

afterEach(() => {
	_resetRegistryForTests();
});

describe("PLAUSIBLE_FIELDS schema", () => {
	it("accepts a valid host/siteId/apiKey triple", () => {
		expect(PLAUSIBLE_FIELDS.parse(FIELDS)).toEqual(FIELDS);
	});

	it("rejects a non-URL host", () => {
		expect(PLAUSIBLE_FIELDS.safeParse({ ...FIELDS, host: "plausible.io" }).success).toBe(false);
	});

	it("rejects an empty siteId", () => {
		expect(PLAUSIBLE_FIELDS.safeParse({ ...FIELDS, siteId: "" }).success).toBe(false);
	});

	it("rejects an empty apiKey", () => {
		expect(PLAUSIBLE_FIELDS.safeParse({ ...FIELDS, apiKey: "" }).success).toBe(false);
	});
});

describe("buildPlausibleSiteUrl", () => {
	it("appends /api/v1/sites/{siteId} to a bare-origin host", () => {
		expect(buildPlausibleSiteUrl("https://plausible.io", "example.com")).toBe(
			"https://plausible.io/api/v1/sites/example.com",
		);
	});

	it("URL-encodes a siteId that contains reserved characters", () => {
		// `:` and `/` in a siteId would otherwise change the URL path
		// shape; encodeURIComponent renders them safe.
		expect(buildPlausibleSiteUrl("https://plausible.io", "team/site:prod")).toBe(
			"https://plausible.io/api/v1/sites/team%2Fsite%3Aprod",
		);
	});

	it("works against a self-hosted host with a trailing slash", () => {
		expect(buildPlausibleSiteUrl("https://stats.example.com/", "example.com")).toBe(
			"https://stats.example.com/api/v1/sites/example.com",
		);
	});
});

describe("buildPlausibleAuthHeader", () => {
	it("prefixes the token with 'Bearer '", () => {
		expect(buildPlausibleAuthHeader("abc")).toBe("Bearer abc");
	});

	it("does not mutate or trim the token", () => {
		// Pinning a token with surrounding whitespace catches a mutant
		// that would helpfully .trim() and accidentally drop a real
		// trailing-whitespace key configured by the operator.
		expect(buildPlausibleAuthHeader("  abc  ")).toBe("Bearer   abc  ");
	});
});

describe("verifyPlausible", () => {
	let signal: AbortSignal;

	beforeEach(() => {
		signal = new AbortController().signal;
	});

	it("resolves on 200 OK", async () => {
		const { fetch, calls } = makeFetchMock({ status: 200 });
		await expect(verifyPlausible(FIELDS, { signal }, { fetch })).resolves.toBeUndefined();
		expect(calls).toHaveLength(1);
	});

	it("uses GET method (mutator-killer for the literal 'GET')", async () => {
		const { fetch, calls } = makeFetchMock({ status: 200 });
		await verifyPlausible(FIELDS, { signal }, { fetch });
		expect(calls[0].method).toBe("GET");
	});

	it("hits the constructed URL ({host}/api/v1/sites/{siteId})", async () => {
		const { fetch, calls } = makeFetchMock({ status: 200 });
		await verifyPlausible(FIELDS, { signal }, { fetch });
		expect(calls[0].url).toBe("https://plausible.io/api/v1/sites/example.com");
	});

	it("attaches Bearer auth header built from apiKey", async () => {
		const { fetch, calls } = makeFetchMock({ status: 200 });
		await verifyPlausible(FIELDS, { signal }, { fetch });
		expect(calls[0].authorization).toBe("Bearer plausible-token-xyz");
	});

	it("forwards the AbortSignal so connect-flow's timeout aborts the fetch", async () => {
		const { fetch, calls } = makeFetchMock({ status: 200 });
		await verifyPlausible(FIELDS, { signal }, { fetch });
		expect(calls[0].signalIs).toBe(signal);
	});

	it("throws AUTH_REJECTED on 401", async () => {
		const { fetch } = makeFetchMock({ status: 401 });
		await expect(verifyPlausible(FIELDS, { signal }, { fetch })).rejects.toMatchObject({
			code: "INTEGRATION_AUTH_REJECTED",
		});
	});

	it("throws AUTH_REJECTED on 403 (token-without-site-scope)", async () => {
		const { fetch } = makeFetchMock({ status: 403 });
		await expect(verifyPlausible(FIELDS, { signal }, { fetch })).rejects.toMatchObject({
			code: "INTEGRATION_AUTH_REJECTED",
		});
	});

	it("throws NOT_FOUND on 404 (distinct from AUTH_REJECTED)", async () => {
		const { fetch } = makeFetchMock({ status: 404 });
		await expect(verifyPlausible(FIELDS, { signal }, { fetch })).rejects.toMatchObject({
			code: "INTEGRATION_NOT_FOUND",
		});
	});

	it("throws RATE_LIMITED on 429 (distinct from VERIFY_FAILED)", async () => {
		const { fetch } = makeFetchMock({ status: 429 });
		await expect(verifyPlausible(FIELDS, { signal }, { fetch })).rejects.toMatchObject({
			code: "INTEGRATION_RATE_LIMITED",
		});
	});

	it("throws VERIFY_FAILED on 500", async () => {
		const { fetch } = makeFetchMock({ status: 500 });
		await expect(verifyPlausible(FIELDS, { signal }, { fetch })).rejects.toMatchObject({
			code: "INTEGRATION_VERIFY_FAILED",
		});
	});

	it("throws VERIFY_FAILED on 400 (4xx that isn't 401/403/404/429)", async () => {
		const { fetch } = makeFetchMock({ status: 400 });
		await expect(verifyPlausible(FIELDS, { signal }, { fetch })).rejects.toMatchObject({
			code: "INTEGRATION_VERIFY_FAILED",
		});
	});

	it("PlausibleVerifyError subclasses Error and carries the typed code", async () => {
		const { fetch } = makeFetchMock({ status: 403 });
		try {
			await verifyPlausible(FIELDS, { signal }, { fetch });
			throw new Error("expected verify to throw");
		} catch (err) {
			expect(err).toBeInstanceOf(PlausibleVerifyError);
			expect(err).toBeInstanceOf(Error);
			expect((err as PlausibleVerifyError).code).toBe("INTEGRATION_AUTH_REJECTED");
		}
	});

	it("falls back to global fetch when deps.fetch is omitted", async () => {
		const stub = vi
			.spyOn(globalThis, "fetch")
			.mockResolvedValue(new Response(null, { status: 200 }));
		try {
			await expect(verifyPlausible(FIELDS, { signal })).resolves.toBeUndefined();
			expect(stub).toHaveBeenCalledTimes(1);
		} finally {
			stub.mockRestore();
		}
	});
});

describe("registerPlausible", () => {
	it("registers under analytics with id 'plausible' and label 'Plausible'", () => {
		const entry = registerPlausible();
		expect(entry.domain).toBe("analytics");
		expect(entry.id).toBe("plausible");
		expect(entry.label).toBe("Plausible");
		const looked = getProvider("analytics", "plausible");
		expect(looked?.label).toBe("Plausible");
	});

	it("registers PLAUSIBLE_FIELDS schema (rejects an invalid payload)", () => {
		registerPlausible();
		const provider = getProvider("analytics", "plausible");
		expect(provider?.fields.safeParse({ host: "x" }).success).toBe(false);
	});

	it("wires verifyPlausible so connect-flow gets a callable verify", () => {
		registerPlausible();
		const provider = getProvider("analytics", "plausible");
		expect(typeof provider?.verify).toBe("function");
	});

	it("wires defaultErrorCode to AUTH_REJECTED (Plausible's most common verify failure)", () => {
		registerPlausible();
		const provider = getProvider("analytics", "plausible");
		expect(provider?.defaultErrorCode).toBe("INTEGRATION_AUTH_REJECTED");
	});
});

tests/sqlite-bootstrap-helpers.test.ts.source:
import { mkdtempSync, rmSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";

import { checkpointSqliteWal, loadSqliteDatabase } from "../src/sqlite-bootstrap-helpers";

// A fully controllable stand-in for the `bun:sqlite` Database class. Setting
// `globalThis.Bun` routes loadSqliteDatabase() through the Bun branch so tests
// can drive checkpointSqliteWal's database interactions deterministically.
const { fakeBunDatabase, bunDbState } = vi.hoisted(() => {
	const bunDbState = {
		// Value returned by `PRAGMA wal_checkpoint(TRUNCATE)`.get()
		pragmaRow: { log: 0, checkpointed: 1 } as { log: number; checkpointed: number } | null,
		throwOnConstruct: false,
		// When true, the `bun:sqlite` mock factory throws — making the dynamic
		// import (and therefore loadSqliteDatabase) reject.
		importThrows: false,
		closeCalls: 0,
	};
	class FakeBunDatabase {
		constructor(public readonly filename: string) {
			if (bunDbState.throwOnConstruct) {
				throw new Error(`cannot open ${filename}`);
			}
		}
		prepare(_sql: string) {
			return {
				get: () => bunDbState.pragmaRow,
				run: () => ({}),
				all: () => [],
			};
		}
		exec() {}
		close() {
			bunDbState.closeCalls += 1;
		}
	}
	return { fakeBunDatabase: FakeBunDatabase, bunDbState };
});

vi.mock("bun:sqlite", () => ({
	// A getter so each access can be toggled to throw — accessing `m.Database`
	// inside loadSqliteDatabase then makes that function's promise reject.
	get Database() {
		if (bunDbState.importThrows) {
			throw new Error("bun:sqlite Database unavailable");
		}
		return fakeBunDatabase;
	},
}));

let testRoot: string;

beforeEach(() => {
	testRoot = mkdtempSync(join(tmpdir(), "astropress-helpers-test-"));
	bunDbState.pragmaRow = { log: 0, checkpointed: 1 };
	bunDbState.throwOnConstruct = false;
	bunDbState.importThrows = false;
	bunDbState.closeCalls = 0;
});

afterEach(() => {
	rmSync(testRoot, { recursive: true, force: true });
	delete (globalThis as { Bun?: unknown }).Bun;
	vi.resetModules();
});

describe("loadSqliteDatabase", () => {
	it("returns a constructor that can open an in-memory database", async () => {
		const DbClass = await loadSqliteDatabase();
		const db = new DbClass(":memory:");
		db.exec("CREATE TABLE t (id INTEGER PRIMARY KEY)");
		db.prepare("INSERT INTO t VALUES (1)").run();
		const row = db.prepare("SELECT id FROM t").get() as { id: number };
		expect(row.id).toBe(1);
		db.close();
	});

	it("returns the node:sqlite DatabaseSync constructor when not running under Bun", async () => {
		// Pins the node branch: a non-Bun runtime must resolve to node:sqlite's
		// DatabaseSync, never the bun:sqlite stub.
		expect("Bun" in globalThis).toBe(false);
		const DbClass = await loadSqliteDatabase();
		expect(DbClass).not.toBe(fakeBunDatabase);
		expect(DbClass.name).toBe("DatabaseSync");
	});

	it("returns the bun:sqlite Database constructor when running under Bun", async () => {
		// Pins the `"Bun" in globalThis` guard and the `bun:sqlite` import: with
		// Bun present, loadSqliteDatabase must resolve to bun:sqlite's Database.
		(globalThis as { Bun?: unknown }).Bun = {};
		const DbClass = await loadSqliteDatabase();
		expect(DbClass).toBe(fakeBunDatabase);
	});
});

describe("checkpointSqliteWal", () => {
	it("returns true and emits no warning for a real WAL-mode SQLite file", async () => {
		const DbClass = await loadSqliteDatabase();
		const dbPath = join(testRoot, "real.sqlite");

		// Create a real SQLite DB in WAL mode with some data
		const db = new DbClass(dbPath);
		db.prepare("PRAGMA journal_mode = WAL").get();
		db.exec("CREATE TABLE items (id INTEGER PRIMARY KEY, val TEXT)");
		db.prepare("INSERT INTO items VALUES (1, 'hello')").run();
		db.close();

		const warnings: string[] = [];
		const result = await checkpointSqliteWal(dbPath, (msg) => warnings.push(msg));

		expect(result).toBe(true);
		expect(warnings).toHaveLength(0);
	});

	it("returns false and warns when the file is not a valid SQLite database", async () => {
		const badPath = join(testRoot, "bad.sqlite");
		writeFileSync(badPath, "this is not sqlite", "utf8");

		const warnings: string[] = [];
		const result = await checkpointSqliteWal(badPath, (msg) => warnings.push(msg));

		expect(result).toBe(false);
		expect(warnings.length).toBeGreaterThan(0);
		expect(warnings[0]).toContain("bad.sqlite");
	});

	it("returns false (not a rejection) when the driver constructor itself throws on an unopenable path", async () => {
		// Path under a non-existent directory makes node:sqlite throw inside
		// `new DatabaseSync(path)` synchronously, leaving `db` undefined inside
		// the checkpoint helper. The finally block must still resolve cleanly —
		// `db?.close()`'s optional chain is load-bearing here.
		const unopenablePath = join(testRoot, "no-such-dir", "db.sqlite");

		const warnings: string[] = [];
		await expect(checkpointSqliteWal(unopenablePath, (msg) => warnings.push(msg))).resolves.toBe(
			false,
		);
		expect(warnings.length).toBeGreaterThan(0);
		expect(warnings[0]).toContain("WAL checkpoint failed");
	});

	it("warns and returns false when loadSqliteDatabase rejects", async () => {
		// Drives the first catch block: with Bun present but `bun:sqlite`'s
		// Database export unresolvable, loadSqliteDatabase rejects and
		// checkpointSqliteWal must emit the "checkpoint skipped" warning.
		bunDbState.importThrows = true;
		(globalThis as { Bun?: unknown }).Bun = {};

		const warnings: string[] = [];
		const result = await checkpointSqliteWal("/tmp/skipme.sqlite", (msg) => warnings.push(msg));

		expect(result).toBe(false);
		expect(warnings).toHaveLength(1);
		expect(warnings[0]).toContain("SQLite WAL checkpoint skipped for /tmp/skipme.sqlite");
	});

	it("returns false without warning when the WAL is not fully flushed (log > 0)", async () => {
		// Pins `row.log === 0`: a non-zero log page count means the checkpoint
		// did not fully truncate, so the helper must report false — and must NOT
		// warn (no error occurred, the WAL simply wasn't fully flushed).
		bunDbState.pragmaRow = { log: 3, checkpointed: 0 };
		(globalThis as { Bun?: unknown }).Bun = {};

		const warnings: string[] = [];
		const result = await checkpointSqliteWal("/tmp/partial.sqlite", (msg) => warnings.push(msg));

		expect(result).toBe(false);
		expect(warnings).toHaveLength(0);
	});

	it("returns false without warning when the checkpoint pragma yields no row", async () => {
		// Pins `row != null`: a null pragma result must short-circuit to false
		// without dereferencing `row.log` (which would throw and warn).
		bunDbState.pragmaRow = null;
		(globalThis as { Bun?: unknown }).Bun = {};

		const warnings: string[] = [];
		const result = await checkpointSqliteWal("/tmp/norow.sqlite", (msg) => warnings.push(msg));

		expect(result).toBe(false);
		expect(warnings).toHaveLength(0);
	});

	it("returns true when the WAL is fully flushed (log === 0)", async () => {
		bunDbState.pragmaRow = { log: 0, checkpointed: 5 };
		(globalThis as { Bun?: unknown }).Bun = {};

		const warnings: string[] = [];
		const result = await checkpointSqliteWal("/tmp/clean.sqlite", (msg) => warnings.push(msg));

		expect(result).toBe(true);
		expect(warnings).toHaveLength(0);
	});

	it("closes the database in the finally block after a successful checkpoint", async () => {
		bunDbState.pragmaRow = { log: 0, checkpointed: 1 };
		(globalThis as { Bun?: unknown }).Bun = {};

		await checkpointSqliteWal("/tmp/closeme.sqlite", () => {});

		expect(bunDbState.closeCalls).toBe(1);
	});
});

tests/plugin-api.test.ts.source:
import { describe, expect, it } from "vitest";
import type { AstropressPlugin } from "../src/config.js";
import {
	dispatchPluginContentEvent,
	dispatchPluginMediaEvent,
	peekCmsConfig,
	registerCms,
} from "../src/config.js";

function makeMinimalConfig(plugins?: AstropressPlugin[]) {
	return {
		templateKeys: ["home"],
		siteUrl: "https://example.com",
		seedPages: [],
		archives: [],
		translationStatus: [],
		plugins,
	};
}

describe("AstropressPlugin API", () => {
	it("dispatchPluginContentEvent calls onContentSave on registered plugins", async () => {
		const events: string[] = [];
		const plugin: AstropressPlugin = {
			name: "test-plugin",
			onContentSave: ({ slug }) => {
				events.push(`save:${slug}`);
			},
		};
		registerCms(makeMinimalConfig([plugin]));

		await dispatchPluginContentEvent("onContentSave", {
			slug: "my-post",
			kind: "post",
			status: "draft",
			actor: "admin@example.com",
		});

		expect(events).toEqual(["save:my-post"]);
	});

	it("dispatchPluginContentEvent calls onContentPublish only for published status", async () => {
		const events: string[] = [];
		const plugin: AstropressPlugin = {
			name: "publish-plugin",
			onContentPublish: ({ slug }) => {
				events.push(`publish:${slug}`);
			},
		};
		registerCms(makeMinimalConfig([plugin]));

		await dispatchPluginContentEvent("onContentPublish", {
			slug: "my-post",
			kind: "post",
			status: "published",
			actor: "admin@example.com",
		});
		await dispatchPluginContentEvent("onContentSave", {
			slug: "draft-post",
			kind: "post",
			status: "draft",
			actor: "admin@example.com",
		});

		expect(events).toEqual(["publish:my-post"]);
	});

	it("dispatchPluginContentEvent catches errors thrown by plugin hooks", async () => {
		const errorPlugin: AstropressPlugin = {
			name: "broken-plugin",
			onContentSave: () => {
				throw new Error("plugin error");
			},
		};
		registerCms(makeMinimalConfig([errorPlugin]));

		// Should not throw
		await expect(
			dispatchPluginContentEvent("onContentSave", {
				slug: "post",
				kind: "post",
				status: "draft",
				actor: "admin@example.com",
			}),
		).resolves.toBeUndefined();
	});

	it("dispatchPluginContentEvent is a no-op when no plugins are registered", async () => {
		registerCms(makeMinimalConfig([]));
		await expect(
			dispatchPluginContentEvent("onContentSave", {
				slug: "post",
				kind: "post",
				status: "draft",
				actor: "admin@example.com",
			}),
		).resolves.toBeUndefined();
	});

	it("dispatchPluginMediaEvent calls onMediaUpload on registered plugins", async () => {
		const uploads: string[] = [];
		const plugin: AstropressPlugin = {
			name: "media-plugin",
			onMediaUpload: ({ id, mimeType }) => {
				uploads.push(`${id}:${mimeType}`);
			},
		};
		registerCms(makeMinimalConfig([plugin]));

		await dispatchPluginMediaEvent({
			id: "asset-1",
			filename: "photo.jpg",
			mimeType: "image/jpeg",
			size: 1024,
			actor: "admin@example.com",
		});

		expect(uploads).toEqual(["asset-1:image/jpeg"]);
	});

	it("dispatchPluginMediaEvent catches errors thrown by onMediaUpload hooks", async () => {
		const brokenPlugin: AstropressPlugin = {
			name: "broken-media-plugin",
			onMediaUpload: () => {
				throw new Error("media plugin error");
			},
		};
		registerCms(makeMinimalConfig([brokenPlugin]));

		await expect(
			dispatchPluginMediaEvent({
				id: "a",
				filename: "f.jpg",
				mimeType: "image/jpeg",
				size: 0,
				actor: "x@y.com",
			}),
		).resolves.toBeUndefined();
	});

	it("plugins with navItems expose them via getCmsConfig", () => {
		const navPlugin: AstropressPlugin = {
			name: "nav-plugin",
			navItems: [{ label: "My Tool", href: "/ap-admin/my-tool" }],
		};
		registerCms(makeMinimalConfig([navPlugin]));
		const config = peekCmsConfig();
		expect(config?.plugins?.[0]?.navItems?.[0]?.label).toBe("My Tool");
	});

	it("plugin adminRoutes are stored in config and accessible via peekCmsConfig", () => {
		const routePlugin: AstropressPlugin = {
			name: "route-plugin",
			adminRoutes: [
				{
					pattern: "/ap-admin/my-plugin",
					entrypoint: "./src/pages/my-plugin-admin.astro",
				},
				{
					pattern: "/ap-admin/my-plugin/settings",
					entrypoint: "./src/pages/my-plugin-settings.astro",
				},
			],
		};
		registerCms(makeMinimalConfig([routePlugin]));
		const config = peekCmsConfig();
		const routes = config?.plugins?.[0]?.adminRoutes;
		expect(routes).toHaveLength(2);
		expect(routes?.[0]?.pattern).toBe("/ap-admin/my-plugin");
		expect(routes?.[0]?.entrypoint).toBe("./src/pages/my-plugin-admin.astro");
		expect(routes?.[1]?.pattern).toBe("/ap-admin/my-plugin/settings");
	});

	it("plugin with no adminRoutes does not break config access", () => {
		const plainPlugin: AstropressPlugin = { name: "plain-plugin" };
		registerCms(makeMinimalConfig([plainPlugin]));
		const config = peekCmsConfig();
		expect(config?.plugins?.[0]?.adminRoutes).toBeUndefined();
	});
});

describe("createSitemapPlugin", () => {
	it("source file exists and exports createSitemapPlugin", async () => {
		const { createSitemapPlugin: fn } = await import("../src/plugins/sitemap-plugin.js");
		expect(typeof fn).toBe("function");
	});

	it("returned plugin has name 'astropress-sitemap' and onContentPublish hook", async () => {
		const { createSitemapPlugin: fn } = await import("../src/plugins/sitemap-plugin.js");
		const plugin = fn();
		expect(plugin.name).toBe("astropress-sitemap");
		expect(typeof plugin.onContentPublish).toBe("function");
	});

	it("onContentPublish calls onPublish callback with slug", async () => {
		const { createSitemapPlugin: fn } = await import("../src/plugins/sitemap-plugin.js");
		const slugs: string[] = [];
		const plugin = fn({
			onPublish: (slug: string) => {
				slugs.push(slug);
			},
		});
		await plugin.onContentPublish?.({
			slug: "my-post",
			kind: "post",
			status: "published",
			actor: "admin@example.com",
		});
		expect(slugs).toEqual(["my-post"]);
	});
});

tests/admin-normalizers.test.ts.source:
import { describe, expect, it } from "vitest";

import {
	normalizeEmail,
	normalizePath,
	normalizeRedirectPath,
	parseIdList,
	serializeIdList,
	slugify,
} from "../src/admin-normalizers";

describe("normalizePath", () => {
	it("returns empty string for empty input", () => {
		expect(normalizePath("")).toBe("");
	});

	it("returns empty string for whitespace-only input", () => {
		expect(normalizePath("   ")).toBe("");
	});

	it("prepends slash when path lacks one", () => {
		expect(normalizePath("about")).toBe("/about");
	});

	it("preserves existing leading slash", () => {
		expect(normalizePath("/about")).toBe("/about");
	});

	it("trims surrounding whitespace before normalizing", () => {
		expect(normalizePath("  /about  ")).toBe("/about");
	});
});

describe("normalizeRedirectPath", () => {
	it("returns empty string for empty input", () => {
		expect(normalizeRedirectPath("")).toBe("");
	});

	it("returns empty string for whitespace-only input", () => {
		expect(normalizeRedirectPath("   ")).toBe("");
	});

	it("rejects protocol-relative URLs (open redirect vector)", () => {
		expect(normalizeRedirectPath("//evil.example.com")).toBe("");
	});

	it("rejects protocol-relative URLs with trailing whitespace trimmed first", () => {
		expect(normalizeRedirectPath("  //evil.example.com/path  ")).toBe("");
	});

	it("prepends slash to relative paths", () => {
		expect(normalizeRedirectPath("dashboard")).toBe("/dashboard");
	});

	it("preserves existing leading slash", () => {
		expect(normalizeRedirectPath("/dashboard")).toBe("/dashboard");
	});
});

describe("normalizeEmail", () => {
	it("lowercases and trims the value", () => {
		expect(normalizeEmail("  Admin@Example.COM  ")).toBe("admin@example.com");
	});
});

describe("slugify", () => {
	it("lowercases, replaces non-alphanumeric runs with hyphens, strips leading/trailing hyphens", () => {
		expect(slugify("Hello World!")).toBe("hello-world");
	});
});

describe("parseIdList", () => {
	it.each([null, undefined, ""])("returns empty array for falsy input: %s", (value) => {
		expect(parseIdList(value)).toEqual([]);
	});

	it("returns empty array for invalid JSON string", () => {
		expect(parseIdList("not-json")).toEqual([]);
	});

	it("returns empty array when JSON is a non-array value", () => {
		expect(parseIdList('{"id":1}')).toEqual([]);
	});

	it("filters out non-integer and non-positive entries", () => {
		expect(parseIdList('["a", -1, 0, 1.5, 2]')).toEqual([2]);
	});

	it("parses a valid array of positive integers", () => {
		expect(parseIdList("[1, 2, 3]")).toEqual([1, 2, 3]);
	});
});

describe("serializeIdList", () => {
	it("serializes a sorted array of positive integers", () => {
		expect(serializeIdList([3, 1, 2])).toBe("[1,2,3]");
	});

	it("filters out non-positive entries before serializing", () => {
		expect(serializeIdList([0, -1, 3, 1])).toBe("[1,3]");
	});

	it("filters out non-integer entries", () => {
		expect(serializeIdList([1.5, 2, 3])).toBe("[2,3]");
	});

	it("returns empty array for all-negative input", () => {
		expect(serializeIdList([-1, -2, -3])).toBe("[]");
	});

	it("returns empty array for empty input", () => {
		expect(serializeIdList([])).toBe("[]");
	});
});

describe("slugify — edge cases", () => {
	it("collapses consecutive non-alphanumeric characters into a single hyphen", () => {
		expect(slugify("hello  world")).toBe("hello-world");
	});

	it("strips leading hyphens from special-char prefix", () => {
		expect(slugify("!hello")).toBe("hello");
	});

	it("strips trailing hyphens from special-char suffix", () => {
		expect(slugify("hello!")).toBe("hello");
	});

	it("strips multiple consecutive trailing hyphens", () => {
		// Kills Regex mutation: -+$ → -$ (only strips one trailing hyphen)
		expect(slugify("hello!!")).toBe("hello");
	});

	it("strips multiple consecutive leading hyphens", () => {
		// Kills Regex mutation: ^-+ → ^- (only strips one leading hyphen)
		expect(slugify("!!hello")).toBe("hello");
	});

	it("strips both leading and trailing hyphens", () => {
		expect(slugify("---hello world---")).toBe("hello-world");
	});

	it("collapses internal runs of hyphens produced by adjacent special chars", () => {
		expect(slugify("hello!!world")).toBe("hello-world");
	});

	it("handles leading and trailing whitespace without explicit trim", () => {
		expect(slugify("  hello  ")).toBe("hello");
	});

	it("returns empty string for all non-alphanumeric input", () => {
		expect(slugify("!!!")).toBe("");
	});

	it("trims whitespace before processing", () => {
		expect(slugify("  hello world  ")).toBe("hello-world");
	});
});

describe("parseIdList — boundary cases", () => {
	it("filters out zero (entry > 0 not >=)", () => {
		expect(parseIdList("[0]")).toEqual([]);
	});

	it("parses mixed valid and invalid values", () => {
		expect(parseIdList("[1, 0, -5, 3]")).toEqual([1, 3]);
	});
});

describe("normalizeEmail — individual transforms", () => {
	it("lowercases without trimming when no whitespace present", () => {
		expect(normalizeEmail("ADMIN@EXAMPLE.COM")).toBe("admin@example.com");
	});

	it("trims without case-folding when already lowercase", () => {
		expect(normalizeEmail("  admin@example.com  ")).toBe("admin@example.com");
	});
});

describe("normalizePath — whitespace without slash", () => {
	it("prepends slash to a path with inner whitespace stripped", () => {
		expect(normalizePath("  about  ")).toBe("/about");
	});
});

describe("normalizeRedirectPath — additional branches", () => {
	it("rejects path that is exactly '//'", () => {
		expect(normalizeRedirectPath("//")).toBe("");
	});

	it("accepts a single slash", () => {
		expect(normalizeRedirectPath("/")).toBe("/");
	});
});

